window.PTO_EXAMPLES_SOURCES = {"examples/hello_world.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"\r\nThe simplest PyPTO program: element-wise tensor addition.\r\n\r\nConcepts introduced:\r\n  - @pl.jit decorator: function specializes on torch tensor shape/dtype, compiles, caches\r\n  - pl.at(level=pl.Level.CORE_GROUP) context: a single on-chip compute scope (load tiles, compute, store back)\r\n  - pl.Out[] marks output tensor parameters (in-place mutation)\r\n  - Tensor (global memory) vs Tile (on-chip register) types\r\n\r\nRun:  python examples/hello_world.py\r\nNext: examples/kernels/01_elementwise.py\r\n\"\"\"\r\n\r\nimport pypto.language as pl\r\nimport torch\r\nfrom pypto.runtime import RunConfig\r\n\r\n\r\n@pl.jit\r\ndef tile_add(a: pl.Tensor, b: pl.Tensor, c: pl.Out[pl.Tensor]):\r\n    with pl.at(level=pl.Level.CORE_GROUP):\r\n        tile_a = pl.load(a, [0, 0], [128, 128])\r\n        tile_b = pl.load(b, [0, 0], [128, 128])\r\n        tile_c = pl.add(tile_a, tile_b)\r\n        pl.store(tile_c, [0, 0], c)\r\n    return c\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    a = torch.full((128, 128), 2.0, dtype=torch.float32)\r\n    b = torch.full((128, 128), 3.0, dtype=torch.float32)\r\n    c = torch.zeros((128, 128), dtype=torch.float32)\r\n    tile_add(a, b, c, config=RunConfig())\r\n    expected = a + b\r\n    assert torch.allclose(c, expected, rtol=1e-5, atol=1e-5), (\r\n        f\"hello_world tile_add failed: max diff = {(c - expected).abs().max().item()}\"\r\n    )\r\n    print(\"OK\")\r\n","examples/kernels/01_elementwise.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"\r\nTile element-wise operations: add and multiply.\r\n\r\nKernels:\r\n  tile_add_128 — c = a + b  (128x128)\r\n  tile_mul_128 — c = a * b  (128x128)\r\n  tile_add_64  — c = a + b  (64x64)\r\n  tile_mul_64  — c = a * b  (64x64)\r\n\r\nConcepts introduced:\r\n  - pl.mul for element-wise multiplication\r\n  - Multiple @pl.jit kernels in one file\r\n\r\nRun:  python examples/kernels/01_elementwise.py\r\nNext: examples/kernels/02_fused_ops.py\r\n\"\"\"\r\n\r\nimport pypto.language as pl\r\nimport torch\r\nfrom pypto.runtime import RunConfig\r\n\r\n\r\n@pl.jit\r\ndef tile_add_128(a: pl.Tensor, b: pl.Tensor, c: pl.Out[pl.Tensor]):\r\n    with pl.at(level=pl.Level.CORE_GROUP):\r\n        tile_a = pl.load(a, [0, 0], [128, 128])\r\n        tile_b = pl.load(b, [0, 0], [128, 128])\r\n        tile_c = pl.add(tile_a, tile_b)\r\n        pl.store(tile_c, [0, 0], c)\r\n    return c\r\n\r\n\r\n@pl.jit\r\ndef tile_mul_128(a: pl.Tensor, b: pl.Tensor, c: pl.Out[pl.Tensor]):\r\n    with pl.at(level=pl.Level.CORE_GROUP):\r\n        tile_a = pl.load(a, [0, 0], [128, 128])\r\n        tile_b = pl.load(b, [0, 0], [128, 128])\r\n        tile_c = pl.mul(tile_a, tile_b)\r\n        pl.store(tile_c, [0, 0], c)\r\n    return c\r\n\r\n\r\n@pl.jit\r\ndef tile_add_64(a: pl.Tensor, b: pl.Tensor, c: pl.Out[pl.Tensor]):\r\n    \"\"\"Element-wise addition on 64x64 tiles.\"\"\"\r\n    with pl.at(level=pl.Level.CORE_GROUP):\r\n        tile_a = pl.load(a, [0, 0], [64, 64])\r\n        tile_b = pl.load(b, [0, 0], [64, 64])\r\n        tile_c = pl.add(tile_a, tile_b)\r\n        pl.store(tile_c, [0, 0], c)\r\n    return c\r\n\r\n\r\n@pl.jit\r\ndef tile_mul_64(a: pl.Tensor, b: pl.Tensor, c: pl.Out[pl.Tensor]):\r\n    \"\"\"Element-wise multiplication on 64x64 tiles.\"\"\"\r\n    with pl.at(level=pl.Level.CORE_GROUP):\r\n        tile_a = pl.load(a, [0, 0], [64, 64])\r\n        tile_b = pl.load(b, [0, 0], [64, 64])\r\n        tile_c = pl.mul(tile_a, tile_b)\r\n        pl.store(tile_c, [0, 0], c)\r\n    return c\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    cfg = RunConfig()\r\n\r\n    a128 = torch.full((128, 128), 2.0, dtype=torch.float32)\r\n    b128 = torch.full((128, 128), 3.0, dtype=torch.float32)\r\n    c128 = torch.zeros((128, 128), dtype=torch.float32)\r\n    tile_add_128(a128, b128, c128, config=cfg)\r\n    assert torch.allclose(c128, a128 + b128, rtol=1e-5, atol=1e-5)\r\n\r\n    c128 = torch.zeros((128, 128), dtype=torch.float32)\r\n    tile_mul_128(a128, b128, c128, config=cfg)\r\n    assert torch.allclose(c128, a128 * b128, rtol=1e-5, atol=1e-5)\r\n\r\n    a64 = torch.full((64, 64), 2.0, dtype=torch.float32)\r\n    b64 = torch.full((64, 64), 3.0, dtype=torch.float32)\r\n    c64 = torch.zeros((64, 64), dtype=torch.float32)\r\n    tile_add_64(a64, b64, c64, config=cfg)\r\n    assert torch.allclose(c64, a64 + b64, rtol=1e-5, atol=1e-5)\r\n\r\n    c64 = torch.zeros((64, 64), dtype=torch.float32)\r\n    tile_mul_64(a64, b64, c64, config=cfg)\r\n    assert torch.allclose(c64, a64 * b64, rtol=1e-5, atol=1e-5)\r\n\r\n    print(\"OK\")\r\n","examples/kernels/02_fused_ops.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"\r\nFused operations: combining multiple ops in a single InCore kernel.\r\n\r\nKernels:\r\n  fused_add_scale    — c = (a + b) * 2.0           (vector only)\r\n  fused_add_relu     — c = relu(a + b)              (vector only)\r\n  fused_matmul_bias  — c = matmul(a, b) + bias      (cube + vector)\r\n  fused_linear_relu  — y = relu(matmul(x, w) + bias) (cube + vector)\r\n\r\nConcepts introduced:\r\n  - Scalar operations: pl.mul(tile, 2.0)\r\n  - Activation functions: pl.relu\r\n  - Memory spaces: pl.MemorySpace.Mat (L1), Left (L0A), Right (L0B)\r\n  - pl.move for transferring tiles between memory spaces\r\n  - pl.matmul for cube unit matrix multiplication\r\n  - Multi-kernel orchestration: @pl.jit.incore helpers + pl.create_tensor for intermediate buffers\r\n\r\nRun:  python examples/kernels/02_fused_ops.py\r\nNext: examples/kernels/03_matmul.py\r\n\"\"\"\r\n\r\nimport pypto.language as pl\r\nimport torch\r\nfrom pypto.runtime import RunConfig\r\n\r\n\r\n@pl.jit\r\ndef fused_add_scale(a: pl.Tensor, b: pl.Tensor, c: pl.Out[pl.Tensor]):\r\n    \"\"\"Fused: load a, b -> add -> scale by 2.0 -> store c.\"\"\"\r\n    with pl.at(level=pl.Level.CORE_GROUP):\r\n        tile_a = pl.load(a, [0, 0], [128, 128])\r\n        tile_b = pl.load(b, [0, 0], [128, 128])\r\n        tile_sum = pl.add(tile_a, tile_b)\r\n        tile_c = pl.mul(tile_sum, 2.0)\r\n        pl.store(tile_c, [0, 0], c)\r\n    return c\r\n\r\n\r\n@pl.jit\r\ndef fused_add_relu(a: pl.Tensor, b: pl.Tensor, c: pl.Out[pl.Tensor]):\r\n    \"\"\"Fused: load a, b -> add -> relu -> store c.\"\"\"\r\n    with pl.at(level=pl.Level.CORE_GROUP):\r\n        tile_a = pl.load(a, [0, 0], [128, 128])\r\n        tile_b = pl.load(b, [0, 0], [128, 128])\r\n        tile_sum = pl.add(tile_a, tile_b)\r\n        tile_c = pl.relu(tile_sum)\r\n        pl.store(tile_c, [0, 0], c)\r\n    return c\r\n\r\n\r\n@pl.jit.incore\r\ndef _matmul_kernel_64x64(a: pl.Tensor, b: pl.Tensor, output: pl.Out[pl.Tensor]):\r\n    \"\"\"Cube InCore: compute a @ b and store to output.\"\"\"\r\n    tile_a_l1 = pl.load(a, [0, 0], [64, 64], target_memory=pl.MemorySpace.Mat)\r\n    tile_b_l1 = pl.load(b, [0, 0], [64, 64], target_memory=pl.MemorySpace.Mat)\r\n    tile_a_l0a = pl.move(tile_a_l1, target_memory=pl.MemorySpace.Left)\r\n    tile_b_l0b = pl.move(tile_b_l1, target_memory=pl.MemorySpace.Right)\r\n    tile_c_l0c = pl.matmul(tile_a_l0a, tile_b_l0b)\r\n    pl.store(tile_c_l0c, [0, 0], output)\r\n    return output\r\n\r\n\r\n@pl.jit.incore\r\ndef _add_bias_kernel_64x64(x: pl.Tensor, bias: pl.Tensor, output: pl.Out[pl.Tensor]):\r\n    \"\"\"Vector InCore: add bias to x and store to output.\"\"\"\r\n    tile_x = pl.load(x, [0, 0], [64, 64])\r\n    tile_bias = pl.load(bias, [0, 0], [64, 64])\r\n    tile_c = pl.add(tile_x, tile_bias)\r\n    pl.store(tile_c, [0, 0], output)\r\n    return output\r\n\r\n\r\n@pl.jit.incore\r\ndef _add_bias_relu_kernel_64x64(x: pl.Tensor, bias: pl.Tensor, output: pl.Out[pl.Tensor]):\r\n    \"\"\"Vector InCore: fused bias add and relu activation.\"\"\"\r\n    tile_x = pl.load(x, [0, 0], [64, 64])\r\n    tile_bias = pl.load(bias, [0, 0], [64, 64])\r\n    tile_biased = pl.add(tile_x, tile_bias)\r\n    tile_y = pl.relu(tile_biased)\r\n    pl.store(tile_y, [0, 0], output)\r\n    return output\r\n\r\n\r\n@pl.jit\r\ndef fused_matmul_bias(a: pl.Tensor, b: pl.Tensor, bias: pl.Tensor, c: pl.Out[pl.Tensor]):\r\n    \"\"\"Orchestrate: c = matmul(a, b) + bias\"\"\"\r\n    mm_out = pl.create_tensor([64, 64], dtype=pl.FP32)\r\n    mm_out = _matmul_kernel_64x64(a, b, mm_out)\r\n    c = _add_bias_kernel_64x64(mm_out, bias, c)\r\n    return c\r\n\r\n\r\n@pl.jit\r\ndef fused_linear_relu(x: pl.Tensor, w: pl.Tensor, bias: pl.Tensor, y: pl.Out[pl.Tensor]):\r\n    \"\"\"Orchestrate: y = relu(matmul(x, w) + bias)\"\"\"\r\n    mm_out = pl.create_tensor([64, 64], dtype=pl.FP32)\r\n    mm_out = _matmul_kernel_64x64(x, w, mm_out)\r\n    y = _add_bias_relu_kernel_64x64(mm_out, bias, y)\r\n    return y\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    cfg = RunConfig()\r\n    torch.manual_seed(0)\r\n\r\n    # fused_add_scale\r\n    a = torch.full((128, 128), 2.0, dtype=torch.float32)\r\n    b = torch.full((128, 128), 3.0, dtype=torch.float32)\r\n    c = torch.zeros((128, 128), dtype=torch.float32)\r\n    fused_add_scale(a, b, c, config=cfg)\r\n    assert torch.allclose(c, (a + b) * 2.0, rtol=1e-5, atol=1e-5)\r\n\r\n    # fused_add_relu\r\n    c = torch.zeros((128, 128), dtype=torch.float32)\r\n    fused_add_relu(a, b, c, config=cfg)\r\n    assert torch.allclose(c, torch.relu(a + b), rtol=1e-5, atol=1e-5)\r\n\r\n    # fused_matmul_bias\r\n    a64 = torch.full((64, 64), 2.0, dtype=torch.float32)\r\n    b64 = torch.full((64, 64), 3.0, dtype=torch.float32)\r\n    bias = torch.randn(64, 64, dtype=torch.float32)\r\n    c64 = torch.zeros((64, 64), dtype=torch.float32)\r\n    fused_matmul_bias(a64, b64, bias, c64, config=cfg)\r\n    assert torch.allclose(c64, torch.matmul(a64, b64) + bias, rtol=1e-3, atol=1e-3)\r\n\r\n    # fused_linear_relu\r\n    y = torch.zeros((64, 64), dtype=torch.float32)\r\n    fused_linear_relu(a64, b64, bias, y, config=cfg)\r\n    assert torch.allclose(y, torch.relu(torch.matmul(a64, b64) + bias), rtol=1e-3, atol=1e-3)\r\n\r\n    print(\"OK\")\r\n","examples/kernels/03_matmul.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"\r\nMatrix multiplication on the cube unit (64x64).\r\n\r\nKernels:\r\n  matmul_64     — full 64x64 matmul in one shot\r\n  matmul_acc_64 — K=64 split into two K=32 chunks with matmul + matmul_acc\r\n\r\nConcepts introduced:\r\n  - Memory hierarchy: GM -> Mat (L1) -> Left/Right (L0A/L0B) -> matmul -> Acc (L0C)\r\n  - pl.matmul for cube unit multiplication\r\n  - pl.matmul_acc for accumulating partial products\r\n  - K-dimension tiling for large reductions\r\n\r\nRun:  python examples/kernels/03_matmul.py\r\nNext: examples/kernels/04_concat.py\r\n\"\"\"\r\n\r\nimport pypto.language as pl\r\nimport torch\r\nfrom pypto.runtime import RunConfig\r\n\r\n\r\n@pl.jit\r\ndef matmul_64(a: pl.Tensor, b: pl.Tensor, c: pl.Out[pl.Tensor]):\r\n    with pl.at(level=pl.Level.CORE_GROUP):\r\n        tile_a_l1 = pl.load(a, [0, 0], [64, 64], target_memory=pl.MemorySpace.Mat)\r\n        tile_b_l1 = pl.load(b, [0, 0], [64, 64], target_memory=pl.MemorySpace.Mat)\r\n        tile_a_l0a = pl.move(tile_a_l1, target_memory=pl.MemorySpace.Left)\r\n        tile_b_l0b = pl.move(tile_b_l1, target_memory=pl.MemorySpace.Right)\r\n        tile_c_l0c = pl.matmul(tile_a_l0a, tile_b_l0b)\r\n        pl.store(tile_c_l0c, [0, 0], c)\r\n    return c\r\n\r\n\r\n@pl.jit\r\ndef matmul_acc_64(a: pl.Tensor, b: pl.Tensor, c: pl.Out[pl.Tensor]):\r\n    \"\"\"Matrix multiply with accumulation -- K=64 split into two K=32 chunks.\r\n\r\n    First chunk initialises L0C via ``matmul``; second chunk accumulates via\r\n    ``matmul_acc``.  The final result equals the full 64x64 matrix product.\r\n    \"\"\"\r\n    with pl.at(level=pl.Level.CORE_GROUP):\r\n        # First K-chunk: A[:,0:32] @ B[0:32,:] -- initialises L0C via matmul\r\n        tile_a0_l1 = pl.load(a, [0, 0], [64, 32], target_memory=pl.MemorySpace.Mat)\r\n        tile_b0_l1 = pl.load(b, [0, 0], [32, 64], target_memory=pl.MemorySpace.Mat)\r\n        tile_a0_l0a = pl.move(tile_a0_l1, target_memory=pl.MemorySpace.Left)\r\n        tile_b0_l0b = pl.move(tile_b0_l1, target_memory=pl.MemorySpace.Right)\r\n        acc: pl.Tile[[64, 64], pl.FP32] = pl.matmul(tile_a0_l0a, tile_b0_l0b)\r\n\r\n        # Second K-chunk: A[:,32:64] @ B[32:64,:] -- accumulates into existing L0C\r\n        tile_a1_l1 = pl.load(a, [0, 32], [64, 32], target_memory=pl.MemorySpace.Mat)\r\n        tile_b1_l1 = pl.load(b, [32, 0], [32, 64], target_memory=pl.MemorySpace.Mat)\r\n        tile_a1_l0a = pl.move(tile_a1_l1, target_memory=pl.MemorySpace.Left)\r\n        tile_b1_l0b = pl.move(tile_b1_l1, target_memory=pl.MemorySpace.Right)\r\n        acc = pl.matmul_acc(acc, tile_a1_l0a, tile_b1_l0b)\r\n\r\n        pl.store(acc, [0, 0], c)\r\n    return c\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    cfg = RunConfig()\r\n    torch.manual_seed(0)\r\n\r\n    a = torch.randn(64, 64, dtype=torch.float32)\r\n    b = torch.randn(64, 64, dtype=torch.float32)\r\n\r\n    c = torch.zeros((64, 64), dtype=torch.float32)\r\n    matmul_64(a, b, c, config=cfg)\r\n    assert torch.allclose(c, torch.matmul(a, b), rtol=1e-3, atol=1e-3)\r\n\r\n    c = torch.zeros((64, 64), dtype=torch.float32)\r\n    matmul_acc_64(a, b, c, config=cfg)\r\n    assert torch.allclose(c, torch.matmul(a, b), rtol=1e-3, atol=1e-3)\r\n\r\n    print(\"OK\")\r\n","examples/kernels/04_concat.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"\r\nTile column-wise concatenation: c[:, :16] = a, c[:, 16:] = b.\r\n\r\nKernels:\r\n  tile_concat_32x32 -- c[32,32] = concat(a[32,16], b[32,16])\r\n\r\nConcepts introduced:\r\n  - pl.concat for column-wise tile concatenation\r\n\r\nRun:  python examples/kernels/04_concat.py\r\nNext: examples/kernels/05_activation.py\r\n\"\"\"\r\n\r\nimport pypto.language as pl\r\nimport torch\r\nfrom pypto.runtime import RunConfig\r\n\r\n\r\n@pl.jit\r\ndef tile_concat_32x32(a: pl.Tensor, b: pl.Tensor, c: pl.Out[pl.Tensor]):\r\n    with pl.at(level=pl.Level.CORE_GROUP):\r\n        tile_a = pl.load(a, [0, 0], [32, 16])\r\n        tile_b = pl.load(b, [0, 0], [32, 16])\r\n        tile_out: pl.Tile[[32, 32], pl.FP32] = pl.concat(tile_a, tile_b)\r\n        pl.store(tile_out, [0, 0], c)\r\n    return c\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    cfg = RunConfig()\r\n    torch.manual_seed(0)\r\n\r\n    a = torch.randn(32, 16, dtype=torch.float32)\r\n    b = torch.randn(32, 16, dtype=torch.float32)\r\n    c = torch.zeros((32, 32), dtype=torch.float32)\r\n    tile_concat_32x32(a, b, c, config=cfg)\r\n    expected = torch.cat([a, b], dim=1)\r\n    assert torch.allclose(c, expected, rtol=1e-5, atol=1e-5)\r\n\r\n    print(\"OK\")\r\n","examples/kernels/05_activation.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"\r\nActivation functions (32x128 tiles).\r\n\r\nKernels:\r\n  silu    -- SiLU:   output = x * sigmoid(x)                    = x / (1 + exp(-x))\r\n  gelu    -- GELU:   output = x * sigmoid(1.702 * x)            (fast approximation)\r\n  swiglu  -- SwiGLU: output = gate * sigmoid(gate) * up\r\n  geglu   -- GeGLU:  output = gate * sigmoid(1.702 * gate) * up\r\n\r\nConcepts introduced:\r\n  - pl.exp, pl.recip for building sigmoid from primitives\r\n  - Chaining element-wise ops for complex activation functions\r\n  - Two-input activations (SwiGLU, GeGLU) with gate and up projections\r\n\r\nRun:  python examples/kernels/05_activation.py\r\nNext: examples/kernels/06_softmax.py\r\n\"\"\"\r\n\r\nimport pypto.language as pl\r\nimport torch\r\nfrom pypto.runtime import RunConfig\r\n\r\n\r\n@pl.jit\r\ndef silu(x: pl.Tensor, output: pl.Out[pl.Tensor]):\r\n    with pl.at(level=pl.Level.CORE_GROUP):\r\n        # SiLU(x) = x * sigmoid(x) = x / (1 + exp(-x))\r\n        tile_x = pl.load(x, [0, 0], [32, 128])\r\n        x_neg = pl.mul(tile_x, -1.0)\r\n        exp_neg = pl.exp(x_neg)\r\n        denom = pl.add(exp_neg, 1.0)\r\n        sigmoid = pl.recip(denom)\r\n        result = pl.mul(tile_x, sigmoid)\r\n        pl.store(result, [0, 0], output)\r\n    return output\r\n\r\n\r\n@pl.jit\r\ndef gelu(x: pl.Tensor, output: pl.Out[pl.Tensor]):\r\n    with pl.at(level=pl.Level.CORE_GROUP):\r\n        # GELU(x) = x * sigmoid(1.702 * x)  (fast approximation)\r\n        tile_x = pl.load(x, [0, 0], [32, 128])\r\n        x_scaled = pl.mul(tile_x, 1.702)\r\n        x_neg = pl.mul(x_scaled, -1.0)\r\n        exp_neg = pl.exp(x_neg)\r\n        denom = pl.add(exp_neg, 1.0)\r\n        sigmoid = pl.recip(denom)\r\n        result = pl.mul(tile_x, sigmoid)\r\n        pl.store(result, [0, 0], output)\r\n    return output\r\n\r\n\r\n@pl.jit\r\ndef swiglu(gate: pl.Tensor, up: pl.Tensor, output: pl.Out[pl.Tensor]):\r\n    with pl.at(level=pl.Level.CORE_GROUP):\r\n        # SwiGLU(gate, up) = Swish(gate) * up = gate * sigmoid(gate) * up\r\n        tile_gate = pl.load(gate, [0, 0], [32, 128])\r\n        tile_up = pl.load(up, [0, 0], [32, 128])\r\n        gate_neg = pl.mul(tile_gate, -1.0)\r\n        exp_neg = pl.exp(gate_neg)\r\n        denom = pl.add(exp_neg, 1.0)\r\n        sigmoid = pl.recip(denom)\r\n        swish = pl.mul(tile_gate, sigmoid)\r\n        result = pl.mul(swish, tile_up)\r\n        pl.store(result, [0, 0], output)\r\n    return output\r\n\r\n\r\n@pl.jit\r\ndef geglu(gate: pl.Tensor, up: pl.Tensor, output: pl.Out[pl.Tensor]):\r\n    with pl.at(level=pl.Level.CORE_GROUP):\r\n        # GeGLU(gate, up) = GELU(gate) * up\r\n        # GELU approximation: gate * sigmoid(1.702 * gate)\r\n        tile_gate = pl.load(gate, [0, 0], [32, 128])\r\n        tile_up = pl.load(up, [0, 0], [32, 128])\r\n        gate_scaled = pl.mul(tile_gate, 1.702)\r\n        gate_neg = pl.mul(gate_scaled, -1.0)\r\n        exp_neg = pl.exp(gate_neg)\r\n        denom = pl.add(exp_neg, 1.0)\r\n        sigmoid = pl.recip(denom)\r\n        gelu_gate = pl.mul(tile_gate, sigmoid)\r\n        result = pl.mul(gelu_gate, tile_up)\r\n        pl.store(result, [0, 0], output)\r\n    return output\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    torch.manual_seed(0)\r\n    config = RunConfig()\r\n\r\n    # SiLU\r\n    x = torch.randn(32, 128, dtype=torch.float32)\r\n    out = torch.zeros_like(x)\r\n    silu(x, out, config=config)\r\n    expected = x * torch.sigmoid(x)\r\n    assert torch.allclose(out, expected, rtol=1e-5, atol=1e-5), (\r\n        f\"silu failed: max diff = {(out - expected).abs().max().item()}\"\r\n    )\r\n\r\n    # GELU\r\n    x = torch.randn(32, 128, dtype=torch.float32)\r\n    out = torch.zeros_like(x)\r\n    gelu(x, out, config=config)\r\n    expected = x * torch.sigmoid(1.702 * x)\r\n    assert torch.allclose(out, expected, rtol=1e-5, atol=1e-5), (\r\n        f\"gelu failed: max diff = {(out - expected).abs().max().item()}\"\r\n    )\r\n\r\n    # SwiGLU\r\n    gate = torch.randn(32, 128, dtype=torch.float32)\r\n    up = torch.randn(32, 128, dtype=torch.float32)\r\n    out = torch.zeros_like(gate)\r\n    swiglu(gate, up, out, config=config)\r\n    expected = gate * torch.sigmoid(gate) * up\r\n    assert torch.allclose(out, expected, rtol=1e-5, atol=1e-5), (\r\n        f\"swiglu failed: max diff = {(out - expected).abs().max().item()}\"\r\n    )\r\n\r\n    # GeGLU\r\n    gate = torch.randn(32, 128, dtype=torch.float32)\r\n    up = torch.randn(32, 128, dtype=torch.float32)\r\n    out = torch.zeros_like(gate)\r\n    geglu(gate, up, out, config=config)\r\n    expected = gate * torch.sigmoid(1.702 * gate) * up\r\n    assert torch.allclose(out, expected, rtol=1e-5, atol=1e-5), (\r\n        f\"geglu failed: max diff = {(out - expected).abs().max().item()}\"\r\n    )\r\n\r\n    print(\"OK\")\r\n","examples/kernels/06_softmax.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"\r\nRow-wise softmax (64x64 input).\r\n\r\nFormula: output[i] = exp(a[i] - max(a[i])) / sum(exp(a[i] - max(a[i])))\r\n\r\nConcepts introduced:\r\n  - pl.create_tile for scratch tiles in a specific memory space\r\n  - Row reduction ops: pl.row_max, pl.row_sum\r\n  - Row broadcast ops: pl.row_expand_sub, pl.row_expand_div\r\n  - Numerically stable softmax algorithm\r\n\r\nRun:  python examples/kernels/06_softmax.py\r\nNext: examples/kernels/07_normalization.py\r\n\"\"\"\r\n\r\nimport pypto.language as pl\r\nimport torch\r\nfrom pypto.runtime import RunConfig\r\n\r\n\r\n@pl.jit\r\ndef tile_softmax(a: pl.Tensor, output: pl.Out[pl.Tensor]):\r\n    with pl.at(level=pl.Level.CORE_GROUP):\r\n        tile_a = pl.load(a, [0, 0], [64, 64])\r\n\r\n        # Step 1: row-wise max for numerical stability\r\n        max_tmp = pl.create_tile([64, 1], dtype=pl.FP32, target_memory=pl.MemorySpace.Vec)\r\n        row_max: pl.Tile[[64, 1], pl.FP32] = pl.row_max(tile_a, max_tmp)\r\n\r\n        # Step 2: subtract row max from each row: x - max(x)\r\n        shifted = pl.row_expand_sub(tile_a, row_max)\r\n\r\n        # Step 3: exp(x - max(x))\r\n        exp_shifted = pl.exp(shifted)\r\n\r\n        # Step 4: row-wise sum of exp values\r\n        sum_tmp = pl.create_tile([64, 1], dtype=pl.FP32, target_memory=pl.MemorySpace.Vec)\r\n        row_sum: pl.Tile[[64, 1], pl.FP32] = pl.row_sum(exp_shifted, sum_tmp)\r\n\r\n        # Step 5: divide each row by its sum\r\n        result = pl.row_expand_div(exp_shifted, row_sum)\r\n\r\n        pl.store(result, [0, 0], output)\r\n    return output\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    torch.manual_seed(0)\r\n    a = torch.randn(64, 64, dtype=torch.float32)\r\n    out = torch.zeros_like(a)\r\n    tile_softmax(a, out, config=RunConfig())\r\n    expected = torch.softmax(a, dim=-1)\r\n    assert torch.allclose(out, expected, rtol=1e-5, atol=1e-5), (\r\n        f\"tile_softmax failed: max diff = {(out - expected).abs().max().item()}\"\r\n    )\r\n    print(\"OK\")\r\n","examples/kernels/07_normalization.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"\r\nNormalization layers: RMSNorm and LayerNorm (32x64 input).\r\n\r\nKernels:\r\n  rms_norm   -- output = x / sqrt(mean(x^2) + eps) * gamma\r\n  layer_norm -- output = (x - mean) / sqrt(var + eps) * gamma + beta\r\n\r\nConcepts introduced:\r\n  - pl.reshape for transposing [32,1] -> [1,32] (ColMajor -> RowMajor workaround)\r\n  - pl.row_sum for row-wise reduction\r\n  - pl.row_expand_sub, pl.row_expand_div for broadcasting row vectors\r\n  - pl.col_expand_mul, pl.col_expand for broadcasting column vectors\r\n  - pl.sqrt for square root\r\n\r\nRun:  python examples/kernels/07_normalization.py\r\nNext: examples/kernels/08_assemble.py\r\n\"\"\"\r\n\r\nimport pypto.language as pl\r\nimport torch\r\nfrom pypto.runtime import RunConfig\r\n\r\n\r\n@pl.jit\r\ndef rms_norm(x: pl.Tensor, gamma: pl.Tensor, output: pl.Out[pl.Tensor]):\r\n    with pl.at(level=pl.Level.CORE_GROUP):\r\n        tile_x = pl.load(x, [0, 0], [32, 64])\r\n        tile_gamma = pl.load(gamma, [0, 0], [1, 64])\r\n\r\n        # [32, 1] tiles are ColMajor; scalar ops (mul/add) need RowMajor.\r\n        # Workaround: reshape [32, 1] -> [1, 32], apply op, reshape back.\r\n\r\n        # squared = x * x\r\n        squared = pl.mul(tile_x, tile_x)\r\n\r\n        # mean_sq = sum(x^2, dim=-1, keepdim=True) / hidden_size\r\n        tmp = pl.create_tile([32, 64], dtype=pl.FP32, target_memory=pl.MemorySpace.Vec)\r\n        mean_sq: pl.Tile[[32, 1], pl.FP32] = pl.row_sum(squared, tmp)\r\n        mean_sq_T: pl.Tile[[1, 32], pl.FP32] = pl.reshape(mean_sq, [1, 32])\r\n        mean_sq_T = pl.mul(mean_sq_T, 0.015625)  # 1.0 / 64\r\n        mean_sq = pl.reshape(mean_sq_T, [32, 1])\r\n\r\n        # rms = sqrt(mean_sq + eps)\r\n        mean_sq_T = pl.reshape(mean_sq, [1, 32])\r\n        rms_T = pl.add(mean_sq_T, 1e-5)\r\n        rms_T = pl.sqrt(rms_T)\r\n        rms = pl.reshape(rms_T, [32, 1])\r\n\r\n        # normalized = x / rms (broadcast rms across hidden dim)\r\n        normalized = pl.row_expand_div(tile_x, rms)\r\n\r\n        # result = normalized * gamma (broadcast gamma across batch)\r\n        result = pl.col_expand_mul(normalized, tile_gamma)\r\n\r\n        pl.store(result, [0, 0], output)\r\n    return output\r\n\r\n\r\n@pl.jit\r\ndef layer_norm(\r\n    x: pl.Tensor,\r\n    gamma: pl.Tensor,\r\n    beta: pl.Tensor,\r\n    output: pl.Out[pl.Tensor],\r\n):\r\n    with pl.at(level=pl.Level.CORE_GROUP):\r\n        tile_x = pl.load(x, [0, 0], [32, 64])\r\n        tile_gamma = pl.load(gamma, [0, 0], [1, 64])\r\n        tile_beta = pl.load(beta, [0, 0], [1, 64])\r\n\r\n        # mean = sum(x, dim=-1, keepdim=True) / hidden_size\r\n        tmp = pl.create_tile([32, 64], dtype=pl.FP32, target_memory=pl.MemorySpace.Vec)\r\n        mean: pl.Tile[[32, 1], pl.FP32] = pl.row_sum(tile_x, tmp)\r\n        mean_T: pl.Tile[[1, 32], pl.FP32] = pl.reshape(mean, [1, 32])\r\n        mean_T = pl.mul(mean_T, 0.015625)  # 1.0 / 64\r\n        mean = pl.reshape(mean_T, [32, 1])\r\n\r\n        # centered = x - mean (broadcast mean across hidden dim)\r\n        centered = pl.row_expand_sub(tile_x, mean)\r\n\r\n        # var = sum(centered^2, dim=-1, keepdim=True) / hidden_size\r\n        squared = pl.mul(centered, centered)\r\n        tmp2 = pl.create_tile([32, 64], dtype=pl.FP32, target_memory=pl.MemorySpace.Vec)\r\n        var: pl.Tile[[32, 1], pl.FP32] = pl.row_sum(squared, tmp2)\r\n        var_T: pl.Tile[[1, 32], pl.FP32] = pl.reshape(var, [1, 32])\r\n        var_T = pl.mul(var_T, 0.015625)  # 1.0 / 64\r\n        var = pl.reshape(var_T, [32, 1])\r\n\r\n        # std = sqrt(var + eps)\r\n        var_T = pl.reshape(var, [1, 32])\r\n        var_eps_T = pl.add(var_T, 1e-5)\r\n        std_T = pl.sqrt(var_eps_T)\r\n        std = pl.reshape(std_T, [32, 1])\r\n\r\n        # normalized = centered / std (broadcast std across hidden dim)\r\n        normalized = pl.row_expand_div(centered, std)\r\n\r\n        # scaled = normalized * gamma (broadcast gamma across batch)\r\n        scaled = pl.col_expand_mul(normalized, tile_gamma)\r\n\r\n        # result = scaled + beta (broadcast beta across batch)\r\n        beta_full = pl.col_expand(scaled, tile_beta)\r\n        result = pl.add(scaled, beta_full)\r\n\r\n        pl.store(result, [0, 0], output)\r\n    return output\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    torch.manual_seed(0)\r\n    config = RunConfig()\r\n    eps = 1e-5\r\n    hidden_size = 64\r\n\r\n    # RMSNorm\r\n    x = torch.randn(32, 64, dtype=torch.float32)\r\n    gamma = torch.randn(1, 64, dtype=torch.float32)\r\n    out = torch.zeros_like(x)\r\n    rms_norm(x, gamma, out, config=config)\r\n    mean_sq = (x**2).sum(dim=-1, keepdim=True) / hidden_size\r\n    rms_ref = torch.sqrt(mean_sq + eps)\r\n    expected = (x / rms_ref) * gamma\r\n    assert torch.allclose(out, expected, rtol=1e-5, atol=1e-5), (\r\n        f\"rms_norm failed: max diff = {(out - expected).abs().max().item()}\"\r\n    )\r\n\r\n    # LayerNorm\r\n    x = torch.randn(32, 64, dtype=torch.float32)\r\n    gamma = torch.randn(1, 64, dtype=torch.float32)\r\n    beta = torch.randn(1, 64, dtype=torch.float32)\r\n    out = torch.zeros_like(x)\r\n    layer_norm(x, gamma, beta, out, config=config)\r\n    mean = x.sum(dim=-1, keepdim=True) / hidden_size\r\n    centered = x - mean\r\n    var = (centered**2).sum(dim=-1, keepdim=True) / hidden_size\r\n    std_ref = torch.sqrt(var + eps)\r\n    expected = (centered / std_ref) * gamma + beta\r\n    assert torch.allclose(out, expected, rtol=1e-5, atol=1e-5), (\r\n        f\"layer_norm failed: max diff = {(out - expected).abs().max().item()}\"\r\n    )\r\n\r\n    print(\"OK\")\r\n","examples/kernels/08_assemble.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"\r\nTile assemble: write a source tile into a target tile at a specified offset.\r\n\r\nHardware semantics (PTO backend):\r\n  tile.assemble maps to the TINSERT instruction. The hardware mode is inferred\r\n  automatically from the memory spaces of the operands:\r\n\r\n  Acc->Mat (TInsertMode::NZ) -- source from Acc (L0C), target in Mat (L1):\r\n    - target tile: in Mat (L1), fractal layout\r\n    - source tile: in Acc (L0C), fractal layout (always FP32, output of tile.matmul)\r\n    Data flow:\r\n      a, b (GM) -> Mat -> Left/Right -> tile.matmul -> Acc (FP32)\r\n      x   (GM) -> Mat (FP32) [target]\r\n      TINSERT NZ: Acc -> Mat [at offset]\r\n      Mat -> Vec -> GM\r\n\r\n  Vec->Vec (TInsertMode::ND_VEC) -- both tiles in Vec (UB), RowMajor/ND layout:\r\n    - target tile: in Vec (UB), ND layout\r\n    - source tile: in Vec (UB), ND layout\r\n    Data flow:\r\n      x   (GM) -> Vec (UB) [target]\r\n      src (GM) -> Vec (UB) [source]\r\n      TINSERT ND_VEC: Vec -> Vec [at offset]\r\n      Vec -> GM\r\n\r\nConcepts introduced:\r\n  - pl.tile.assemble for inserting tiles at offsets\r\n  - pl.slice for extracting sub-tiles with dynamic offsets\r\n  - pl.range for InCore loops (DSL for-loop)\r\n  - Nested loops with computed offsets\r\n  - Acc->Mat vs Vec->Vec hardware modes\r\n\r\nKernels (one representative per distinct pattern):\r\n  tile_assemble_acc_mat              -- Acc->Mat: matmul result -> target at offset\r\n  tile_assemble_vec                  -- Vec->Vec: single-shot insert\r\n  tile_assemble_row_by_row           -- Vec->Vec: loop + pl.slice + assemble\r\n  tile_assemble_double_loop          -- Vec->Vec: nested loops + pl.slice\r\n  tile_assemble_loop_col_broadcast   -- Vec->Vec: loop with column broadcast (no slice)\r\n  tile_assemble_double_loop_broadcast -- Vec->Vec: nested loops, quadrant broadcast\r\n\r\nNote: ``__main__`` runs ``compile_for_test`` (full pass pipeline, no device\r\nexecution) for each kernel. The per-mode hardware semantics of TINSERT\r\n(Acc->Mat NZ vs. Vec->Vec ND_VEC) are best validated on device via\r\n``tests/st/runtime/ops/test_assemble.py`` rather than against a torch reference.\r\n\r\nRun:  python examples/kernels/08_assemble.py\r\nNext: examples/models/01_ffn.py\r\n\"\"\"\r\n\r\nimport pypto.language as pl\r\nimport torch\r\n\r\n\r\n@pl.jit\r\ndef tile_assemble_acc_mat(\r\n    x: pl.Tensor,\r\n    a: pl.Tensor,\r\n    b: pl.Tensor,\r\n    y: pl.Out[pl.Tensor],\r\n):\r\n    with pl.at(level=pl.Level.CORE_GROUP):\r\n        # Load target into Mat (L1)\r\n        tile_x = pl.load(x, [0, 0], [32, 32], target_memory=pl.MemorySpace.Mat)\r\n        # Produce Acc (L0C, FP32) via matmul: GM -> Mat -> Left/Right -> matmul\r\n        tile_a_l1 = pl.load(a, [0, 0], [32, 16], target_memory=pl.MemorySpace.Mat)\r\n        tile_b_l1 = pl.load(b, [0, 0], [16, 16], target_memory=pl.MemorySpace.Mat)\r\n        tile_a = pl.move(tile_a_l1, target_memory=pl.MemorySpace.Left)\r\n        tile_b = pl.move(tile_b_l1, target_memory=pl.MemorySpace.Right)\r\n        tile_src = pl.matmul(tile_a, tile_b)\r\n        # Assemble: insert tile_src into the right half of tile_x at offset [0, 16]\r\n        result = pl.tile.assemble(tile_x, tile_src, [0, 16])\r\n        # Move Mat -> Vec before store\r\n        result_vec = pl.move(result, target_memory=pl.MemorySpace.Vec)\r\n        pl.store(result_vec, [0, 0], y)\r\n    return y\r\n\r\n\r\n@pl.jit\r\ndef tile_assemble_vec(\r\n    x: pl.Tensor,\r\n    src: pl.Tensor,\r\n    y: pl.Out[pl.Tensor],\r\n):\r\n    with pl.at(level=pl.Level.CORE_GROUP):\r\n        # Load target and source into Vec (UB) -- ND/RowMajor layout\r\n        tile_x = pl.load(x, [0, 0], [32, 32], target_memory=pl.MemorySpace.Vec)\r\n        tile_src = pl.load(src, [0, 0], [32, 16], target_memory=pl.MemorySpace.Vec)\r\n        # Assemble: insert src into the left half of x at [0, 0] -- ND_VEC mode\r\n        result = pl.tile.assemble(tile_x, tile_src, [0, 0])\r\n        pl.store(result, [0, 0], y)\r\n    return y\r\n\r\n\r\n@pl.jit\r\ndef tile_assemble_row_by_row(\r\n    x: pl.Tensor,\r\n    src: pl.Tensor,\r\n    y: pl.Out[pl.Tensor],\r\n):\r\n    with pl.at(level=pl.Level.CORE_GROUP):\r\n        tile_x = pl.load(x, [0, 0], [32, 32], target_memory=pl.MemorySpace.Vec)\r\n        tile_src = pl.load(src, [0, 0], [32, 16], target_memory=pl.MemorySpace.Vec)\r\n        for i in pl.range(32):\r\n            row = pl.slice(tile_src, [1, 16], [i, 0])\r\n            tile_x = pl.tile.assemble(tile_x, row, [i, 0])\r\n        pl.store(tile_x, [0, 0], y)\r\n    return y\r\n\r\n\r\n@pl.jit\r\ndef tile_assemble_double_loop(\r\n    x: pl.Tensor,\r\n    src: pl.Tensor,\r\n    y: pl.Out[pl.Tensor],\r\n):\r\n    with pl.at(level=pl.Level.CORE_GROUP):\r\n        tile_x = pl.load(x, [0, 0], [32, 32], target_memory=pl.MemorySpace.Vec)\r\n        tile_src = pl.load(src, [0, 0], [32, 16], target_memory=pl.MemorySpace.Vec)\r\n        for b in pl.range(4):\r\n            for i in pl.range(8):\r\n                row = b * 8 + i\r\n                tile_row = pl.slice(tile_src, [1, 16], [row, 0])\r\n                tile_x = pl.tile.assemble(tile_x, tile_row, [row, 0])\r\n        pl.store(tile_x, [0, 0], y)\r\n    return y\r\n\r\n\r\n@pl.jit\r\ndef tile_assemble_loop_col_broadcast(\r\n    x: pl.Tensor,\r\n    src: pl.Tensor,\r\n    y: pl.Out[pl.Tensor],\r\n):\r\n    with pl.at(level=pl.Level.CORE_GROUP):\r\n        tile_x = pl.load(x, [0, 0], [32, 32], target_memory=pl.MemorySpace.Vec)\r\n        tile_src = pl.load(src, [0, 0], [32, 8], target_memory=pl.MemorySpace.Vec)\r\n        for c in pl.range(4):\r\n            tile_x = pl.tile.assemble(tile_x, tile_src, [0, c * 8])\r\n        pl.store(tile_x, [0, 0], y)\r\n    return y\r\n\r\n\r\n@pl.jit\r\ndef tile_assemble_double_loop_broadcast(\r\n    x: pl.Tensor,\r\n    src: pl.Tensor,\r\n    y: pl.Out[pl.Tensor],\r\n):\r\n    with pl.at(level=pl.Level.CORE_GROUP):\r\n        tile_x = pl.load(x, [0, 0], [32, 32], target_memory=pl.MemorySpace.Vec)\r\n        tile_src = pl.load(src, [0, 0], [16, 16], target_memory=pl.MemorySpace.Vec)\r\n        for b in pl.range(2):\r\n            for c in pl.range(2):\r\n                tile_x = pl.tile.assemble(tile_x, tile_src, [b * 16, c * 16])\r\n        pl.store(tile_x, [0, 0], y)\r\n    return y\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    # Smoke test each kernel via compile_for_test (no torch reference --\r\n    # tile.assemble's per-mode hardware semantics are best validated on device).\r\n    cases = [\r\n        (\r\n            \"acc_mat\",\r\n            tile_assemble_acc_mat,\r\n            (\r\n                torch.randn(32, 32, dtype=torch.float32),\r\n                torch.randn(32, 16, dtype=torch.float32),\r\n                torch.randn(16, 16, dtype=torch.float32),\r\n                torch.zeros(32, 32, dtype=torch.float32),\r\n            ),\r\n        ),\r\n        (\r\n            \"vec\",\r\n            tile_assemble_vec,\r\n            (\r\n                torch.randn(32, 32, dtype=torch.float32),\r\n                torch.randn(32, 16, dtype=torch.float32),\r\n                torch.zeros(32, 32, dtype=torch.float32),\r\n            ),\r\n        ),\r\n        (\r\n            \"row_by_row\",\r\n            tile_assemble_row_by_row,\r\n            (\r\n                torch.randn(32, 32, dtype=torch.float32),\r\n                torch.randn(32, 16, dtype=torch.float32),\r\n                torch.zeros(32, 32, dtype=torch.float32),\r\n            ),\r\n        ),\r\n        (\r\n            \"double_loop\",\r\n            tile_assemble_double_loop,\r\n            (\r\n                torch.randn(32, 32, dtype=torch.float32),\r\n                torch.randn(32, 16, dtype=torch.float32),\r\n                torch.zeros(32, 32, dtype=torch.float32),\r\n            ),\r\n        ),\r\n        (\r\n            \"loop_col_broadcast\",\r\n            tile_assemble_loop_col_broadcast,\r\n            (\r\n                torch.randn(32, 32, dtype=torch.float32),\r\n                torch.randn(32, 8, dtype=torch.float32),\r\n                torch.zeros(32, 32, dtype=torch.float32),\r\n            ),\r\n        ),\r\n        (\r\n            \"double_loop_broadcast\",\r\n            tile_assemble_double_loop_broadcast,\r\n            (\r\n                torch.randn(32, 32, dtype=torch.float32),\r\n                torch.randn(16, 16, dtype=torch.float32),\r\n                torch.zeros(32, 32, dtype=torch.float32),\r\n            ),\r\n        ),\r\n    ]\r\n    for name, fn, args in cases:\r\n        prog = fn.compile_for_test(*args)\r\n        print(f\"{name}: {len(prog.functions)} fn(s)\")\r\n    print(\"OK\")\r\n","examples/kernels/09_dyn_valid_shape.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"Dynamic valid_shape examples.\r\n\r\nDemonstrates a DSL pattern where the valid length of a tile is a runtime\r\nscalar (caller-provided) and used inside ``pl.load(..., valid_shapes=...)``\r\nto bound the active region of the tile, then padded via\r\n``pl.tile.fillpad``::\r\n\r\n    tile = pl.load(..., valid_shapes=[rows, vlen])   # vlen is a runtime scalar\r\n    padded = pl.tile.fillpad(tile, pad_value=PadValue.min)\r\n\r\nJIT note\r\n--------\r\nThe pre-JIT version of this example also showed the same pattern with\r\n``vlen`` selected via ``if/else`` (and inside a per-block loop).  In the\r\n@pl.jit world the specializer's alpha-renamer rewrites the rebinding of\r\n``vlen`` in the else-branch to a distinct alias, which then fails\r\n``ConvertToSSA`` (\"used outside its defining scope\").  The current\r\nrecommended workaround is to push the per-call/per-iteration choice of\r\n``vlen`` to the *caller* and pass a single scalar parameter -- as shown\r\nbelow.  Restoring the in-DSL ``if/else`` pattern requires a JIT\r\nspecializer fix (see the comments in ``examples/models/qwen3_jit/``).\r\n\r\nNote: ``__main__`` runs ``compile_for_test`` only (no device execution).\r\nFull end-to-end execution is exercised under\r\n``tests/st/codegen/dsl/test_dyn_valid_shape_loop.py`` and\r\n``tests/st/codegen/dsl/test_dynamic_valid_shape_if_else.py``.\r\n\r\nRun:  python examples/kernels/09_dyn_valid_shape.py\r\n\"\"\"\r\n\r\n# DSL function bodies are parsed as AST -- runtime scalars (vlen, ...)\r\n# look undefined to pyright. pl.FP32 / pl.INDEX scalar dtype markers (used as\r\n# annotations) are DataType values, not types -- pyright can't infer them.\r\n# pyright: reportUndefinedVariable=false, reportInvalidTypeForm=false\r\n\r\nimport pypto.language as pl\r\nimport torch\r\n\r\n# Tile / tensor dimensions\r\nQ_TILE = 64\r\nBLOCK_COL = 64\r\n\r\n\r\n@pl.jit\r\ndef dyn_valid_shape(\r\n    data: pl.Tensor,\r\n    scale: pl.FP32,\r\n    vlen: pl.INDEX,\r\n    output: pl.Out[pl.Tensor],\r\n):\r\n    \"\"\"Load with caller-provided valid_shape, fillpad, then scale.\r\n\r\n    The caller passes either the partial-block length or the full-block\r\n    length; the kernel does not need to branch internally.\r\n    \"\"\"\r\n    with pl.at(level=pl.Level.CORE_GROUP):\r\n        s_tile = pl.load(\r\n            data,\r\n            [0, 0],\r\n            [Q_TILE, BLOCK_COL],\r\n            valid_shapes=[Q_TILE, vlen],\r\n            target_memory=pl.MemorySpace.Vec,\r\n        )\r\n        s_padded = pl.tile.fillpad(s_tile, pad_value=pl.PadValue.min)\r\n        scaled = pl.mul(s_padded, scale)\r\n        pl.store(scaled, [0, 0], output)\r\n    return output\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    # Smoke test via compile_for_test (no device execution required).\r\n    # Same kernel, two different valid_shape values: full block (64) and\r\n    # partial last block (32). compile_for_test caches per concrete vlen,\r\n    # so both compile cleanly.\r\n    data = torch.randn(Q_TILE, BLOCK_COL, dtype=torch.float32)\r\n    out = torch.zeros(Q_TILE, BLOCK_COL, dtype=torch.float32)\r\n\r\n    prog_full = dyn_valid_shape.compile_for_test(data, 0.5, 64, out)\r\n    print(f\"dyn_valid_shape (full): {len(prog_full.functions)} fn(s)\")\r\n\r\n    prog_partial = dyn_valid_shape.compile_for_test(data, 0.5, 32, out)\r\n    print(f\"dyn_valid_shape (partial): {len(prog_partial.functions)} fn(s)\")\r\n    print(\"OK\")\r\n","examples/kernels/10_split_k.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"\r\nSplit-K matrix multiplication.\r\n\r\nSplit-K is a matmul optimisation for a large K (reduction) dimension with\r\nsmall M and N. With small M/N there are few independent output tiles, so the\r\nstandard \"one output tile per core\" mapping leaves most cores idle. Split-K\r\nalso parallelises the K dimension: each core computes a partial product over\r\na slice of K, and the partials are summed into the shared output.\r\n\r\nKernel:\r\n  matmul_split_k -- [M, K] @ [K, N] with K split across SPLIT parallel cores\r\n\r\nConcepts introduced:\r\n  - pl.parallel over the K dimension (one core per K-slice)\r\n  - pl.assemble(..., atomic=pl.AtomicType.Add) -- atomic-add accumulation of\r\n    each core's partial product into one global-memory output\r\n  - in-kernel zero-initialisation of the output before the atomic-add loop\r\n\r\nNOTE: atomic-add accumulation order across cores is not fixed, so the\r\nfloating-point result is non-deterministic at the ulp level.\r\n\r\nRun:  python examples/kernels/10_split_k.py\r\n\"\"\"\r\n\r\nimport pypto.language as pl\r\nimport torch\r\nfrom pypto.runtime import RunConfig\r\n\r\nM = 64\r\nN = 64\r\nK = 512\r\nSPLIT = 4  # number of cores the K reduction is spread across\r\nKS = K // SPLIT  # per-core K-slice width\r\n\r\n\r\n@pl.jit\r\ndef matmul_split_k(a: pl.Tensor, b: pl.Tensor, c: pl.Out[pl.Tensor]):\r\n    \"\"\"Split-K matmul: c = a @ b, with K split across SPLIT parallel cores.\r\n\r\n    Each core multiplies an [M, KS] x [KS, N] slice and atomically adds its\r\n    partial product into ``c``. ``c`` is zero-initialised in-kernel first so\r\n    the accumulation starts from zero; the zero-init is sequenced before the\r\n    parallel loop because its result feeds the loop.\r\n    \"\"\"\r\n    with pl.at(level=pl.Level.CORE_GROUP, name_hint=\"zero_init\"):\r\n        c = pl.assemble(c, pl.full([M, N], dtype=pl.FP32, value=0.0), [0, 0])\r\n    for ks in pl.parallel(0, SPLIT):\r\n        with pl.at(level=pl.Level.CORE_GROUP, name_hint=\"split_k\"):\r\n            k0 = ks * KS\r\n            a_k = a[:, k0 : k0 + KS]\r\n            b_k = b[k0 : k0 + KS, :]\r\n            partial = pl.matmul(a_k, b_k, out_dtype=pl.FP32)\r\n            c = pl.assemble(c, partial, [0, 0], atomic=pl.AtomicType.Add)\r\n    return c\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    cfg = RunConfig()\r\n    torch.manual_seed(0)\r\n\r\n    a = torch.randn(M, K, dtype=torch.float32)\r\n    b = torch.randn(K, N, dtype=torch.float32)\r\n\r\n    c = torch.zeros((M, N), dtype=torch.float32)\r\n    matmul_split_k(a, b, c, config=cfg)\r\n    assert torch.allclose(c, torch.matmul(a, b), rtol=1e-3, atol=1e-3)\r\n\r\n    print(\"OK\")\r\n","examples/kernels/11_auto_tile_matmul.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"\r\nCompiler-driven L0 matmul tiling (AutoTileMatmulL0) -- the placement x K-strategy matrix.\r\n\r\nWhen a matmul's ``[M, N]`` output exceeds the cube accumulator L0c (128 KB on Ascend910B),\r\nAutoTileMatmulL0 tiles the output into ``[m, n]`` sub-tiles and **places** each one by where\r\nthe result is consumed:\r\n\r\n  - **DDR (direct-store)** -- the result is stored to a DDR tensor; each sub-tile is stored\r\n    straight to ``out[mi:, ni:]``.\r\n  - **Mat/L1 (Mat-scratch)** -- the result is consumed on-chip by *another matmul*; each\r\n    sub-tile is assembled (Acc->Mat ``tile.assemble``) into an L1/Mat scratch kept on-chip,\r\n    so the chain never spills the intermediate to DDR.\r\n\r\nOrthogonally, the K (reduction) dimension picks the **K-strategy**:\r\n\r\n  - **full-K** -- the whole K fits L0a/L0b at once (``k == K``); the M/N grid is a pipelined\r\n    nest with loop-variable offsets (BuildFullKPipelined).\r\n  - **split-K** -- K spans >= 2 L0 blocks; each ``[m, n]`` sub-tile is its own pipelined\r\n    K-loop (BuildSplitKGrid).\r\n\r\nThe first four kernels are the oversized 2x2 matrix. The K-strategy is **shape-driven**: for\r\nan ``[M, N] = [256, 256]`` FP32 output the L0 chooser caps ``k = 32``, so ``K = 32`` fits L0\r\nin one pass (full-K) while ``K = 128`` splits into 4 K-blocks (split-K). No manual tiling --\r\nthe compiler picks the path from the shapes and the consumer.\r\n\r\n**Fits-L0c chained matmul (cast-fold).** When the chained ``[M, N]`` intermediate *fits* L0c\r\n(no M/N tiling), the same Mat/L1 placement applies as a **single full-window** Acc->Mat\r\n``tile.assemble``: the autotiler folds the ``pl.cast(c, bf16)`` into one cube FIXPIPE\r\n``pto.tinsert``, so the downcast stays on the cube. Without the fold the standalone ``pl.cast``\r\nlowers to a Vector ``pto.tcvt`` (a cube->vector->cube round-trip that overflows the Vec buffer\r\nat ``[128, 128]``). The fold matches FIXPIPE's fixed narrowing exactly — it fires only for\r\n``mode=\"rint\"`` (round-half-to-even); the cast default ``\"round\"`` (ties away) and the\r\ndirectional modes keep the Vector cast. FIXPIPE narrows tie-even on **both** A2/A3 and A5\r\n(the cube writeback rounding is arch-independent — only the scratch dtype differs: A2/A3\r\nforces bf16, A5 may keep f32), so the folded cast needs ``mode=\"rint\"`` on either backend.\r\nThe last two kernels are the full-K (no K-loop) and split-K (K-loop) fits-L0c cases.\r\n\r\nRun:  python examples/kernels/11_auto_tile_matmul.py\r\n\"\"\"\r\n\r\nimport pypto.language as pl\r\nimport torch\r\nfrom pypto.runtime import RunConfig\r\n\r\n\r\n@pl.jit\r\ndef ddr_split_k(a: pl.Tensor, b: pl.Tensor, out: pl.Out[pl.Tensor]):\r\n    \"\"\"``a @ b`` -> **DDR**, **split-K**. ``[256,128] @ [128,256] = [256,256]`` (> L0c) is\r\n    consumed by the output store, so each ``[m, n]`` sub-tile direct-stores to DDR; ``K=128``\r\n    splits into K-blocks.\"\"\"\r\n    with pl.at(level=pl.Level.CORE_GROUP, name_hint=\"ddr_split_k\"):\r\n        c = pl.matmul(a, b, out_dtype=pl.FP32)  # [256, 256] -> M/N-tiled, stored to DDR\r\n        out = pl.assemble(out, c, [0, 0])\r\n    return out\r\n\r\n\r\n@pl.jit\r\ndef ddr_full_k(a: pl.Tensor, b: pl.Tensor, out: pl.Out[pl.Tensor]):\r\n    \"\"\"``a @ b`` -> **DDR**, **full-K**. Same as above but ``[256,32] @ [32,256]``; ``K=32``\r\n    fits L0 in one pass (``k == K``), so the grid is the pipelined full-K nest.\"\"\"\r\n    with pl.at(level=pl.Level.CORE_GROUP, name_hint=\"ddr_full_k\"):\r\n        c = pl.matmul(a, b, out_dtype=pl.FP32)\r\n        out = pl.assemble(out, c, [0, 0])\r\n    return out\r\n\r\n\r\n@pl.jit\r\ndef mat_split_k(a: pl.Tensor, b: pl.Tensor, e: pl.Tensor, out: pl.Out[pl.Tensor]):\r\n    \"\"\"``(a @ b) @ e`` -> **Mat/L1 scratch**. The ``[256,256]`` intermediate (> L0c) is\r\n    consumed on-chip by the second matmul, so it is M/N-tiled into an L1/Mat scratch\r\n    instead of spilling to DDR. The test drives this with a K where the roofline chooser\r\n    keeps both chained matmuls **output-stationary** so their L0 buffers pack (a K that\r\n    makes the producer A/B-stationary hits the #1908 offset-packing gap: ``Left buffer\r\n    usage exceeds``).\r\n\r\n    The intermediate is **bf16** — the cube accumulates in f32 (L0C) and the FIXPIPE\r\n    writeback to L1 downcasts to bf16/f16 (the only offset Acc->Mat path on A2/A3), which\r\n    is also the cube's native matmul-operand precision. The explicit ``pl.cast(..., mode=\"rint\")``\r\n    matches FIXPIPE's round-half-to-even tie rule (``pto.tinsert`` carries no rmode); the autotiler\r\n    fuses it into the per-sub-tile Acc->Mat ``pto.tinsert`` that fills the scratch.\"\"\"\r\n    with pl.at(level=pl.Level.CORE_GROUP, name_hint=\"mat_split_k\"):\r\n        c = pl.matmul(a, b, out_dtype=pl.FP32)  # bf16 @ bf16 -> f32 [256, 256] (> L0c)\r\n        cb = pl.cast(c, pl.BF16, mode=\"rint\")  # rint REQUIRED to fold (FIXPIPE narrows tie-even)\r\n        d = pl.matmul(cb, e, out_dtype=pl.FP32)  # consumes the scratch on-chip\r\n        out = pl.assemble(out, d, [0, 0])\r\n    return out\r\n\r\n\r\n@pl.jit\r\ndef mat_full_k(a: pl.Tensor, b: pl.Tensor, e: pl.Tensor, out: pl.Out[pl.Tensor]):\r\n    \"\"\"``(a @ b) @ e`` -> **Mat/L1 scratch**, **full-K**. Same bf16 chain but ``[256,32] @\r\n    [32,256]``; ``K=32`` fits L0 (``k == K``), so the Mat-scratch ``tinsert``s land inside\r\n    the pipelined full-K nest with loop-variable offsets.\"\"\"\r\n    with pl.at(level=pl.Level.CORE_GROUP, name_hint=\"mat_full_k\"):\r\n        c = pl.matmul(a, b, out_dtype=pl.FP32)  # bf16 @ bf16 -> f32 [256, 256] (> L0c)\r\n        cb = pl.cast(c, pl.BF16, mode=\"rint\")  # rint REQUIRED to fold (FIXPIPE narrows tie-even)\r\n        d = pl.matmul(cb, e, out_dtype=pl.FP32)\r\n        out = pl.assemble(out, d, [0, 0])\r\n    return out\r\n\r\n\r\n@pl.jit\r\ndef fits_l0c_full_k(a: pl.Tensor, b: pl.Tensor, e: pl.Tensor, out: pl.Out[pl.Tensor]):\r\n    \"\"\"``(a @ b) @ e`` -> **Mat/L1 scratch**, **fits-L0c full-K**. The ``[128, 128]``\r\n    intermediate *fits* L0c (no M/N tiling), and ``K=64`` fits L0 (``k == K``), so the\r\n    producer is a single matmul. The autotiler folds ``pl.cast`` into ONE full-window\r\n    Acc->Mat ``tile.assemble`` (cube ``pto.tinsert``) — no Vector ``tcvt``, no round-trip.\"\"\"\r\n    with pl.at(level=pl.Level.CORE_GROUP, name_hint=\"fits_l0c_full_k\"):\r\n        c = pl.matmul(a, b, out_dtype=pl.FP32)  # [128, 128] f32, fits L0c\r\n        cb = pl.cast(c, pl.BF16, mode=\"rint\")  # rint REQUIRED to fold (FIXPIPE narrows tie-even)\r\n        d = pl.matmul(cb, e, out_dtype=pl.FP32)  # consumes the bf16 Mat scratch on-chip\r\n        out = pl.assemble(out, d, [0, 0])\r\n    return out\r\n\r\n\r\n@pl.jit\r\ndef fits_l0c_split_k(a: pl.Tensor, b: pl.Tensor, e: pl.Tensor, out: pl.Out[pl.Tensor]):\r\n    \"\"\"``(a @ b) @ e`` -> **Mat/L1 scratch**, **fits-L0c split-K**. Same ``[128, 128]``\r\n    fits-L0c intermediate, but ``[128, 512] @ [512, 128]`` overflows L0a/L0b, so the\r\n    producer is K-looped. The K-loop's Acc result is folded into the *same* single\r\n    full-window Acc->Mat assemble — the cast-fold is independent of the K tiling.\"\"\"\r\n    with pl.at(level=pl.Level.CORE_GROUP, name_hint=\"fits_l0c_split_k\"):\r\n        c = pl.matmul(a, b, out_dtype=pl.FP32)  # [128, 128] f32, fits L0c; K=512 splits\r\n        cb = pl.cast(c, pl.BF16, mode=\"rint\")  # rint REQUIRED to fold (FIXPIPE narrows tie-even)\r\n        d = pl.matmul(cb, e, out_dtype=pl.FP32)\r\n        out = pl.assemble(out, d, [0, 0])\r\n    return out\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    cfg = RunConfig()\r\n    torch.manual_seed(0)\r\n\r\n    # DDR (direct-store): a @ b -> [256, 256]; K picks split-K (128) vs full-K (32).\r\n    for fn, K in ((ddr_split_k, 128), (ddr_full_k, 32)):\r\n        a = torch.randn(256, K, dtype=torch.float32)\r\n        b = torch.randn(K, 256, dtype=torch.float32)\r\n        out = torch.zeros((256, 256), dtype=torch.float32)\r\n        fn(a, b, out, config=cfg)\r\n        assert torch.allclose(out, a @ b, rtol=1e-3, atol=1e-3), f\"{fn.__name__} mismatch\"\r\n\r\n    # Mat/L1 scratch: (a @ b) @ e -> [256, 64]; bf16 operands, bf16 on-chip intermediate.\r\n    # K picks split-K (128) vs full-K (32). Golden models the FIXPIPE bf16 downcast of the\r\n    # intermediate (f32 accumulate -> bf16 L1 -> f32 accumulate), so the tolerance is bf16.\r\n    for fn, K in ((mat_split_k, 128), (mat_full_k, 32)):\r\n        a = torch.randn(256, K, dtype=torch.bfloat16)\r\n        b = torch.randn(K, 256, dtype=torch.bfloat16)\r\n        e = torch.randn(256, 64, dtype=torch.bfloat16)\r\n        out = torch.zeros((256, 64), dtype=torch.float32)\r\n        fn(a, b, e, out, config=cfg)\r\n        c_bf16 = (a.float() @ b.float()).to(torch.bfloat16).float()  # FIXPIPE downcast\r\n        golden = c_bf16 @ e.float()\r\n        assert torch.allclose(out, golden, rtol=2e-2, atol=2e-2), f\"{fn.__name__} mismatch\"\r\n\r\n    # Fits-L0c chained (cast-fold): (a @ b) @ e -> [128, 64] with a [128, 128] intermediate\r\n    # that FITS L0c. full-K (K=64, no K-loop) vs split-K (K=512, K-loop). Same bf16 golden.\r\n    # Frobenius relative error (not allclose): the bf16 chain has near-zero cancellation\r\n    # elements where a per-element atol fails on a numerically-correct result (K=512's larger\r\n    # intermediate magnitudes make this bite); the global relative norm is the robust metric.\r\n    for fn, K in ((fits_l0c_full_k, 64), (fits_l0c_split_k, 512)):\r\n        a = torch.randn(128, K, dtype=torch.bfloat16)\r\n        b = torch.randn(K, 128, dtype=torch.bfloat16)\r\n        e = torch.randn(128, 64, dtype=torch.bfloat16)\r\n        out = torch.zeros((128, 64), dtype=torch.float32)\r\n        fn(a, b, e, out, config=cfg)\r\n        c_bf16 = (a.float() @ b.float()).to(torch.bfloat16).float()  # FIXPIPE downcast\r\n        golden = c_bf16 @ e.float()\r\n        rel_err = ((out - golden).norm() / golden.norm()).item()\r\n        assert rel_err < 5e-2, f\"{fn.__name__} Frobenius rel_err {rel_err:.3e} exceeds 5e-2\"\r\n\r\n    print(\"OK\")\r\n","examples/kernels/__init__.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"\r\nKernel examples — single-kernel programs, ordered by complexity.\r\n\r\n  01_elementwise.py    — add, mul (start here)\r\n  02_fused_ops.py      — add+scale, add+relu, matmul+bias, linear+relu\r\n  03_matmul.py         — cube unit matmul and matmul_acc\r\n  04_concat.py         — tile concatenation\r\n  05_activation.py     — SiLU, GELU, SwiGLU, GeGLU\r\n  06_softmax.py        — numerically stable row-wise softmax\r\n  07_normalization.py  — RMSNorm, LayerNorm\r\n  08_assemble.py       — tile assembly patterns (Acc->Mat, Vec->Vec)\r\n  09_dyn_valid_shape.py — dynamic valid_shape via if/else and loop patterns\r\n  10_split_k.py        — split-K matmul (parallel K reduction, atomic-add)\r\n  11_auto_tile_matmul.py — compiler-driven L0 matmul tiling (DDR/Mat-scratch x full-K/split-K)\r\n\"\"\"\r\n\r\nimport importlib\r\nimport sys\r\n\r\n_ALIASES = {\r\n    \"elementwise\": \"01_elementwise\",\r\n    \"fused_ops\": \"02_fused_ops\",\r\n    \"matmul\": \"03_matmul\",\r\n    \"concat\": \"04_concat\",\r\n    \"activation\": \"05_activation\",\r\n    \"softmax\": \"06_softmax\",\r\n    \"normalization\": \"07_normalization\",\r\n    \"assemble\": \"08_assemble\",\r\n    \"dyn_valid_shape\": \"09_dyn_valid_shape\",\r\n    \"auto_tile_matmul\": \"11_auto_tile_matmul\",\r\n}\r\n\r\nfor _alias, _numbered in _ALIASES.items():\r\n    _mod = importlib.import_module(f\".{_numbered}\", __package__)\r\n    globals()[_alias] = _mod\r\n    sys.modules[f\"{__package__}.{_alias}\"] = _mod\r\n","examples/models/01_ffn.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"\r\nFFN module JIT entries (64x64 tiles).\r\n\r\nEach entry implements a full FFN forward pass (gate projection -> activation ->\r\ndown projection):\r\n\r\n  ffn_gelu   -- output = GELU(hidden_states @ gate_proj_weight) @ down_proj_weight\r\n  ffn_swiglu -- output = SwiGLU(gate, up) @ down_proj_weight\r\n  ffn_relu   -- output = ReLU(hidden_states @ gate_proj_weight) @ down_proj_weight\r\n\r\nConcepts introduced:\r\n  - Module-level @pl.jit.incore: shared kernel reused across multiple JIT entries\r\n  - Multi-kernel orchestration: matmul -> activation -> matmul pipeline\r\n  - Direct call to module-level kernels (no self. prefix)\r\n\r\nRun:  python examples/models/01_ffn.py\r\nNext: examples/models/02_vector_dag.py\r\n\"\"\"\r\n\r\nimport pypto.language as pl\r\nimport torch\r\nfrom pypto.runtime import RunConfig\r\n\r\n# ── Shared cube matmul kernel (module-level, reusable across entries) ────────\r\n\r\n\r\n@pl.jit.incore\r\ndef matmul_kernel(a: pl.Tensor, b: pl.Tensor, output: pl.Out[pl.Tensor]):\r\n    \"\"\"Cube InCore: compute a @ b and store result to GM.\"\"\"\r\n    tile_a_l1 = pl.load(a, [0, 0], [64, 64], target_memory=pl.MemorySpace.Mat)\r\n    tile_b_l1 = pl.load(b, [0, 0], [64, 64], target_memory=pl.MemorySpace.Mat)\r\n    tile_a_l0a = pl.move(tile_a_l1, target_memory=pl.MemorySpace.Left)\r\n    tile_b_l0b = pl.move(tile_b_l1, target_memory=pl.MemorySpace.Right)\r\n    tile_c_l0c = pl.matmul(tile_a_l0a, tile_b_l0b)\r\n    pl.store(tile_c_l0c, [0, 0], output)\r\n    return output\r\n\r\n\r\n# ── Activation kernels (module-level @pl.jit.incore) ─────────────────────────\r\n\r\n\r\n@pl.jit.incore\r\ndef gelu_kernel(x: pl.Tensor, output: pl.Out[pl.Tensor]):\r\n    \"\"\"Vector InCore: apply GELU activation -- x * sigmoid(1.702 * x).\"\"\"\r\n    tile_x = pl.load(x, [0, 0], [64, 64])\r\n    x_scaled = pl.mul(tile_x, 1.702)\r\n    x_neg = pl.mul(x_scaled, -1.0)\r\n    exp_neg = pl.exp(x_neg)\r\n    denom = pl.add(exp_neg, 1.0)\r\n    sigmoid = pl.recip(denom)\r\n    result = pl.mul(tile_x, sigmoid)\r\n    pl.store(result, [0, 0], output)\r\n    return output\r\n\r\n\r\n@pl.jit.incore\r\ndef swiglu_kernel(gate: pl.Tensor, up: pl.Tensor, output: pl.Out[pl.Tensor]):\r\n    \"\"\"Vector InCore: apply SwiGLU activation -- gate * sigmoid(gate) * up.\"\"\"\r\n    tile_gate = pl.load(gate, [0, 0], [64, 64])\r\n    tile_up = pl.load(up, [0, 0], [64, 64])\r\n    gate_neg = pl.mul(tile_gate, -1.0)\r\n    exp_neg = pl.exp(gate_neg)\r\n    denom = pl.add(exp_neg, 1.0)\r\n    sigmoid = pl.recip(denom)\r\n    swish = pl.mul(tile_gate, sigmoid)\r\n    result = pl.mul(swish, tile_up)\r\n    pl.store(result, [0, 0], output)\r\n    return output\r\n\r\n\r\n@pl.jit.incore\r\ndef relu_kernel(x: pl.Tensor, output: pl.Out[pl.Tensor]):\r\n    \"\"\"Vector InCore: apply ReLU activation -- max(0, x).\"\"\"\r\n    tile_x = pl.load(x, [0, 0], [64, 64])\r\n    result = pl.relu(tile_x)\r\n    pl.store(result, [0, 0], output)\r\n    return output\r\n\r\n\r\n# ── FFN orchestration entries (@pl.jit) ───────────────────────────────────────\r\n\r\n\r\n@pl.jit\r\ndef ffn_gelu(\r\n    hidden_states: pl.Tensor,\r\n    gate_proj_weight: pl.Tensor,\r\n    down_proj_weight: pl.Tensor,\r\n    output: pl.Out[pl.Tensor],\r\n):\r\n    \"\"\"FFN with GELU activation.\"\"\"\r\n    # gate = hidden_states @ gate_proj_weight\r\n    gate = pl.create_tensor([64, 64], dtype=pl.FP32)\r\n    gate = matmul_kernel(hidden_states, gate_proj_weight, gate)\r\n    # activated = GELU(gate)\r\n    activated = pl.create_tensor([64, 64], dtype=pl.FP32)\r\n    activated = gelu_kernel(gate, activated)\r\n    # output = activated @ down_proj_weight\r\n    output = matmul_kernel(activated, down_proj_weight, output)\r\n    return output\r\n\r\n\r\n@pl.jit\r\ndef ffn_swiglu(\r\n    hidden_states: pl.Tensor,\r\n    gate_proj_weight: pl.Tensor,\r\n    up_proj_weight: pl.Tensor,\r\n    down_proj_weight: pl.Tensor,\r\n    output: pl.Out[pl.Tensor],\r\n):\r\n    \"\"\"FFN with SwiGLU activation.\"\"\"\r\n    # gate = hidden_states @ gate_proj_weight\r\n    gate = pl.create_tensor([64, 64], dtype=pl.FP32)\r\n    gate = matmul_kernel(hidden_states, gate_proj_weight, gate)\r\n    # up = hidden_states @ up_proj_weight\r\n    up = pl.create_tensor([64, 64], dtype=pl.FP32)\r\n    up = matmul_kernel(hidden_states, up_proj_weight, up)\r\n    # activated = SwiGLU(gate, up)\r\n    activated = pl.create_tensor([64, 64], dtype=pl.FP32)\r\n    activated = swiglu_kernel(gate, up, activated)\r\n    # output = activated @ down_proj_weight\r\n    output = matmul_kernel(activated, down_proj_weight, output)\r\n    return output\r\n\r\n\r\n@pl.jit\r\ndef ffn_relu(\r\n    hidden_states: pl.Tensor,\r\n    gate_proj_weight: pl.Tensor,\r\n    down_proj_weight: pl.Tensor,\r\n    output: pl.Out[pl.Tensor],\r\n):\r\n    \"\"\"FFN with ReLU activation.\"\"\"\r\n    # gate = hidden_states @ gate_proj_weight\r\n    gate = pl.create_tensor([64, 64], dtype=pl.FP32)\r\n    gate = matmul_kernel(hidden_states, gate_proj_weight, gate)\r\n    # activated = ReLU(gate)\r\n    activated = pl.create_tensor([64, 64], dtype=pl.FP32)\r\n    activated = relu_kernel(gate, activated)\r\n    # output = activated @ down_proj_weight\r\n    output = matmul_kernel(activated, down_proj_weight, output)\r\n    return output\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    cfg = RunConfig()\r\n    torch.manual_seed(0)\r\n\r\n    hidden_states = torch.randn(64, 64, dtype=torch.float32)\r\n    gate_proj_weight = torch.randn(64, 64, dtype=torch.float32)\r\n    up_proj_weight = torch.randn(64, 64, dtype=torch.float32)\r\n    down_proj_weight = torch.randn(64, 64, dtype=torch.float32)\r\n\r\n    # FFN + GELU: GELU(hidden @ gate_proj) @ down_proj, GELU = x * sigmoid(1.702 * x)\r\n    output = torch.zeros(64, 64, dtype=torch.float32)\r\n    ffn_gelu(hidden_states, gate_proj_weight, down_proj_weight, output, config=cfg)\r\n    gate = hidden_states @ gate_proj_weight\r\n    expected_gelu = (gate * torch.sigmoid(1.702 * gate)) @ down_proj_weight\r\n    assert torch.allclose(output, expected_gelu, rtol=3e-3, atol=3e-3), (\r\n        f\"ffn_gelu failed: max diff = {(output - expected_gelu).abs().max().item()}\"\r\n    )\r\n\r\n    # FFN + SwiGLU: SwiGLU(gate, up) @ down_proj, SwiGLU = gate * sigmoid(gate) * up\r\n    output = torch.zeros(64, 64, dtype=torch.float32)\r\n    ffn_swiglu(hidden_states, gate_proj_weight, up_proj_weight, down_proj_weight, output, config=cfg)\r\n    gate = hidden_states @ gate_proj_weight\r\n    up = hidden_states @ up_proj_weight\r\n    expected_swiglu = (gate * torch.sigmoid(gate) * up) @ down_proj_weight\r\n    assert torch.allclose(output, expected_swiglu, rtol=3e-3, atol=3e-3), (\r\n        f\"ffn_swiglu failed: max diff = {(output - expected_swiglu).abs().max().item()}\"\r\n    )\r\n\r\n    # FFN + ReLU: ReLU(hidden @ gate_proj) @ down_proj\r\n    output = torch.zeros(64, 64, dtype=torch.float32)\r\n    ffn_relu(hidden_states, gate_proj_weight, down_proj_weight, output, config=cfg)\r\n    gate = hidden_states @ gate_proj_weight\r\n    expected_relu = torch.relu(gate) @ down_proj_weight\r\n    assert torch.allclose(output, expected_relu, rtol=3e-3, atol=3e-3), (\r\n        f\"ffn_relu failed: max diff = {(output - expected_relu).abs().max().item()}\"\r\n    )\r\n\r\n    print(\"OK\")\r\n","examples/models/02_vector_dag.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"\r\nVector DAG computation with 3 InCore kernels and 1 JIT orchestration entry.\r\n\r\nImplements: f = (a + b + 1)(a + b + 2) + (a + b)\r\n\r\nTask graph:\r\n  t0: c = kernel_add(a, b)\r\n  t1: d = kernel_add_scalar(c, 1.0)\r\n  t2: e = kernel_add_scalar(c, 2.0)\r\n  t3: g = kernel_mul(d, e)\r\n  t4: f = kernel_add(g, c)\r\n\r\nDependencies: t0->t1, t0->t2, t1->t3, t2->t3, t3->t4, t0->t4\r\n\r\nConcepts introduced:\r\n  - Multi-kernel orchestration with task dependencies\r\n  - pl.Scalar parameter type\r\n  - Intermediate tensors allocated via pl.create_tensor in the orchestration entry\r\n  - golden() reference for runtime verification\r\n\r\nRun:  python examples/models/02_vector_dag.py  (requires hardware)\r\nNext: examples/models/03_flash_attention.py\r\n\"\"\"\r\n\r\nimport argparse\r\n\r\nimport pypto.language as pl\r\nimport torch\r\nfrom pypto.runtime import RunConfig\r\n\r\n# ── Vector DAG (128x128) kernels ─────────────────────────────────────────────\r\n\r\n\r\n@pl.jit.incore\r\ndef kernel_add_128(a: pl.Tensor, b: pl.Tensor, output: pl.Out[pl.Tensor]):\r\n    \"\"\"Adds two tensors element-wise: result = a + b\"\"\"\r\n    a_tile = pl.load(a, [0, 0], [128, 128])\r\n    b_tile = pl.load(b, [0, 0], [128, 128])\r\n    result = pl.add(a_tile, b_tile)\r\n    pl.store(result, [0, 0], output)\r\n    return output\r\n\r\n\r\n@pl.jit.incore\r\ndef kernel_add_scalar_128(\r\n    a: pl.Tensor,\r\n    scalar: pl.Scalar[pl.FP32],\r\n    output: pl.Out[pl.Tensor],\r\n):\r\n    \"\"\"Adds a scalar to each element: result = a + scalar\"\"\"\r\n    x = pl.load(a, [0, 0], [128, 128])\r\n    result = pl.add(x, scalar)\r\n    pl.store(result, [0, 0], output)\r\n    return output\r\n\r\n\r\n@pl.jit.incore\r\ndef kernel_mul_128(a: pl.Tensor, b: pl.Tensor, output: pl.Out[pl.Tensor]):\r\n    \"\"\"Multiplies two tensors element-wise: result = a * b\"\"\"\r\n    a_tile = pl.load(a, [0, 0], [128, 128])\r\n    b_tile = pl.load(b, [0, 0], [128, 128])\r\n    result = pl.mul(a_tile, b_tile)\r\n    pl.store(result, [0, 0], output)\r\n    return output\r\n\r\n\r\n@pl.jit\r\ndef vector_dag(a: pl.Tensor, b: pl.Tensor, f: pl.Out[pl.Tensor]):\r\n    \"\"\"Orchestration for formula: f = (a + b + 1)(a + b + 2) + (a + b)\r\n\r\n    Task graph:\r\n      t0: c = kernel_add(a, b)\r\n      t1: d = kernel_add_scalar(c, 1.0)\r\n      t2: e = kernel_add_scalar(c, 2.0)\r\n      t3: g = kernel_mul(d, e)\r\n      t4: f = kernel_add(g, c)\r\n    \"\"\"\r\n    c = pl.create_tensor([128, 128], dtype=pl.FP32)\r\n    c = kernel_add_128(a, b, c)\r\n    d = pl.create_tensor([128, 128], dtype=pl.FP32)\r\n    d = kernel_add_scalar_128(c, 1.0, d)\r\n    e = pl.create_tensor([128, 128], dtype=pl.FP32)\r\n    e = kernel_add_scalar_128(c, 2.0, e)\r\n    g = pl.create_tensor([128, 128], dtype=pl.FP32)\r\n    g = kernel_mul_128(d, e, g)\r\n    f = kernel_add_128(g, c, f)\r\n    return f\r\n\r\n\r\n# ── Smaller orchestration DAG (16x16) used by codegen tests ──────────────────\r\n\r\n\r\n@pl.jit.incore\r\ndef kernel_add_16(a: pl.Tensor, b: pl.Tensor, output: pl.Out[pl.Tensor]):\r\n    \"\"\"Adds two tensors element-wise: result = a + b\"\"\"\r\n    a_tile = pl.load(a, [0, 0], [16, 16])\r\n    b_tile = pl.load(b, [0, 0], [16, 16])\r\n    result = pl.add(a_tile, b_tile)\r\n    pl.store(result, [0, 0], output)\r\n    return output\r\n\r\n\r\n@pl.jit.incore\r\ndef kernel_add_scalar_16(\r\n    a: pl.Tensor,\r\n    scalar: pl.Scalar[pl.FP32],\r\n    output: pl.Out[pl.Tensor],\r\n):\r\n    \"\"\"Adds a scalar to each element: result = a + scalar\"\"\"\r\n    x = pl.load(a, [0, 0], [16, 16])\r\n    result = pl.add(x, scalar)\r\n    pl.store(result, [0, 0], output)\r\n    return output\r\n\r\n\r\n@pl.jit.incore\r\ndef kernel_mul_16(a: pl.Tensor, b: pl.Tensor, output: pl.Out[pl.Tensor]):\r\n    \"\"\"Multiplies two tensors element-wise: result = a * b\"\"\"\r\n    a_tile = pl.load(a, [0, 0], [16, 16])\r\n    b_tile = pl.load(b, [0, 0], [16, 16])\r\n    result = pl.mul(a_tile, b_tile)\r\n    pl.store(result, [0, 0], output)\r\n    return output\r\n\r\n\r\n@pl.jit\r\ndef example_orch(a: pl.Tensor, b: pl.Tensor, f_result: pl.Out[pl.Tensor]):\r\n    \"\"\"Simpler orchestration DAG (16x16): f = (a + b + 1)(a + b + 2)\r\n\r\n    Used by codegen tests. 4 tasks, 3 InCore kernels.\r\n    \"\"\"\r\n    c = pl.create_tensor([16, 16], dtype=pl.FP32)\r\n    c = kernel_add_16(a, b, c)\r\n    d = pl.create_tensor([16, 16], dtype=pl.FP32)\r\n    d = kernel_add_scalar_16(c, 1.0, d)\r\n    e = pl.create_tensor([16, 16], dtype=pl.FP32)\r\n    e = kernel_add_scalar_16(c, 2.0, e)\r\n    f_result = kernel_mul_16(d, e, f_result)\r\n    return f_result\r\n\r\n\r\ndef golden(tensors: dict, params: dict | None = None) -> None:\r\n    \"\"\"Reference computation: f = (a + b + 1)(a + b + 2) + (a + b).\"\"\"\r\n    a = tensors[\"a\"].float()\r\n    b = tensors[\"b\"].float()\r\n    c = a + b\r\n    tensors[\"f\"][:] = (c + 1.0) * (c + 2.0) + c\r\n\r\n\r\ndef main():\r\n    parser = argparse.ArgumentParser(description=\"Vector DAG example\")\r\n    parser.add_argument(\r\n        \"--enable-l2-swimlane\",\r\n        action=\"store_true\",\r\n        default=False,\r\n        help=\"Enable on-device runtime profiling and generate swimlane JSON\",\r\n    )\r\n    args = parser.parse_args()\r\n\r\n    a = torch.full((128, 128), 2.0, dtype=torch.float32)\r\n    b = torch.full((128, 128), 3.0, dtype=torch.float32)\r\n    f = torch.zeros((128, 128), dtype=torch.float32)\r\n\r\n    vector_dag(\r\n        a,\r\n        b,\r\n        f,\r\n        config=RunConfig(enable_l2_swimlane=args.enable_l2_swimlane),\r\n    )\r\n\r\n    # Golden validation\r\n    tensors = {\"a\": a, \"b\": b, \"f\": f.clone()}\r\n    golden(tensors)\r\n    expected_f = tensors[\"f\"]\r\n    assert torch.allclose(f, expected_f, rtol=1e-5, atol=1e-5), (\r\n        f\"Validation failed: max diff = {(f - expected_f).abs().max().item()}\"\r\n    )\r\n    print(\"OK\")\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    main()\r\n","examples/models/03_flash_attention.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"\r\nFlash Attention with loop-level iter_args.\r\n\r\nDemonstrates advanced DSL control flow:\r\n  - pl.range with init_values for loop-carried state (iter_args)\r\n  - Nested if/else with pl.yield_ for SSA phi nodes\r\n  - Online softmax with running max/sum accumulators\r\n  - Multi-output yield for updating loop state\r\n\r\nAlgorithm:\r\n  For each KV block j in [0, 16):\r\n    sij = Q @ Kj^T (scaled)\r\n    pij = softmax(sij) with online max/sum correction\r\n    Oi = update(Oi, pij @ Vj)\r\n  Return Oi / li (final normalization)\r\n\r\nRun:  python examples/models/03_flash_attention.py\r\nNext: examples/models/04_paged_attention.py\r\n\"\"\"\r\n\r\nimport pypto.language as pl\r\n\r\n\r\n@pl.jit\r\ndef flash_attention(q_13: pl.Tensor, k_16: pl.Tensor, v_19: pl.Tensor):\r\n    with pl.at(level=pl.Level.CORE_GROUP):\r\n        attn_initial = pl.create_tensor([64, 128], dtype=pl.FP32)\r\n        oi_update_initial = pl.create_tensor([64, 128], dtype=pl.FP32)\r\n        li_update_initial = pl.create_tensor([64, 1], dtype=pl.FP32)\r\n        mi_update_initial = pl.create_tensor([64, 1], dtype=pl.FP32)\r\n\r\n        # statement.for with iter_args → pl.range with tuple unpacking\r\n        for i, (mi_update, li_update, attn_update, oi_update) in pl.range(\r\n            16,\r\n            init_values=(\r\n                mi_update_initial,\r\n                li_update_initial,\r\n                attn_initial,\r\n                oi_update_initial,\r\n            ),\r\n        ):\r\n            # Inner statement.block\r\n            kj = pl.slice(k_16, [64, 128], [i * 64, 0])\r\n            vj = pl.slice(v_19, [64, 128], [i * 64, 0])\r\n            sij = pl.matmul(q_13, kj, out_dtype=pl.FP16, a_trans=False, b_trans=True, c_matrix_nz=False)\r\n            sij_1 = pl.mul(sij, 0.0883883)\r\n            row_max = pl.row_max(sij_1)\r\n            sub = pl.sub(sij_1, row_max)\r\n            p_ij = pl.exp(sub)\r\n            l_ij = pl.row_sum(p_ij)\r\n            tildaPij_83 = pl.cast(p_ij, target_type=pl.FP16, mode=\"round\")\r\n\r\n            # Nested if with yield (SSA phi node)\r\n            if i == 0:\r\n                # Inner statement.block\r\n                oiUpdate_87 = pl.matmul(tildaPij_83, vj, out_dtype=pl.FP16)\r\n                oiUpdate_90 = pl.assemble(oi_update, oiUpdate_87, offset=[0, 0])\r\n\r\n                # Nested if inside first branch\r\n                if i == 15:\r\n                    attn_94 = pl.div(oiUpdate_90, l_ij)\r\n                    attn_95 = pl.yield_(attn_94)\r\n                else:\r\n                    attn_95 = pl.yield_(attn_update)\r\n\r\n                # More statements in first branch\r\n                liUpdate_98 = pl.assemble(li_update, l_ij, offset=[0, 0])\r\n                miUpdate_101 = pl.assemble(mi_update, row_max, offset=[0, 0])\r\n\r\n                # statement.yield → pl.yield_ with assignment\r\n                miUpdate_126, liUpdate_127, attn_128, oiUpdate_129 = pl.yield_(\r\n                    miUpdate_101, liUpdate_98, attn_95, oiUpdate_90\r\n                )\r\n            else:\r\n                # Else branch\r\n                mi_102 = pl.create_tensor(shape=[64, 1], dtype=pl.FP32)\r\n                miUpdate_103 = pl.maximum(mi_102, row_max)\r\n                t1_104 = pl.sub(mi_102, miUpdate_103)\r\n                t2_105 = pl.exp(t1_104)\r\n                t3_106 = pl.sub(row_max, miUpdate_103)\r\n                t4_107 = pl.exp(t3_106)\r\n                t5_108 = pl.mul(t4_107, l_ij)\r\n                t6_109 = pl.mul(t2_105, li_update)\r\n                liUpdate_110 = pl.add(t6_109, t5_108)\r\n                liUpdate_113 = pl.assemble(li_update, liUpdate_110, offset=[0, 0])\r\n                q3_114 = pl.mul(oi_update, t2_105)\r\n                q1_115 = pl.matmul(\r\n                    tildaPij_83, vj, out_dtype=pl.FP16, a_trans=False, b_trans=False, c_matrix_nz=False\r\n                )\r\n                q2_116 = pl.mul(q1_115, t4_107)\r\n                oiUpdate_117 = pl.add(q3_114, q2_116)\r\n                oiUpdate_120 = pl.assemble(oi_update, oiUpdate_117, offset=[0, 0])\r\n\r\n                # Nested if in else branch\r\n                if i == 15:\r\n                    attn_124 = pl.div(oiUpdate_120, liUpdate_113)\r\n                    attn_125 = pl.yield_(attn_124)\r\n                else:\r\n                    attn_125 = pl.yield_(attn_update)\r\n\r\n                miUpdate_126, liUpdate_127, attn_128, oiUpdate_129 = pl.yield_(\r\n                    miUpdate_103, liUpdate_113, attn_125, oiUpdate_120\r\n                )\r\n\r\n            # For loop yield (updates iter_args for next iteration)\r\n            mi_final, li_final, attn_final, oi_final = pl.yield_(\r\n                miUpdate_126, liUpdate_127, attn_128, oiUpdate_129\r\n            )\r\n    return attn_final\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    # The body currently fails IR verification at pipeline_input due to a\r\n    # pre-existing IfStmt yield/return_vars structural mismatch in the original\r\n    # @pl.function example (which only ever called print() and never went\r\n    # through the pass pipeline).  See KNOWN_ISSUES.md for the tracking entry.\r\n    # Until that is fixed, this entry only verifies that the JIT decorator\r\n    # wraps and the Python parser accepts the source -- it does NOT execute.\r\n    print(flash_attention)\r\n    print(\"SKIPPED: flash_attention body fails IR verification (see KNOWN_ISSUES.md)\")\r\n","examples/models/04_paged_attention.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\"\"\"\r\nPaged Attention Orchestration Example\r\n\r\nBuilds a paged attention orchestration function using the PyPTO DSL with online\r\nsoftmax and a 4-kernel pipeline.  Use build_paged_attention_program() to\r\nobtain a @pl.program class parameterised by runtime tensor dimensions.\r\n\r\nTensor layout (all 2D, flattened):\r\n  query:       [batch * num_heads, head_dim]                    BF16\r\n  key_cache:   [total_pool_blocks * block_size, head_dim]       BF16\r\n  value_cache: [total_pool_blocks * block_size, head_dim]       BF16\r\n  out:         [batch * num_heads, head_dim]                    FP32\r\n\r\nPipeline per KV block iteration:\r\n  1. QK Matmul:       sij          = kernel_qk_matmul(qi, kj, sij)\r\n  2. Softmax Prepare: pij, mi, li  = kernel_softmax_prepare(sij_valid, scale, pij, mi, li)\r\n  3. PV Matmul:       oi_tmp       = kernel_pv_matmul(pij, vj, oi_tmp)\r\n  4. Online Update:   mi, li, oi, dst = kernel_online_update(\r\n                          mi_j, li_j, oi_new, mi, li, oi, dst, is_first, is_last)\r\n\r\nShared InCore kernels (module-level @pl.function):\r\n  kernel_init_inplace, kernel_qk_matmul, kernel_softmax_prepare,\r\n  kernel_pv_matmul, kernel_online_update\r\n\r\nThese can be imported and reused by other @pl.program definitions.\r\n\"\"\"\r\n\r\nimport argparse\r\nimport struct\r\n\r\nimport pypto.language as pl\r\nimport torch\r\nfrom pypto.backend import BackendType\r\nfrom pypto.ir.pass_manager import OptimizationStrategy\r\nfrom pypto.runtime import RunConfig, run\r\n\r\n# ── Shared InCore kernels (module-level, reusable across programs) ──────────\r\n\r\n\r\n@pl.function(type=pl.FunctionType.InCore)\r\ndef kernel_init_inplace(\r\n    oi: pl.Out[pl.Tensor[[16, 128], pl.FP32]],\r\n    li: pl.Out[pl.Tensor[[16, 1], pl.FP32]],\r\n    mi: pl.Out[pl.Tensor[[16, 1], pl.FP32]],\r\n) -> tuple[\r\n    pl.Tensor[[16, 128], pl.FP32],\r\n    pl.Tensor[[16, 1], pl.FP32],\r\n    pl.Tensor[[16, 1], pl.FP32],\r\n]:\r\n    \"\"\"Initialize inplace accumulators to zero (VECTOR).\"\"\"\r\n    return oi, li, mi\r\n\r\n\r\n@pl.function(type=pl.FunctionType.InCore)\r\ndef kernel_qk_matmul(\r\n    qi: pl.Tensor[[16, 128], pl.BF16],\r\n    kj: pl.Tensor[[128, 128], pl.BF16],\r\n    output: pl.Out[pl.Tensor[[16, 128], pl.FP32]],\r\n) -> pl.Tensor[[16, 128], pl.FP32]:\r\n    \"\"\"QK matmul: sij = qi @ kj.T (CUBE). kj reinterpreted as its transpose on L1.\"\"\"\r\n    qi_l1 = pl.load(qi, [0, 0], [16, 128], target_memory=pl.MemorySpace.Mat)\r\n    kj_nat = pl.load(kj, [0, 0], [128, 128], target_memory=pl.MemorySpace.Mat)\r\n    kj_l1 = pl.tile.transpose_view(kj_nat)\r\n    qi_l0a = pl.move(qi_l1, target_memory=pl.MemorySpace.Left)\r\n    kj_l0b = pl.move(kj_l1, target_memory=pl.MemorySpace.Right)\r\n    sij_l0c = pl.matmul(qi_l0a, kj_l0b)\r\n    out = pl.store(sij_l0c, [0, 0], output)\r\n    return out\r\n\r\n\r\n@pl.function(type=pl.FunctionType.InCore)\r\ndef kernel_softmax_prepare(\r\n    sij: pl.Tensor[[16, 128], pl.FP32],\r\n    scale: pl.Scalar[pl.FP32],\r\n    out_pij: pl.Out[pl.Tensor[[16, 128], pl.BF16]],\r\n    out_mi: pl.Out[pl.Tensor[[16, 1], pl.FP32]],\r\n    out_li: pl.Out[pl.Tensor[[16, 1], pl.FP32]],\r\n) -> tuple[\r\n    pl.Tensor[[16, 128], pl.BF16],\r\n    pl.Tensor[[16, 1], pl.FP32],\r\n    pl.Tensor[[16, 1], pl.FP32],\r\n]:\r\n    \"\"\"Softmax prepare: scale, row_max, exp, row_sum (VECTOR).\"\"\"\r\n    s_tile = pl.load(sij, [0, 0], [16, 128], target_memory=pl.MemorySpace.Vec)\r\n    scaled = pl.mul(s_tile, scale)\r\n    tmp_tile = pl.create_tile([16, 128], dtype=pl.FP32, target_memory=pl.MemorySpace.Vec)\r\n    mi_tile = pl.row_max(scaled, tmp_tile)\r\n    sij_centered = pl.row_expand_sub(scaled, mi_tile)\r\n    exp_tile = pl.exp(sij_centered)\r\n    pij_tile_bf16 = pl.cast(exp_tile, target_type=pl.BF16)\r\n    pij_tile = pl.cast(pij_tile_bf16, target_type=pl.FP32)\r\n    li_tile = pl.row_sum(pij_tile, tmp_tile)\r\n    out_pij = pl.store(pij_tile_bf16, [0, 0], out_pij)\r\n    out_mi = pl.store(mi_tile, [0, 0], out_mi)\r\n    out_li = pl.store(li_tile, [0, 0], out_li)\r\n    return out_pij, out_mi, out_li\r\n\r\n\r\n@pl.function(type=pl.FunctionType.InCore)\r\ndef kernel_softmax_prepare_unaligned(\r\n    sij: pl.Tensor[[16, 128], pl.FP32],\r\n    scale: pl.Scalar[pl.FP32],\r\n    valid_len: pl.Scalar[pl.INDEX],\r\n    out_pij: pl.Out[pl.Tensor[[16, 128], pl.BF16]],\r\n    out_mi: pl.Out[pl.Tensor[[16, 1], pl.FP32]],\r\n    out_li: pl.Out[pl.Tensor[[16, 1], pl.FP32]],\r\n) -> tuple[\r\n    pl.Tensor[[16, 128], pl.BF16],\r\n    pl.Tensor[[16, 1], pl.FP32],\r\n    pl.Tensor[[16, 1], pl.FP32],\r\n]:\r\n    \"\"\"Softmax prepare with unaligned valid_len: load, set_validshape, fillpad, scale, softmax (VECTOR).\"\"\"\r\n    s_tile = pl.load(sij, [0, 0], [16, 128], valid_shapes=[16, valid_len], target_memory=pl.MemorySpace.Vec)\r\n    s_padded = pl.tile.fillpad(s_tile, pad_value=pl.PadValue.min)\r\n    scaled = pl.mul(s_padded, scale)\r\n    tmp_tile = pl.create_tile([16, 128], dtype=pl.FP32, target_memory=pl.MemorySpace.Vec)\r\n    mi_tile = pl.row_max(scaled, tmp_tile)\r\n    sij_centered = pl.row_expand_sub(scaled, mi_tile)\r\n    exp_tile = pl.exp(sij_centered)\r\n    pij_tile_bf16 = pl.cast(exp_tile, target_type=pl.BF16)\r\n    pij_tile = pl.cast(pij_tile_bf16, target_type=pl.FP32)\r\n    li_tile = pl.row_sum(pij_tile, tmp_tile)\r\n    out_pij = pl.store(pij_tile_bf16, [0, 0], out_pij)\r\n    out_mi = pl.store(mi_tile, [0, 0], out_mi)\r\n    out_li = pl.store(li_tile, [0, 0], out_li)\r\n    return out_pij, out_mi, out_li\r\n\r\n\r\n@pl.function(type=pl.FunctionType.InCore)\r\ndef kernel_pv_matmul(\r\n    pij: pl.Tensor[[16, 128], pl.BF16],\r\n    vj: pl.Tensor[[128, 128], pl.BF16],\r\n    output: pl.Out[pl.Tensor[[16, 128], pl.FP32]],\r\n) -> pl.Tensor[[16, 128], pl.FP32]:\r\n    \"\"\"PV matmul: oi_tmp = pij @ vj (CUBE).\"\"\"\r\n    pij_l1 = pl.load(pij, [0, 0], [16, 128], target_memory=pl.MemorySpace.Mat)\r\n    vj_l1 = pl.load(vj, [0, 0], [128, 128], target_memory=pl.MemorySpace.Mat)\r\n    pij_l0a = pl.move(pij_l1, target_memory=pl.MemorySpace.Left)\r\n    vj_l0b = pl.move(vj_l1, target_memory=pl.MemorySpace.Right)\r\n    oi_l0c = pl.matmul(pij_l0a, vj_l0b)\r\n    out = pl.store(oi_l0c, [0, 0], output)\r\n    return out\r\n\r\n\r\n@pl.function(type=pl.FunctionType.InCore)\r\ndef kernel_online_update(\r\n    mij: pl.Tensor[[16, 1], pl.FP32],\r\n    lij: pl.Tensor[[16, 1], pl.FP32],\r\n    oi_new: pl.Tensor[[16, 128], pl.FP32],\r\n    mi: pl.InOut[pl.Tensor[[16, 1], pl.FP32]],\r\n    li: pl.InOut[pl.Tensor[[16, 1], pl.FP32]],\r\n    oi: pl.InOut[pl.Tensor[[16, 128], pl.FP32]],\r\n    dst: pl.Out[pl.Tensor[[16, 128], pl.FP32]],\r\n    is_first: pl.Scalar[pl.BOOL],\r\n    is_last: pl.Scalar[pl.BOOL],\r\n) -> tuple[\r\n    pl.Tensor[[16, 1], pl.FP32],\r\n    pl.Tensor[[16, 1], pl.FP32],\r\n    pl.Tensor[[16, 128], pl.FP32],\r\n    pl.Tensor[[16, 128], pl.FP32],\r\n]:\r\n    \"\"\"Online softmax update with inplace mi/li/oi (VECTOR).\"\"\"\r\n    mij_tile = pl.load(mij, [0, 0], [16, 1], target_memory=pl.MemorySpace.Vec)\r\n    lij_tile = pl.load(lij, [0, 0], [16, 1], target_memory=pl.MemorySpace.Vec)\r\n    oi_new_tile = pl.load(oi_new, [0, 0], [16, 128], target_memory=pl.MemorySpace.Vec)\r\n    mi_tile = pl.load(mi, [0, 0], [16, 1], target_memory=pl.MemorySpace.Vec)\r\n    li_tile = pl.load(li, [0, 0], [16, 1], target_memory=pl.MemorySpace.Vec)\r\n    oi_tile = pl.load(oi, [0, 0], [16, 128], target_memory=pl.MemorySpace.Vec)\r\n\r\n    if is_first:\r\n        mi_out = pl.store(mij_tile, [0, 0], mi)\r\n        li_out = pl.store(lij_tile, [0, 0], li)\r\n        oi_out = pl.store(oi_new_tile, [0, 0], oi)\r\n        if is_last:\r\n            dst_tile = pl.row_expand_div(oi_new_tile, lij_tile)\r\n            dst_out = pl.store(dst_tile, [0, 0], dst)\r\n        else:\r\n            # First block but not last: dst is not yet meaningful, store zeros\r\n            zero_tile = pl.tile.full([16, 128], dtype=pl.FP32, value=0.0)\r\n            dst_out = pl.store(zero_tile, [0, 0], dst)\r\n    else:\r\n        # Reshape DN [16,1] -> ND [1,16] for element-wise ops\r\n        mi_tile_nd = pl.reshape(mi_tile, [1, 16])\r\n        mij_tile_nd = pl.reshape(mij_tile, [1, 16])\r\n        li_tile_nd = pl.reshape(li_tile, [1, 16])\r\n        lij_tile_nd = pl.reshape(lij_tile, [1, 16])\r\n\r\n        mi_new = pl.maximum(mi_tile_nd, mij_tile_nd)\r\n        mi_diff = pl.sub(mi_tile_nd, mi_new)\r\n        alpha = pl.exp(mi_diff)\r\n        mij_diff = pl.sub(mij_tile_nd, mi_new)\r\n        beta = pl.exp(mij_diff)\r\n\r\n        li_scaled = pl.mul(alpha, li_tile_nd)\r\n        lij_scaled = pl.mul(beta, lij_tile_nd)\r\n        li_updated = pl.add(li_scaled, lij_scaled)\r\n\r\n        alpha_dn = pl.reshape(alpha, [16, 1])  # Reshape [1,16] -> [16,1] DN for row_expand_mul\r\n        oi_scaled = pl.row_expand_mul(oi_tile, alpha_dn)\r\n        beta_dn = pl.reshape(beta, [16, 1])  # Reshape [1,16] -> [16,1] DN for row_expand_mul\r\n        oi_new_scaled = pl.row_expand_mul(oi_new_tile, beta_dn)\r\n        oi_updated = pl.add(oi_scaled, oi_new_scaled)\r\n\r\n        mi_new_dn = pl.reshape(mi_new, [16, 1])  # Reshape back to DN [16,1] for store\r\n        li_updated_dn = pl.reshape(li_updated, [16, 1])  # Reshape back to DN [16,1] for store\r\n\r\n        mi_out = pl.store(mi_new_dn, [0, 0], mi)\r\n        li_out = pl.store(li_updated_dn, [0, 0], li)\r\n\r\n        if is_last:\r\n            dst_tile = pl.row_expand_div(oi_updated, li_updated_dn)\r\n            dst_out = pl.store(dst_tile, [0, 0], dst)\r\n            oi_out = pl.store(oi_updated, [0, 0], oi)\r\n        else:\r\n            zero_tile = pl.tile.full([16, 128], dtype=pl.FP32, value=0.0)\r\n            dst_out = pl.store(zero_tile, [0, 0], dst)\r\n            oi_out = pl.store(oi_updated, [0, 0], oi)\r\n\r\n    return mi_out, li_out, oi_out, dst_out\r\n\r\n\r\ndef build_paged_attention_program(\r\n    batch: int,\r\n    num_heads: int,\r\n    head_dim: int,\r\n    block_size: int,\r\n    max_num_blocks_per_req: int,\r\n    q_tile: int = 16,\r\n):\r\n    \"\"\"Build a parameterised paged-attention @pl.program for the given shapes.\r\n\r\n    Returns the decorated program class (not an instance).  The tensor type\r\n    annotations in the orchestration function are filled in from the arguments\r\n    so that the PyPTO DSL can resolve static dimensions at compile time.\r\n\r\n    Parameters\r\n    ----------\r\n    batch:                  number of requests in the batch\r\n    num_heads:              number of query heads\r\n    head_dim:               per-head feature dimension\r\n    block_size:             KV-cache block size (rows per physical block)\r\n    max_num_blocks_per_req: maximum number of KV blocks per request\r\n    q_tile:                 query-head tile size used by the InCore kernels\r\n    \"\"\"\r\n    # Derived static dimension values for tensor type annotations\r\n    query_rows = batch * num_heads\r\n    key_cache_rows = batch * max_num_blocks_per_req * block_size\r\n    out_rows = batch * num_heads\r\n    block_table_flat_size = batch * max_num_blocks_per_req\r\n\r\n    @pl.program\r\n    class PagedAttentionProgram:\r\n        \"\"\"Paged attention program with CUBE and VECTOR kernels (online softmax).\r\n\r\n        InCore kernels (kernel_init_inplace, kernel_qk_matmul,\r\n        kernel_softmax_prepare, kernel_pv_matmul, kernel_online_update) are\r\n        defined at module level and automatically added to this program when\r\n        called from the orchestration function.\r\n        \"\"\"\r\n\r\n        # ── Orchestration function ──────────────────────────────────────────\r\n        # Parameters: query, key_cache, value_cache, block_table, context_lens,\r\n        #             out, config (7 tensors)\r\n        @pl.function(type=pl.FunctionType.Orchestration)\r\n        def paged_attention(\r\n            self,\r\n            query: pl.Tensor[[query_rows, head_dim], pl.BF16],\r\n            key_cache: pl.Tensor[[key_cache_rows, head_dim], pl.BF16],\r\n            value_cache: pl.Tensor[[key_cache_rows, head_dim], pl.BF16],\r\n            block_table: pl.Tensor[[block_table_flat_size], pl.INT32],\r\n            context_lens: pl.Tensor[[batch], pl.INT32],\r\n            out: pl.Out[pl.Tensor[[out_rows, head_dim], pl.FP32]],\r\n            config: pl.Tensor[[7], pl.INT64],\r\n        ) -> pl.Tensor[[out_rows, head_dim], pl.FP32]:\r\n            \"\"\"Paged attention orchestration.\r\n\r\n            Outer loops: batch → q_tile groups → KV blocks (bn).\r\n            For each KV block, executes the 4-stage kernel pipeline.\r\n            Config layout: [batch, num_heads, kv_head_num, head_dim, block_size, block_num, scale_bits]\r\n            \"\"\"\r\n            # Read runtime config parameters\r\n            batch_cfg = pl.tensor.read(config, [0])\r\n            num_heads_cfg = pl.tensor.read(config, [1])\r\n            head_dim_cfg = pl.tensor.read(config, [3])\r\n            block_size_cfg = pl.tensor.read(config, [4])\r\n            block_num_cfg = pl.tensor.read(config, [5])\r\n            # scale_bits at config[6] - decoded as float\r\n\r\n            q_head_num = num_heads_cfg\r\n            q_loop_cfg = (q_head_num + q_tile - 1) // q_tile\r\n\r\n            for b_idx in pl.range(batch_cfg):\r\n                cur_seq = pl.tensor.read(context_lens, [b_idx])\r\n                bn_this_batch = (cur_seq + block_size_cfg - 1) // block_size_cfg\r\n                for q_idx in pl.range(q_loop_cfg):\r\n                    cur_offset = b_idx * q_head_num + q_idx * q_tile\r\n\r\n                    # Create inplace accumulators for this q_tile group\r\n                    oi_buf = pl.create_tensor([q_tile, head_dim_cfg], dtype=pl.FP32)\r\n                    li_buf = pl.create_tensor([q_tile, 1], dtype=pl.FP32)\r\n                    mi_buf = pl.create_tensor([q_tile, 1], dtype=pl.FP32)\r\n\r\n                    # Initialize accumulators via shared module-level InCore kernel\r\n                    oi, li_update, mi_update = kernel_init_inplace(oi_buf, li_buf, mi_buf)\r\n\r\n                    for bn in pl.range(bn_this_batch):\r\n                        # Query view: row offset = b_idx * num_heads + q_idx * q_tile\r\n                        qi = pl.slice(query, [q_tile, head_dim_cfg], [cur_offset, 0])\r\n\r\n                        # Get block index from block_table\r\n                        cur_block_idx = pl.tensor.read(block_table, [b_idx * block_num_cfg + bn])\r\n                        valid_len = pl.min(block_size_cfg, cur_seq - bn * block_size_cfg)\r\n\r\n                        # Key/Value views: physical block row = cur_block_idx * block_size\r\n                        kv_block_row = cur_block_idx * block_size_cfg\r\n                        kj = pl.slice(key_cache, [block_size_cfg, head_dim_cfg], [kv_block_row, 0])\r\n                        vj = pl.slice(value_cache, [block_size_cfg, head_dim_cfg], [kv_block_row, 0])\r\n\r\n                        sij_buf = pl.create_tensor([q_tile, block_size_cfg], dtype=pl.FP32)\r\n\r\n                        # QK matmul (CUBE) via shared module-level InCore kernel\r\n                        sij = kernel_qk_matmul(qi, kj, sij_buf)\r\n                        sij_valid = pl.slice(sij, [q_tile, valid_len], [0, 0])\r\n\r\n                        pij_f16_buf = pl.create_tensor([q_tile, block_size_cfg], dtype=pl.BF16)\r\n                        mi_sm_buf = pl.create_tensor([q_tile, 1], dtype=pl.FP32)\r\n                        li_sm_buf = pl.create_tensor([q_tile, 1], dtype=pl.FP32)\r\n\r\n                        # Softmax prepare (VECTOR) via shared module-level InCore kernel\r\n                        pij_f16, mi, li = kernel_softmax_prepare(\r\n                            sij_valid,\r\n                            1.0,\r\n                            pij_f16_buf,\r\n                            mi_sm_buf,\r\n                            li_sm_buf,\r\n                        )\r\n\r\n                        oi_tmp_buf = pl.create_tensor([q_tile, head_dim_cfg], dtype=pl.FP32)\r\n                        # PV matmul (CUBE) via shared module-level InCore kernel\r\n                        oi_tmp = kernel_pv_matmul(pij_f16, vj, oi_tmp_buf)\r\n\r\n                        # Conditional flags\r\n                        if bn == 0:\r\n                            is_first = pl.yield_(1)\r\n                        else:\r\n                            is_first = pl.yield_(0)\r\n                        if bn == bn_this_batch - 1:\r\n                            is_last = pl.yield_(1)\r\n                        else:\r\n                            is_last = pl.yield_(0)\r\n\r\n                        # Output view: same row offset as query view\r\n                        out_view_buf = pl.slice(out, [q_tile, head_dim_cfg], [cur_offset, 0])\r\n                        # Online softmax update via shared module-level InCore kernel\r\n                        mi_update, li_update, oi, _out_view = kernel_online_update(\r\n                            mi, li, oi_tmp, mi_update, li_update, oi, out_view_buf, is_first, is_last\r\n                        )\r\n\r\n            return out\r\n\r\n    return PagedAttentionProgram\r\n\r\n\r\ndef build_paged_attention_unaligned_program(\r\n    batch: int,\r\n    num_heads: int,\r\n    head_dim: int,\r\n    block_size: int,\r\n    max_num_blocks_per_req: int,\r\n    q_tile: int = 16,\r\n):\r\n    \"\"\"Build a paged-attention program using set_validshape for unaligned blocks.\r\n\r\n    Unlike build_paged_attention_program which slices sij to [q_tile, valid_len],\r\n    this variant passes the full sij tensor to kernel_softmax_prepare_unaligned\r\n    with valid_len as a scalar. The kernel uses pl.load(..., valid_shapes=...)\r\n    + fillpad to handle the unaligned region via pto.set_validshape.\r\n    \"\"\"\r\n    query_rows = batch * num_heads\r\n    key_cache_rows = batch * max_num_blocks_per_req * block_size\r\n    out_rows = batch * num_heads\r\n    block_table_flat_size = batch * max_num_blocks_per_req\r\n\r\n    @pl.program\r\n    class PagedAttentionUnalignedProgram:\r\n        @pl.function(type=pl.FunctionType.Orchestration)\r\n        def paged_attention(\r\n            self,\r\n            query: pl.Tensor[[query_rows, head_dim], pl.BF16],\r\n            key_cache: pl.Tensor[[key_cache_rows, head_dim], pl.BF16],\r\n            value_cache: pl.Tensor[[key_cache_rows, head_dim], pl.BF16],\r\n            block_table: pl.Tensor[[block_table_flat_size], pl.INT32],\r\n            context_lens: pl.Tensor[[batch], pl.INT32],\r\n            out: pl.Out[pl.Tensor[[out_rows, head_dim], pl.FP32]],\r\n            config: pl.Tensor[[7], pl.INT64],\r\n        ) -> pl.Tensor[[out_rows, head_dim], pl.FP32]:\r\n            batch_cfg = pl.tensor.read(config, [0])\r\n            num_heads_cfg = pl.tensor.read(config, [1])\r\n            head_dim_cfg = pl.tensor.read(config, [3])\r\n            block_size_cfg = pl.tensor.read(config, [4])\r\n            block_num_cfg = pl.tensor.read(config, [5])\r\n\r\n            q_head_num = num_heads_cfg\r\n            q_loop_cfg = (q_head_num + q_tile - 1) // q_tile\r\n\r\n            for b_idx in pl.range(batch_cfg):\r\n                cur_seq = pl.tensor.read(context_lens, [b_idx])\r\n                bn_this_batch = (cur_seq + block_size_cfg - 1) // block_size_cfg\r\n                for q_idx in pl.range(q_loop_cfg):\r\n                    cur_offset = b_idx * q_head_num + q_idx * q_tile\r\n\r\n                    oi_buf = pl.create_tensor([q_tile, head_dim_cfg], dtype=pl.FP32)\r\n                    li_buf = pl.create_tensor([q_tile, 1], dtype=pl.FP32)\r\n                    mi_buf = pl.create_tensor([q_tile, 1], dtype=pl.FP32)\r\n                    oi, li_update, mi_update = kernel_init_inplace(oi_buf, li_buf, mi_buf)\r\n\r\n                    for bn in pl.range(bn_this_batch):\r\n                        qi = pl.slice(query, [q_tile, head_dim_cfg], [cur_offset, 0])\r\n                        cur_block_idx = pl.tensor.read(block_table, [b_idx * block_num_cfg + bn])\r\n                        valid_len = pl.min(block_size_cfg, cur_seq - bn * block_size_cfg)\r\n\r\n                        kv_block_row = cur_block_idx * block_size_cfg\r\n                        kj = pl.slice(key_cache, [block_size_cfg, head_dim_cfg], [kv_block_row, 0])\r\n                        vj = pl.slice(value_cache, [block_size_cfg, head_dim_cfg], [kv_block_row, 0])\r\n\r\n                        sij_buf = pl.create_tensor([q_tile, block_size_cfg], dtype=pl.FP32)\r\n                        sij = kernel_qk_matmul(qi, kj, sij_buf)\r\n\r\n                        # Unaligned: pass full sij + valid_len to kernel_softmax_prepare_unaligned\r\n                        # (no pl.slice — kernel handles padding via set_validshape + fillpad)\r\n                        pij_f16_buf = pl.create_tensor([q_tile, block_size_cfg], dtype=pl.BF16)\r\n                        mi_sm_buf = pl.create_tensor([q_tile, 1], dtype=pl.FP32)\r\n                        li_sm_buf = pl.create_tensor([q_tile, 1], dtype=pl.FP32)\r\n                        pij_f16, mi, li = kernel_softmax_prepare_unaligned(\r\n                            sij,\r\n                            1.0,\r\n                            valid_len,\r\n                            pij_f16_buf,\r\n                            mi_sm_buf,\r\n                            li_sm_buf,\r\n                        )\r\n\r\n                        oi_tmp_buf = pl.create_tensor([q_tile, head_dim_cfg], dtype=pl.FP32)\r\n                        oi_tmp = kernel_pv_matmul(pij_f16, vj, oi_tmp_buf)\r\n\r\n                        if bn == 0:\r\n                            is_first = pl.yield_(1)\r\n                        else:\r\n                            is_first = pl.yield_(0)\r\n                        if bn == bn_this_batch - 1:\r\n                            is_last = pl.yield_(1)\r\n                        else:\r\n                            is_last = pl.yield_(0)\r\n\r\n                        out_view_buf = pl.slice(out, [q_tile, head_dim_cfg], [cur_offset, 0])\r\n                        mi_update, li_update, oi, _out_view = kernel_online_update(\r\n                            mi, li, oi_tmp, mi_update, li_update, oi, out_view_buf, is_first, is_last\r\n                        )\r\n\r\n            return out\r\n\r\n    return PagedAttentionUnalignedProgram\r\n\r\n\r\ndef golden(tensors: dict, params: dict | None = None) -> None:\r\n    \"\"\"Reference paged-attention computation (torch), mirroring the kernel pipeline.\r\n\r\n    Implements the online-softmax paged attention matching the 4-kernel pipeline:\r\n    QK matmul → softmax prepare → PV matmul → online update.\r\n\r\n    Args:\r\n        tensors: Dict mapping tensor names to torch tensors.\r\n        params: Unused.\r\n    \"\"\"\r\n    config = tensors[\"config\"]\r\n    batch = int(config[0].item())\r\n    num_heads = int(config[1].item())\r\n    head_dim = int(config[3].item())\r\n    block_size = int(config[4].item())\r\n    max_num_blocks_per_req = int(config[5].item())\r\n    # scale_bits is stored as float32 bits (IEEE 754) in an INT64 slot\r\n    scale_bits = int(config[6].item())\r\n    scale = struct.unpack(\"f\", struct.pack(\"I\", scale_bits & 0xFFFFFFFF))[0]\r\n\r\n    query = tensors[\"query\"].float().reshape(batch, num_heads, head_dim)\r\n    total_pool_blocks = batch * max_num_blocks_per_req\r\n    key_cache = tensors[\"key_cache\"].float().reshape(total_pool_blocks, block_size, head_dim)\r\n    value_cache = tensors[\"value_cache\"].float().reshape(total_pool_blocks, block_size, head_dim)\r\n    block_table = tensors[\"block_table\"].reshape(batch, max_num_blocks_per_req)\r\n    context_lens = tensors[\"context_lens\"]\r\n\r\n    out = torch.zeros((batch, num_heads, head_dim), dtype=torch.float32)\r\n    q_tile = 16\r\n    max_bn = int((context_lens.max().item() + block_size - 1) // block_size)\r\n\r\n    for q_offset in range(0, num_heads, q_tile):\r\n        q_tile_size = min(q_tile, num_heads - q_offset)\r\n        qi = query[:, q_offset : q_offset + q_tile_size, :]  # [batch, q_tile, head_dim]\r\n        oi, li, mi = None, None, None\r\n\r\n        for bn in range(max_bn):\r\n            valid_lens = torch.clamp(context_lens - bn * block_size, min=0, max=block_size)\r\n            if not (valid_lens > 0).any():\r\n                break\r\n            block_indices = block_table[:, bn]  # [batch]\r\n            kj_all = key_cache[block_indices]  # [batch, block_size, head_dim]\r\n            vj_all = value_cache[block_indices]  # [batch, block_size, head_dim]\r\n\r\n            sij = torch.bmm(qi, kj_all.transpose(1, 2)) * scale  # [batch, q_tile, block_size]\r\n            pos = torch.arange(block_size).unsqueeze(0)  # [1, block_size]\r\n            valid_mask = (pos < valid_lens.unsqueeze(1)).unsqueeze(1)  # [batch, 1, block_size]\r\n            sij = sij.masked_fill(~valid_mask, float(\"-inf\"))\r\n            mij = sij.max(dim=-1, keepdim=True)[0].clamp(min=-1e30)  # [batch, q_tile, 1]\r\n            pij = torch.exp(sij - mij).masked_fill(~valid_mask, 0.0)\r\n            pij = pij.to(torch.bfloat16).to(torch.float32)\r\n            lij = pij.sum(dim=-1, keepdim=True)  # [batch, q_tile, 1]\r\n            oi_new = torch.bmm(pij, vj_all)  # [batch, q_tile, head_dim]\r\n\r\n            if bn == 0:\r\n                oi, li, mi = oi_new, lij, mij\r\n            else:\r\n                assert oi is not None and li is not None and mi is not None\r\n                mi_new = torch.maximum(mi, mij)\r\n                alpha = torch.exp(mi - mi_new)\r\n                beta = torch.exp(mij - mi_new)\r\n                li = alpha * li + beta * lij\r\n                oi = alpha * oi + beta * oi_new\r\n                mi = mi_new\r\n\r\n        assert oi is not None and li is not None, \"No KV blocks processed for this query tile\"\r\n        out[:, q_offset : q_offset + q_tile_size, :] = oi / li\r\n\r\n    tensors[\"out\"][:] = out.reshape(batch * num_heads, head_dim)\r\n\r\n\r\ndef build_tensors(\r\n    batch: int,\r\n    num_heads: int,\r\n    head_dim: int,\r\n    block_size: int,\r\n    max_num_blocks_per_req: int,\r\n    context_len: int,\r\n    scale: float = 1.0,\r\n) -> tuple[torch.Tensor, ...]:\r\n    \"\"\"Build torch tensors matching the paged_attention orchestration signature.\r\n\r\n    Returns:\r\n        (query, key_cache, value_cache, block_table, context_lens, out, config)\r\n    \"\"\"\r\n    query_rows = batch * num_heads\r\n    key_cache_rows = batch * max_num_blocks_per_req * block_size\r\n    block_table_flat_size = batch * max_num_blocks_per_req\r\n\r\n    scale_bits = struct.unpack(\"I\", struct.pack(\"f\", scale))[0]\r\n    config = torch.tensor(\r\n        [batch, num_heads, 1, head_dim, block_size, max_num_blocks_per_req, scale_bits],\r\n        dtype=torch.int64,\r\n    )\r\n    context_lens = torch.full((batch,), context_len, dtype=torch.int32)\r\n    block_table = torch.randint(\r\n        0, max(block_table_flat_size, 1), size=(batch, max_num_blocks_per_req), dtype=torch.int32\r\n    ).flatten()\r\n\r\n    query = torch.randn(query_rows, head_dim, dtype=torch.bfloat16)\r\n    key_cache = torch.randn(key_cache_rows, head_dim, dtype=torch.bfloat16)\r\n    value_cache = torch.randn(key_cache_rows, head_dim, dtype=torch.bfloat16)\r\n    out = torch.zeros(query_rows, head_dim, dtype=torch.float32)\r\n\r\n    return query, key_cache, value_cache, block_table, context_lens, out, config\r\n\r\n\r\ndef main():\r\n    parser = argparse.ArgumentParser(description=\"Paged attention example\")\r\n    parser.add_argument(\r\n        \"--enable-l2-swimlane\",\r\n        action=\"store_true\",\r\n        default=False,\r\n        help=\"Enable on-device runtime profiling and generate swimlane JSON\",\r\n    )\r\n    args = parser.parse_args()\r\n\r\n    batch = 64\r\n    num_heads = 16\r\n    head_dim = 128\r\n    block_size = 128\r\n    max_model_len = 32768\r\n    context_len = 8192\r\n    scale = 1.0\r\n    max_num_blocks_per_req = max_model_len // block_size  # 256\r\n\r\n    program = build_paged_attention_program(\r\n        batch=batch,\r\n        num_heads=num_heads,\r\n        head_dim=head_dim,\r\n        block_size=block_size,\r\n        max_num_blocks_per_req=max_num_blocks_per_req,\r\n    )\r\n\r\n    query, key_cache, value_cache, block_table, context_lens, out, config = build_tensors(\r\n        batch=batch,\r\n        num_heads=num_heads,\r\n        head_dim=head_dim,\r\n        block_size=block_size,\r\n        max_num_blocks_per_req=max_num_blocks_per_req,\r\n        context_len=context_len,\r\n        scale=scale,\r\n    )\r\n    run(\r\n        program,\r\n        query,\r\n        key_cache,\r\n        value_cache,\r\n        block_table,\r\n        context_lens,\r\n        out,\r\n        config,\r\n        config=RunConfig(\r\n            platform=\"a2a3\",\r\n            device_id=11,\r\n            strategy=OptimizationStrategy.Default,\r\n            dump_passes=True,\r\n            backend_type=BackendType.Ascend910B,\r\n            enable_l2_swimlane=args.enable_l2_swimlane,\r\n        ),\r\n    )\r\n\r\n    # Golden validation\r\n    expected_out = out.clone()\r\n    golden(\r\n        {\r\n            \"query\": query,\r\n            \"key_cache\": key_cache,\r\n            \"value_cache\": value_cache,\r\n            \"block_table\": block_table,\r\n            \"context_lens\": context_lens,\r\n            \"out\": expected_out,\r\n            \"config\": config,\r\n        },\r\n    )\r\n    assert torch.allclose(out, expected_out, rtol=2e-2, atol=2e-2), (\r\n        f\"Validation failed: max diff = {(out - expected_out).abs().max().item()}\"\r\n    )\r\n    print(\"PASSED\")\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    main()\r\n","examples/models/05_paged_attention_batch.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\"\"\"\r\nBatch Paged Attention Example (16x16 tiles, BF16)\r\n\r\nBuilds a batch paged attention program using the PyPTO DSL with online\r\nsoftmax and a 6-kernel pipeline (AIC/AIV split).  The batch loop is moved\r\ninside kernels so that the orchestration only has q_idx and bn loops,\r\nmatching the C++ implementation in paged_attention_orch.cpp.\r\n\r\nTensor layout (all 2D, flattened):\r\n  query:       [batch * num_heads, head_dim]                    BF16\r\n  key_cache:   [total_pool_blocks * block_size, head_dim]       BF16\r\n  value_cache: [total_pool_blocks * block_size, head_dim]       BF16\r\n  out:         [batch * num_heads, head_dim]                    FP32\r\n\r\nIntermediate batched tensors (contiguous across batch dimension):\r\n  sij_batch:     (batch * q_tile, block_size)  FP32\r\n  pij_batch:     (batch * q_tile, block_size)  BF16\r\n  mij/lij_batch: (batch * q_tile, 1)           FP32\r\n  oi_new_batch:  (batch * q_tile, head_dim)    FP32\r\n  oi_batch:      (batch * q_tile, head_dim)    FP32  accumulator\r\n  mi/li_batch:   (batch * q_tile, 1)           FP32  accumulator\r\n\r\nPipeline per KV block iteration (all batches processed in a single kernel call):\r\n  1. QK Matmul (AIC):        sij            = KernelQkMatmul(query, key_cache, sij, ...)\r\n  2. Softmax Prepare (AIV):  pij, mij, lij  = KernelSoftmaxPrepare(sij, pij, mij, lij, ...)\r\n  3. PV Matmul (AIC):        oi_new         = KernelPvMatmul(pij, value_cache, oi_new, ...)\r\n  4. Online Update (AIV):    mi, li, oi, out = KernelOnlineUpdate(mij, lij, oi_new, mi, li, oi, out, ...)\r\n\r\nKernel mapping to C++ implementations:\r\n  KernelQkMatmul       -> kernels/aic/aic_qk_matmul.cpp   (func_id=0)\r\n  KernelSoftmaxPrepare -> kernels/aiv/aiv_softmax_prepare.cpp (func_id=1)\r\n  KernelPvMatmul       -> kernels/aic/aic_pv_matmul.cpp   (func_id=2)\r\n  KernelOnlineUpdate   -> kernels/aiv/aiv_online_update.cpp (func_id=3)\r\n\"\"\"\r\n\r\nimport os\r\n\r\nimport pypto.language as pl\r\nfrom pypto import ir\r\nfrom pypto.backend import BackendType\r\n\r\n\r\ndef BuildBatchPagedAttentionProgram(\r\n    batch: int,\r\n    num_heads: int,\r\n    head_dim: int = 16,\r\n    block_size: int = 16,\r\n    max_num_blocks_per_req: int = 16,\r\n    q_tile: int = 16,\r\n):\r\n    \"\"\"Build a parameterised batch-paged-attention @pl.program for the given shapes.\r\n\r\n    Returns the decorated program class (not an instance).  The tensor type\r\n    annotations in the orchestration function are filled in from the arguments\r\n    so that the PyPTO DSL can resolve static dimensions at compile time.\r\n\r\n    Parameters\r\n    ----------\r\n    batch:                  number of requests in the batch\r\n    num_heads:              number of query heads\r\n    head_dim:               per-head feature dimension (default 16)\r\n    block_size:             KV-cache block size (default 16)\r\n    max_num_blocks_per_req: maximum number of KV blocks per request\r\n    q_tile:                 query-head tile size used by InCore kernels (default 16)\r\n    \"\"\"\r\n    query_rows = batch * num_heads\r\n    key_cache_rows = batch * max_num_blocks_per_req * block_size\r\n    out_rows = batch * num_heads\r\n    block_table_flat_size = batch * max_num_blocks_per_req\r\n    batch_q_tile = batch * q_tile\r\n\r\n    @pl.program\r\n    class BatchPagedAttentionProgram:\r\n        \"\"\"Batch paged attention with AIC (CUBE) and AIV (VECTOR) kernels.\"\"\"\r\n\r\n        # ── CUBE kernel: QK matmul ──────────────────────────────────────\r\n        # C++ params: query(in), key_cache(in), sij_batch(out),\r\n        #   block_table(tensor), batch_count, block_idx, q_offset,\r\n        #   block_num, num_heads  (9 params)\r\n        @pl.function(type=pl.FunctionType.InCore)\r\n        def KernelQkMatmul(\r\n            self,\r\n            query: pl.Tensor[[query_rows, head_dim], pl.BF16],\r\n            key_cache: pl.Tensor[[key_cache_rows, head_dim], pl.BF16],\r\n            sij_batch: pl.Out[pl.Tensor[[batch_q_tile, block_size], pl.FP32]],\r\n            block_table: pl.Tensor[[block_table_flat_size], pl.INT32],\r\n            batch_count: pl.Scalar[pl.INT64],\r\n            block_idx: pl.Scalar[pl.INT64],\r\n            q_offset: pl.Scalar[pl.INT64],\r\n            block_num: pl.Scalar[pl.INT64],\r\n            num_heads_param: pl.Scalar[pl.INT64],\r\n        ) -> pl.Tensor[[batch_q_tile, block_size], pl.FP32]:\r\n            \"\"\"QK matmul: sij = qi @ kj.T (CUBE, func_id=0).\r\n\r\n            Loops over batch internally, computing per-batch qi and kj\r\n            addresses from block_table lookup and q_offset.\r\n            \"\"\"\r\n            for b in pl.range(batch_count):\r\n                qi_row = b * num_heads_param + q_offset\r\n                phys_block = pl.read(block_table, b * block_num + block_idx)\r\n                kj_row = phys_block * block_size\r\n\r\n                qi_l1 = pl.load(\r\n                    query,\r\n                    [qi_row, 0],\r\n                    [q_tile, head_dim],\r\n                    target_memory=pl.MemorySpace.Mat,\r\n                )\r\n                kj_l1 = pl.load(\r\n                    key_cache,\r\n                    [kj_row, 0],\r\n                    [block_size, head_dim],\r\n                    target_memory=pl.MemorySpace.Mat,\r\n                )\r\n                qi_l0a = pl.move(qi_l1, target_memory=pl.MemorySpace.Left)\r\n                kj_l0b = pl.move(kj_l1, target_memory=pl.MemorySpace.Right, transpose=True)\r\n                sij_l0c = pl.matmul(qi_l0a, kj_l0b)\r\n                sij_batch_new = pl.store(sij_l0c, [b * q_tile, 0], sij_batch)\r\n            return sij_batch_new\r\n\r\n        # ── VECTOR kernel: softmax prepare ──────────────────────────────\r\n        # C++ params: sij_batch(in), pij_batch(out), mij_batch(out),\r\n        #   lij_batch(out), scale_value, context_lens(tensor),\r\n        #   batch_count, block_idx  (8 params)\r\n        @pl.function(type=pl.FunctionType.InCore)\r\n        def KernelSoftmaxPrepare(\r\n            self,\r\n            sij_batch: pl.Tensor[[batch_q_tile, block_size], pl.FP32],\r\n            pij_batch: pl.Out[pl.Tensor[[batch_q_tile, block_size], pl.BF16]],\r\n            mij_batch: pl.Out[pl.Tensor[[batch_q_tile, 1], pl.FP32]],\r\n            lij_batch: pl.Out[pl.Tensor[[batch_q_tile, 1], pl.FP32]],\r\n            scale_value: pl.Scalar[pl.FP32],\r\n            context_lens: pl.Tensor[[batch], pl.INT32],\r\n            batch_count: pl.Scalar[pl.INT64],\r\n            block_idx: pl.Scalar[pl.INT64],\r\n        ) -> tuple[\r\n            pl.Tensor[[batch_q_tile, block_size], pl.BF16],\r\n            pl.Tensor[[batch_q_tile, 1], pl.FP32],\r\n            pl.Tensor[[batch_q_tile, 1], pl.FP32],\r\n        ]:\r\n            \"\"\"Softmax prepare: scale, row_max, exp, row_sum (VECTOR, func_id=1).\r\n\r\n            Loops over batch internally, masking invalid positions with -inf\r\n            using context_lens and block_idx to compute per-batch valid_len.\r\n            \"\"\"\r\n            for b in pl.range(batch_count):\r\n                cur_seq = pl.tensor.read(context_lens, [b])\r\n                start = block_idx * block_size\r\n                remaining = cur_seq - start\r\n                valid_len = pl.max(pl.min(remaining, block_size), 0)\r\n\r\n                s_tile = pl.load(\r\n                    sij_batch,\r\n                    [b * q_tile, 0],\r\n                    [q_tile, block_size],\r\n                    target_memory=pl.MemorySpace.Vec,\r\n                    valid_shapes=[q_tile, valid_len],\r\n                )\r\n\r\n                s_padded = pl.tile.fillpad(s_tile, pad_value=pl.PadValue.min)\r\n\r\n                scaled = pl.mul(s_padded, scale_value)\r\n                tmp_tile = pl.create_tile(\r\n                    [q_tile, block_size],\r\n                    dtype=pl.FP32,\r\n                    target_memory=pl.MemorySpace.Vec,\r\n                )\r\n                mi_tile = pl.row_max(scaled, tmp_tile)\r\n                sij_centered = pl.row_expand_sub(scaled, mi_tile)\r\n                exp_tile = pl.exp(sij_centered)\r\n                pij_tile_f16 = pl.cast(exp_tile, target_type=pl.BF16)\r\n                pij_tile = pl.cast(pij_tile_f16, target_type=pl.FP32)\r\n                li_tile = pl.row_sum(pij_tile, tmp_tile)\r\n\r\n                pij_batch = pl.store(pij_tile_f16, [b * q_tile, 0], pij_batch, [q_tile, block_size])\r\n                mij_batch = pl.store(mi_tile, [b * q_tile, 0], mij_batch, [q_tile, 1])\r\n                lij_batch = pl.store(li_tile, [b * q_tile, 0], lij_batch, [q_tile, 1])\r\n            return pij_batch, mij_batch, lij_batch\r\n\r\n        # ── CUBE kernel: PV matmul ──────────────────────────────────────\r\n        # C++ params: pij_batch(in), value_cache(in), oi_new_batch(out),\r\n        #   block_table(tensor), batch_count, block_idx, block_num  (7 params)\r\n        @pl.function(type=pl.FunctionType.InCore)\r\n        def KernelPvMatmul(\r\n            self,\r\n            pij_batch: pl.Tensor[[batch_q_tile, block_size], pl.BF16],\r\n            value_cache: pl.Tensor[[key_cache_rows, head_dim], pl.BF16],\r\n            oi_new_batch: pl.Out[pl.Tensor[[batch_q_tile, head_dim], pl.FP32]],\r\n            block_table: pl.Tensor[[block_table_flat_size], pl.INT32],\r\n            batch_count: pl.Scalar[pl.INT64],\r\n            block_idx: pl.Scalar[pl.INT64],\r\n            block_num: pl.Scalar[pl.INT64],\r\n        ) -> pl.Tensor[[batch_q_tile, head_dim], pl.FP32]:\r\n            \"\"\"PV matmul: oi_tmp = pij @ vj (CUBE, func_id=2).\r\n\r\n            Loops over batch internally, computing per-batch pij offset\r\n            and vj address from block_table lookup.\r\n            \"\"\"\r\n            for b in pl.range(batch_count):\r\n                phys_block = pl.read(block_table, b * block_num + block_idx)\r\n                vj_row = phys_block * block_size\r\n\r\n                pij_l1 = pl.load(\r\n                    pij_batch,\r\n                    [b * q_tile, 0],\r\n                    [q_tile, block_size],\r\n                    target_memory=pl.MemorySpace.Mat,\r\n                )\r\n                vj_l1 = pl.load(\r\n                    value_cache,\r\n                    [vj_row, 0],\r\n                    [block_size, head_dim],\r\n                    target_memory=pl.MemorySpace.Mat,\r\n                )\r\n                pij_l0a = pl.move(pij_l1, target_memory=pl.MemorySpace.Left)\r\n                vj_l0b = pl.move(vj_l1, target_memory=pl.MemorySpace.Right)\r\n                oi_l0c = pl.matmul(pij_l0a, vj_l0b)\r\n                oi_new_batch = pl.store(oi_l0c, [b * q_tile, 0], oi_new_batch)\r\n            return oi_new_batch\r\n\r\n        # ── VECTOR kernel: online update (inplace) ──────────────────────\r\n        # C++ params: mij_batch(in), lij_batch(in), oi_new_batch(in),\r\n        #   mi_batch(inout), li_batch(inout), oi_batch(out), out(out),\r\n        #   is_first, is_last, batch_count, q_offset, num_heads  (12 params)\r\n        @pl.function(type=pl.FunctionType.InCore)\r\n        def KernelOnlineUpdate(  # noqa: PLR0913\r\n            self,\r\n            mij_batch: pl.Tensor[[batch_q_tile, 1], pl.FP32],\r\n            lij_batch: pl.Tensor[[batch_q_tile, 1], pl.FP32],\r\n            oi_new_batch: pl.Tensor[[batch_q_tile, head_dim], pl.FP32],\r\n            mi_batch: pl.InOut[pl.Tensor[[batch_q_tile, 1], pl.FP32]],\r\n            li_batch: pl.InOut[pl.Tensor[[batch_q_tile, 1], pl.FP32]],\r\n            oi_batch: pl.InOut[pl.Tensor[[batch_q_tile, head_dim], pl.FP32]],\r\n            out_tensor: pl.Out[pl.Tensor[[out_rows, head_dim], pl.FP32]],\r\n            is_first: pl.Scalar[pl.INT64],\r\n            is_last: pl.Scalar[pl.INT64],\r\n            batch_count: pl.Scalar[pl.INT64],\r\n            q_offset: pl.Scalar[pl.INT64],\r\n            num_heads_param: pl.Scalar[pl.INT64],\r\n        ) -> tuple[\r\n            pl.Tensor[[batch_q_tile, 1], pl.FP32],\r\n            pl.Tensor[[batch_q_tile, 1], pl.FP32],\r\n            pl.Tensor[[batch_q_tile, head_dim], pl.FP32],\r\n            pl.Tensor[[out_rows, head_dim], pl.FP32],\r\n        ]:\r\n            \"\"\"Online softmax update with inplace mi/li/oi (VECTOR, func_id=3).\r\n\r\n            Loops over batch internally, updating accumulators per batch and\r\n            writing normalised output to out_tensor at the correct batch offset\r\n            on the last KV-block iteration.\r\n            \"\"\"\r\n            for b in pl.range(batch_count):\r\n                dst_row = b * num_heads_param + q_offset\r\n\r\n                if is_first:\r\n                    mij_tile = pl.load(\r\n                        mij_batch,\r\n                        [b * q_tile, 0],\r\n                        [q_tile, 1],\r\n                        target_memory=pl.MemorySpace.Vec,\r\n                    )\r\n                    lij_tile = pl.load(\r\n                        lij_batch,\r\n                        [b * q_tile, 0],\r\n                        [q_tile, 1],\r\n                        target_memory=pl.MemorySpace.Vec,\r\n                    )\r\n                    oi_new_tile = pl.load(\r\n                        oi_new_batch,\r\n                        [b * q_tile, 0],\r\n                        [q_tile, head_dim],\r\n                        target_memory=pl.MemorySpace.Vec,\r\n                    )\r\n\r\n                    mi_batch = pl.store(mij_tile, [b * q_tile, 0], mi_batch, [q_tile, 1])\r\n                    li_batch = pl.store(lij_tile, [b * q_tile, 0], li_batch, [q_tile, 1])\r\n                    oi_batch = pl.store(oi_new_tile, [b * q_tile, 0], oi_batch, [q_tile, head_dim])\r\n\r\n                    if is_last:\r\n                        dst_tile = pl.row_expand_div(oi_new_tile, lij_tile)\r\n                        out_tensor = pl.store(dst_tile, [dst_row, 0], out_tensor, [q_tile, head_dim])\r\n                else:\r\n                    mij_tile = pl.load(\r\n                        mij_batch,\r\n                        [b * q_tile, 0],\r\n                        [q_tile, 1],\r\n                        target_memory=pl.MemorySpace.Vec,\r\n                    )\r\n                    lij_tile = pl.load(\r\n                        lij_batch,\r\n                        [b * q_tile, 0],\r\n                        [q_tile, 1],\r\n                        target_memory=pl.MemorySpace.Vec,\r\n                    )\r\n                    oi_new_tile = pl.load(\r\n                        oi_new_batch,\r\n                        [b * q_tile, 0],\r\n                        [q_tile, head_dim],\r\n                        target_memory=pl.MemorySpace.Vec,\r\n                    )\r\n                    mi_tile = pl.load(\r\n                        mi_batch,\r\n                        [b * q_tile, 0],\r\n                        [q_tile, 1],\r\n                        target_memory=pl.MemorySpace.Vec,\r\n                    )\r\n                    li_tile = pl.load(\r\n                        li_batch,\r\n                        [b * q_tile, 0],\r\n                        [q_tile, 1],\r\n                        target_memory=pl.MemorySpace.Vec,\r\n                    )\r\n                    oi_tile = pl.load(\r\n                        oi_batch,\r\n                        [b * q_tile, 0],\r\n                        [q_tile, head_dim],\r\n                        target_memory=pl.MemorySpace.Vec,\r\n                    )\r\n\r\n                    # Reshape DN [q_tile,1] -> ND [1,q_tile] for element-wise ops\r\n                    mi_tile_nd = pl.reshape(mi_tile, [1, q_tile])\r\n                    mij_tile_nd = pl.reshape(mij_tile, [1, q_tile])\r\n                    li_tile_nd = pl.reshape(li_tile, [1, q_tile])\r\n                    lij_tile_nd = pl.reshape(lij_tile, [1, q_tile])\r\n\r\n                    mi_new = pl.maximum(mi_tile_nd, mij_tile_nd)\r\n                    alpha = pl.exp(pl.sub(mi_tile_nd, mi_new))\r\n                    beta = pl.exp(pl.sub(mij_tile_nd, mi_new))\r\n                    li_updated = pl.add(pl.mul(alpha, li_tile_nd), pl.mul(beta, lij_tile_nd))\r\n\r\n                    # Reshape back to DN [q_tile,1] for store and row_expand ops\r\n                    mi_new_dn = pl.reshape(mi_new, [q_tile, 1])\r\n                    li_updated_dn = pl.reshape(li_updated, [q_tile, 1])\r\n\r\n                    mi_batch = pl.store(mi_new_dn, [b * q_tile, 0], mi_batch, [q_tile, 1])\r\n                    li_batch = pl.store(li_updated_dn, [b * q_tile, 0], li_batch, [q_tile, 1])\r\n\r\n                    # Reshape ND [1,q_tile] -> DN [q_tile,1] for row_expand_mul\r\n                    alpha_dn = pl.reshape(alpha, [q_tile, 1])\r\n                    beta_dn = pl.reshape(beta, [q_tile, 1])\r\n                    oi_scaled = pl.row_expand_mul(oi_tile, alpha_dn)\r\n                    oi_new_scaled = pl.row_expand_mul(oi_new_tile, beta_dn)\r\n                    oi_updated = pl.add(oi_scaled, oi_new_scaled)\r\n\r\n                    if is_last:\r\n                        dst_tile = pl.row_expand_div(oi_updated, li_updated_dn)\r\n                        out_tensor = pl.store(dst_tile, [dst_row, 0], out_tensor, [q_tile, head_dim])\r\n                    else:\r\n                        oi_batch = pl.store(\r\n                            oi_updated,\r\n                            [b * q_tile, 0],\r\n                            oi_batch,\r\n                            [q_tile, head_dim],\r\n                        )\r\n\r\n            return mi_batch, li_batch, oi_batch, out_tensor\r\n\r\n        # ── Orchestration function ──────────────────────────────────────\r\n        # Mirrors aicpu_orchestration_entry() in paged_attention_orch.cpp:\r\n        #   - No batch loop (batch dimension is inside kernels)\r\n        #   - Loops: for q_idx -> for bn\r\n        #   - Intermediate tensors are batch-sized (batch * q_tile)\r\n        #   - Kernels receive full global tensors + scalar metadata\r\n        @pl.function(type=pl.FunctionType.Orchestration)\r\n        def BatchPagedAttention(\r\n            self,\r\n            query: pl.Tensor[[query_rows, head_dim], pl.BF16],\r\n            key_cache: pl.Tensor[[key_cache_rows, head_dim], pl.BF16],\r\n            value_cache: pl.Tensor[[key_cache_rows, head_dim], pl.BF16],\r\n            block_table: pl.Tensor[[block_table_flat_size], pl.INT32],\r\n            context_lens: pl.Tensor[[batch], pl.INT32],\r\n            out: pl.Out[pl.Tensor[[out_rows, head_dim], pl.FP32]],\r\n            config: pl.Tensor[[7], pl.INT64],\r\n            size_query: pl.Tensor[[1], pl.INT64],\r\n            size_key_cache: pl.Tensor[[1], pl.INT64],\r\n            size_value_cache: pl.Tensor[[1], pl.INT64],\r\n        ) -> pl.Tensor[[out_rows, head_dim], pl.FP32]:\r\n            \"\"\"Batch paged attention orchestration.\r\n\r\n            Strictly follows aicpu_orchestration_entry() logic:\r\n            no batch loop, q_idx outer loop, bn inner loop.\r\n            Config layout: [batch, num_heads, kv_head_num, head_dim,\r\n                            block_size, block_num, scale_bits]\r\n            \"\"\"\r\n            batch_cfg = pl.tensor.read(config, [0])\r\n            num_heads_cfg = pl.tensor.read(config, [1])\r\n            head_dim_cfg = pl.tensor.read(config, [3])\r\n            block_size_cfg = pl.tensor.read(config, [4])\r\n            block_num_cfg = pl.tensor.read(config, [5])\r\n\r\n            q_loop_cfg = (num_heads_cfg + q_tile - 1) // q_tile\r\n\r\n            # Compute max_bn across all batches (mirrors C++ max_bn loop)\r\n            max_bn = pl.yield_(0)\r\n            for b in pl.range(batch_cfg):\r\n                cur_seq_b = pl.tensor.read(context_lens, [b])\r\n                bn_b = (cur_seq_b + block_size_cfg - 1) // block_size_cfg\r\n                max_bn = pl.max(max_bn, bn_b)  # type: ignore[reportArgumentType]\r\n\r\n            for q_idx in pl.range(q_loop_cfg):\r\n                q_offset = q_idx * q_tile\r\n\r\n                # Batch-sized accumulators (mirrors C++ oi_batch/li_batch/mi_batch)\r\n                oi_batch = pl.create_tensor([batch_cfg * q_tile, head_dim_cfg], dtype=pl.FP32)\r\n                li_batch = pl.create_tensor([batch_cfg * q_tile, 1], dtype=pl.FP32)\r\n                mi_batch = pl.create_tensor([batch_cfg * q_tile, 1], dtype=pl.FP32)\r\n\r\n                for bn in pl.range(max_bn):\r\n                    # Batch-sized intermediate tensors (mirrors C++ sij_b/pij_b/etc.)\r\n                    sij_b = pl.create_tensor([batch_cfg * q_tile, block_size_cfg], dtype=pl.FP32)\r\n                    pij_b = pl.create_tensor([batch_cfg * q_tile, block_size_cfg], dtype=pl.FP16)\r\n                    mij_b = pl.create_tensor([batch_cfg * q_tile, 1], dtype=pl.FP32)\r\n                    lij_b = pl.create_tensor([batch_cfg * q_tile, 1], dtype=pl.FP32)\r\n                    oi_new_b = pl.create_tensor([batch_cfg * q_tile, head_dim_cfg], dtype=pl.FP32)\r\n\r\n                    # Stage 1: QK matmul (FUNC_QK_MATMUL, AIC / CUBE)\r\n                    sij_b = self.KernelQkMatmul(\r\n                        query,\r\n                        key_cache,\r\n                        sij_b,\r\n                        block_table,\r\n                        batch_cfg,\r\n                        bn,\r\n                        q_offset,\r\n                        block_num_cfg,\r\n                        num_heads_cfg,\r\n                    )\r\n\r\n                    # Stage 2: Softmax prepare (FUNC_SOFTMAX_PREPARE, AIV / VECTOR)\r\n                    pij_b, mij_b, lij_b = self.KernelSoftmaxPrepare(\r\n                        sij_b,\r\n                        pij_b,\r\n                        mij_b,\r\n                        lij_b,\r\n                        1.0,\r\n                        context_lens,\r\n                        batch_cfg,\r\n                        bn,\r\n                    )\r\n\r\n                    # Stage 3: PV matmul (FUNC_PV_MATMUL, AIC / CUBE)\r\n                    oi_new_b = self.KernelPvMatmul(\r\n                        pij_b,\r\n                        value_cache,\r\n                        oi_new_b,\r\n                        block_table,\r\n                        batch_cfg,\r\n                        bn,\r\n                        block_num_cfg,\r\n                    )\r\n\r\n                    # Conditional flags (mirrors C++ is_first/is_last)\r\n                    if bn == 0:\r\n                        is_first = pl.yield_(1)\r\n                    else:\r\n                        is_first = pl.yield_(0)\r\n                    if bn == max_bn - 1:\r\n                        is_last = pl.yield_(1)\r\n                    else:\r\n                        is_last = pl.yield_(0)\r\n\r\n                    # Stage 4: Online update (FUNC_ONLINE_UPDATE, AIV / VECTOR)\r\n                    mi_batch, li_batch, oi_batch, out = self.KernelOnlineUpdate(\r\n                        mij_b,\r\n                        lij_b,\r\n                        oi_new_b,\r\n                        mi_batch,\r\n                        li_batch,\r\n                        oi_batch,\r\n                        out,\r\n                        is_first,\r\n                        is_last,\r\n                        batch_cfg,\r\n                        q_offset,\r\n                        num_heads_cfg,\r\n                    )\r\n\r\n            return out\r\n\r\n    return BatchPagedAttentionProgram\r\n\r\n\r\ndef main():\r\n    \"\"\"Build IR, compile, and display generated orchestration C++ code.\"\"\"\r\n    print(\"=\" * 70)\r\n    print(\"Batch Paged Attention Orchestration Code Generation (16x16)\")\r\n    print(\"=\" * 70)\r\n\r\n    program = BuildBatchPagedAttentionProgram(\r\n        batch=1,\r\n        num_heads=16,\r\n        head_dim=16,\r\n        block_size=16,\r\n        max_num_blocks_per_req=16,\r\n    )\r\n    print(f\"\\nProgram: {program.name}\")\r\n    print(f\"Functions: {[f.name for f in program.functions.values()]}\")\r\n\r\n    print(\"\\n[1] IR Preview:\")\r\n    print(\"-\" * 70)\r\n    ir_text = program.as_python()\r\n    lines = ir_text.split(\"\\n\")\r\n    preview = min(60, len(lines))\r\n    print(\"\\n\".join(lines[:preview]))\r\n    if len(lines) > preview:\r\n        print(f\"\\n... ({len(lines) - preview} more lines)\")\r\n    print(\"-\" * 70)\r\n\r\n    print(\"\\n[2] Compiling...\")\r\n    output_dir = ir.compile(\r\n        program,\r\n        strategy=ir.OptimizationStrategy.Default,\r\n        dump_passes=True,\r\n        backend_type=BackendType.Ascend910B,\r\n    )\r\n    print(f\"Output: {output_dir}\")\r\n\r\n    print(\"\\n[3] Generated files:\")\r\n    for root, _dirs, files in os.walk(output_dir):\r\n        for f in files:\r\n            path = os.path.join(root, f)\r\n            rel = os.path.relpath(path, output_dir)\r\n            print(f\"  - {rel} ({os.path.getsize(path)} bytes)\")\r\n\r\n    orch_file = os.path.join(output_dir, \"orchestration\", \"batch_paged_attention.cpp\")\r\n    if os.path.exists(orch_file):\r\n        print(\"\\n[4] Generated Orchestration C++ path:\")\r\n        print(orch_file)\r\n\r\n    print(\"\\nDone.\")\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    main()\r\n","examples/models/06_paged_attention_dynamic.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\"\"\"\r\nDynamic Paged Attention Example\r\n\r\nInCore kernel type annotations use pl.dynamic() variables (Q_HEADS, HEAD_DIM_DYN,\r\nBLOCK_SIZE_DYN), while load operations use closure variables (_Q_TILE, _HEAD_DIM,\r\n_BLOCK_SIZE) captured from build_dynamic_paged_attention_program().\r\nOrchestration-level tensor shapes also use pl.dynamic() variables so the program\r\naccepts any batch size at runtime.\r\n\"\"\"\r\n\r\n# DSL function bodies are parsed as AST — dynamic var names look undefined to pyright.\r\n# pyright: reportUndefinedVariable=false\r\n\r\nimport argparse\r\n\r\nimport pypto.language as pl\r\nimport torch\r\nfrom pypto.backend import BackendType\r\nfrom pypto.ir.pass_manager import OptimizationStrategy\r\nfrom pypto.runtime import RunConfig, run\r\n\r\n# ---------------------------------------------------------------------------\r\n# Module-level dynamic variables — used only in InCore kernel type annotations.\r\n# Load operations inside the kernels use closure variables from the builder instead.\r\n# ---------------------------------------------------------------------------\r\n\r\nQ_HEADS = pl.dynamic(\"Q_HEADS\")  # query tile rows   (e.g. 16)\r\nHEAD_DIM_DYN = pl.dynamic(\"HEAD_DIM_DYN\")  # head dimension    (e.g. 128)\r\nBLOCK_SIZE_DYN = pl.dynamic(\"BLOCK_SIZE_DYN\")  # KV block size     (e.g. 128)\r\nBATCH_DYN = pl.dynamic(\"BATCH_DYN\")  # batch size (number of requests)\r\nQUERY_ROWS_DYN = pl.dynamic(\"QUERY_ROWS_DYN\")  # batch * num_heads\r\nKEY_CACHE_ROWS_DYN = pl.dynamic(\"KEY_CACHE_ROWS_DYN\")  # batch * max_num_blocks_per_req * block_size\r\nBLOCK_TABLE_FLAT_DYN = pl.dynamic(\"BLOCK_TABLE_FLAT_DYN\")  # batch * max_num_blocks_per_req\r\n\r\n\r\n# ---------------------------------------------------------------------------\r\n# Program builders\r\n# ---------------------------------------------------------------------------\r\n\r\n\r\ndef build_dynamic_paged_attention_program(\r\n    q_tile: int,\r\n    head_dim: int,\r\n    block_size: int,\r\n):\r\n    \"\"\"Build a paged-attention @pl.program whose InCore kernels use dynamic shapes.\r\n\r\n    InCore kernel type annotations reference module-level pl.dynamic() variables so\r\n    shapes are resolved at runtime.  Load operations use closure variables captured\r\n    from the builder parameters (_Q_TILE, _HEAD_DIM, _BLOCK_SIZE).\r\n\r\n    Parameters\r\n    ----------\r\n    q_tile:     query-head tile size (number of query heads processed per InCore call)\r\n    head_dim:   per-head feature dimension\r\n    block_size: KV-cache block size (rows per physical block)\r\n    \"\"\"\r\n    # Tile-size constants captured as closures by the InCore kernels below.\r\n    _Q_TILE: int = q_tile\r\n    _HEAD_DIM: int = head_dim\r\n    _BLOCK_SIZE: int = block_size\r\n\r\n    # -----------------------------------------------------------------------\r\n    # InCore kernels — defined here to capture _Q_TILE, _HEAD_DIM, _BLOCK_SIZE\r\n    # as closure variables; type annotations use module-level pl.dynamic() vars.\r\n    # -----------------------------------------------------------------------\r\n\r\n    @pl.function(type=pl.FunctionType.InCore)\r\n    def dyn_kernel_init_inplace(\r\n        oi: pl.Out[pl.Tensor[[Q_HEADS, HEAD_DIM_DYN], pl.FP32]],\r\n        li: pl.Out[pl.Tensor[[Q_HEADS, 1], pl.FP32]],\r\n        mi: pl.Out[pl.Tensor[[Q_HEADS, 1], pl.FP32]],\r\n    ) -> tuple[\r\n        pl.Tensor[[Q_HEADS, HEAD_DIM_DYN], pl.FP32],\r\n        pl.Tensor[[Q_HEADS, 1], pl.FP32],\r\n        pl.Tensor[[Q_HEADS, 1], pl.FP32],\r\n    ]:\r\n        \"\"\"No-op passthrough: binds concrete tensor shapes to dynamic type annotations.\r\n\r\n        pl.create_tensor zero-initialises the buffers before this call; this\r\n        function exists solely to propagate the dynamic shape at the call site.\r\n        \"\"\"\r\n        return oi, li, mi\r\n\r\n    @pl.function(type=pl.FunctionType.InCore)\r\n    def dyn_kernel_qk_matmul(\r\n        qi: pl.Tensor[[Q_HEADS, HEAD_DIM_DYN], pl.BF16],\r\n        kj: pl.Tensor[[BLOCK_SIZE_DYN, HEAD_DIM_DYN], pl.BF16],\r\n        output: pl.Out[pl.Tensor[[Q_HEADS, BLOCK_SIZE_DYN], pl.FP32]],\r\n    ) -> pl.Tensor[[Q_HEADS, BLOCK_SIZE_DYN], pl.FP32]:\r\n        \"\"\"QK matmul: output = qi @ kj.T (CUBE). kj reinterpreted as its transpose.\"\"\"\r\n        qi_l1 = pl.load(qi, [0, 0], [_Q_TILE, _HEAD_DIM], target_memory=pl.MemorySpace.Mat)\r\n        kj_nat = pl.load(kj, [0, 0], [_BLOCK_SIZE, _HEAD_DIM], target_memory=pl.MemorySpace.Mat)\r\n        kj_l1 = pl.tile.transpose_view(kj_nat)\r\n        qi_l0a = pl.move(qi_l1, target_memory=pl.MemorySpace.Left)\r\n        kj_l0b = pl.move(kj_l1, target_memory=pl.MemorySpace.Right)\r\n        sij_l0c = pl.matmul(qi_l0a, kj_l0b)\r\n        out = pl.store(sij_l0c, [0, 0], output)\r\n        return out\r\n\r\n    @pl.function(type=pl.FunctionType.InCore)\r\n    def dyn_kernel_softmax_prepare(\r\n        sij: pl.Tensor[[Q_HEADS, BLOCK_SIZE_DYN], pl.FP32],\r\n        scale: pl.Scalar[pl.FP32],\r\n        out_pij: pl.Out[pl.Tensor[[Q_HEADS, BLOCK_SIZE_DYN], pl.BF16]],\r\n        out_mi: pl.Out[pl.Tensor[[Q_HEADS, 1], pl.FP32]],\r\n        out_li: pl.Out[pl.Tensor[[Q_HEADS, 1], pl.FP32]],\r\n    ) -> tuple[\r\n        pl.Tensor[[Q_HEADS, BLOCK_SIZE_DYN], pl.BF16],\r\n        pl.Tensor[[Q_HEADS, 1], pl.FP32],\r\n        pl.Tensor[[Q_HEADS, 1], pl.FP32],\r\n    ]:\r\n        \"\"\"Scale sij, compute row_max (mi), exp(sij-mi), cast to BF16, row_sum (li). VECTOR.\"\"\"\r\n        s_tile = pl.load(sij, [0, 0], [_Q_TILE, _BLOCK_SIZE], target_memory=pl.MemorySpace.Vec)\r\n        scaled = pl.mul(s_tile, scale)\r\n        tmp_tile = pl.create_tile([_Q_TILE, _BLOCK_SIZE], dtype=pl.FP32, target_memory=pl.MemorySpace.Vec)\r\n        mi_tile = pl.row_max(scaled, tmp_tile)\r\n        sij_centered = pl.row_expand_sub(scaled, mi_tile)\r\n        exp_tile = pl.exp(sij_centered)\r\n        pij_tile_bf16 = pl.cast(exp_tile, target_type=pl.BF16)\r\n        pij_tile = pl.cast(pij_tile_bf16, target_type=pl.FP32)\r\n        li_tile = pl.row_sum(pij_tile, tmp_tile)\r\n        out_pij = pl.store(pij_tile_bf16, [0, 0], out_pij)\r\n        out_mi = pl.store(mi_tile, [0, 0], out_mi)\r\n        out_li = pl.store(li_tile, [0, 0], out_li)\r\n        return out_pij, out_mi, out_li\r\n\r\n    @pl.function(type=pl.FunctionType.InCore)\r\n    def dyn_kernel_pv_matmul(\r\n        pij: pl.Tensor[[Q_HEADS, BLOCK_SIZE_DYN], pl.BF16],\r\n        vj: pl.Tensor[[BLOCK_SIZE_DYN, HEAD_DIM_DYN], pl.BF16],\r\n        output: pl.Out[pl.Tensor[[Q_HEADS, HEAD_DIM_DYN], pl.FP32]],\r\n    ) -> pl.Tensor[[Q_HEADS, HEAD_DIM_DYN], pl.FP32]:\r\n        \"\"\"PV matmul: output = pij @ vj (CUBE).\"\"\"\r\n        pij_l1 = pl.load(pij, [0, 0], [_Q_TILE, _BLOCK_SIZE], target_memory=pl.MemorySpace.Mat)\r\n        vj_l1 = pl.load(vj, [0, 0], [_BLOCK_SIZE, _HEAD_DIM], target_memory=pl.MemorySpace.Mat)\r\n        pij_l0a = pl.move(pij_l1, target_memory=pl.MemorySpace.Left)\r\n        vj_l0b = pl.move(vj_l1, target_memory=pl.MemorySpace.Right)\r\n        oi_l0c = pl.matmul(pij_l0a, vj_l0b)\r\n        out = pl.store(oi_l0c, [0, 0], output)\r\n        return out\r\n\r\n    @pl.function(type=pl.FunctionType.InCore)\r\n    def dyn_kernel_online_update(\r\n        mij: pl.Tensor[[Q_HEADS, 1], pl.FP32],\r\n        lij: pl.Tensor[[Q_HEADS, 1], pl.FP32],\r\n        oi_new: pl.Tensor[[Q_HEADS, HEAD_DIM_DYN], pl.FP32],\r\n        mi: pl.InOut[pl.Tensor[[Q_HEADS, 1], pl.FP32]],\r\n        li: pl.InOut[pl.Tensor[[Q_HEADS, 1], pl.FP32]],\r\n        oi: pl.InOut[pl.Tensor[[Q_HEADS, HEAD_DIM_DYN], pl.FP32]],\r\n        dst: pl.Out[pl.Tensor[[Q_HEADS, HEAD_DIM_DYN], pl.FP32]],\r\n        is_first: pl.Scalar[pl.BOOL],\r\n        is_last: pl.Scalar[pl.BOOL],\r\n    ) -> tuple[\r\n        pl.Tensor[[Q_HEADS, 1], pl.FP32],\r\n        pl.Tensor[[Q_HEADS, 1], pl.FP32],\r\n        pl.Tensor[[Q_HEADS, HEAD_DIM_DYN], pl.FP32],\r\n        pl.Tensor[[Q_HEADS, HEAD_DIM_DYN], pl.FP32],\r\n    ]:\r\n        \"\"\"Merge current block's (mij, lij, oi_new) into running accumulators (mi, li, oi). VECTOR.\r\n\r\n        First block (is_first=True): directly assign accumulators, no rescaling.\r\n        Subsequent blocks: mi_new=max(mi,mij), alpha=exp(mi-mi_new), beta=exp(mij-mi_new),\r\n          li <- alpha*li + beta*lij,  oi <- alpha*oi + beta*oi_new.\r\n        Last block (is_last=True): write oi/li to dst; otherwise dst=zeros.\r\n\r\n        Reshape between [Q_TILE,1] and [1,Q_TILE] is required because row_expand_mul\r\n        broadcasts along the column axis while element-wise ops need consistent layout.\r\n        \"\"\"\r\n        mij_tile = pl.load(mij, [0, 0], [_Q_TILE, 1], target_memory=pl.MemorySpace.Vec)\r\n        lij_tile = pl.load(lij, [0, 0], [_Q_TILE, 1], target_memory=pl.MemorySpace.Vec)\r\n        oi_new_tile = pl.load(oi_new, [0, 0], [_Q_TILE, _HEAD_DIM], target_memory=pl.MemorySpace.Vec)\r\n        mi_tile = pl.load(mi, [0, 0], [_Q_TILE, 1], target_memory=pl.MemorySpace.Vec)\r\n        li_tile = pl.load(li, [0, 0], [_Q_TILE, 1], target_memory=pl.MemorySpace.Vec)\r\n        oi_tile = pl.load(oi, [0, 0], [_Q_TILE, _HEAD_DIM], target_memory=pl.MemorySpace.Vec)\r\n\r\n        if is_first:\r\n            mi_out = pl.store(mij_tile, [0, 0], mi)\r\n            li_out = pl.store(lij_tile, [0, 0], li)\r\n            oi_out = pl.store(oi_new_tile, [0, 0], oi)\r\n            if is_last:\r\n                dst_tile = pl.row_expand_div(oi_new_tile, lij_tile)\r\n                dst_out = pl.store(dst_tile, [0, 0], dst)\r\n            else:\r\n                zero_tile = pl.tile.full([_Q_TILE, _HEAD_DIM], dtype=pl.FP32, value=0.0)\r\n                dst_out = pl.store(zero_tile, [0, 0], dst)\r\n        else:\r\n            mi_tile_nd = pl.reshape(mi_tile, [1, _Q_TILE])\r\n            mij_tile_nd = pl.reshape(mij_tile, [1, _Q_TILE])\r\n            li_tile_nd = pl.reshape(li_tile, [1, _Q_TILE])\r\n            lij_tile_nd = pl.reshape(lij_tile, [1, _Q_TILE])\r\n\r\n            mi_new = pl.maximum(mi_tile_nd, mij_tile_nd)\r\n            mi_diff = pl.sub(mi_tile_nd, mi_new)\r\n            alpha = pl.exp(mi_diff)\r\n            mij_diff = pl.sub(mij_tile_nd, mi_new)\r\n            beta = pl.exp(mij_diff)\r\n\r\n            li_scaled = pl.mul(alpha, li_tile_nd)\r\n            lij_scaled = pl.mul(beta, lij_tile_nd)\r\n            li_updated = pl.add(li_scaled, lij_scaled)\r\n\r\n            alpha_dn = pl.reshape(alpha, [_Q_TILE, 1])\r\n            oi_scaled = pl.row_expand_mul(oi_tile, alpha_dn)\r\n            beta_dn = pl.reshape(beta, [_Q_TILE, 1])\r\n            oi_new_scaled = pl.row_expand_mul(oi_new_tile, beta_dn)\r\n            oi_updated = pl.add(oi_scaled, oi_new_scaled)\r\n\r\n            mi_new_dn = pl.reshape(mi_new, [_Q_TILE, 1])\r\n            li_updated_dn = pl.reshape(li_updated, [_Q_TILE, 1])\r\n\r\n            mi_out = pl.store(mi_new_dn, [0, 0], mi)\r\n            li_out = pl.store(li_updated_dn, [0, 0], li)\r\n            oi_out = pl.store(oi_updated, [0, 0], oi)\r\n\r\n            if is_last:\r\n                dst_tile = pl.row_expand_div(oi_updated, li_updated_dn)\r\n                dst_out = pl.store(dst_tile, [0, 0], dst)\r\n            else:\r\n                zero_tile = pl.tile.full([_Q_TILE, _HEAD_DIM], dtype=pl.FP32, value=0.0)\r\n                dst_out = pl.store(zero_tile, [0, 0], dst)\r\n\r\n        return mi_out, li_out, oi_out, dst_out\r\n\r\n    # -----------------------------------------------------------------------\r\n    # Program definition\r\n    # -----------------------------------------------------------------------\r\n\r\n    @pl.program\r\n    class DynamicPagedAttentionProgram:\r\n        \"\"\"Paged attention with dynamic-shape InCore kernels (online softmax).\r\n\r\n        InCore kernels are defined inside build_dynamic_paged_attention_program()\r\n        and capture _Q_TILE, _HEAD_DIM, _BLOCK_SIZE as closure variables for\r\n        load tile sizes, while their type annotations reference module-level\r\n        pl.dynamic() variables (Q_HEADS, HEAD_DIM_DYN, BLOCK_SIZE_DYN).\r\n        The 5-kernel pipeline and orchestration loops are identical in structure\r\n        to the static version in paged_attention_example.py.\r\n        \"\"\"\r\n\r\n        @pl.function(type=pl.FunctionType.Orchestration)\r\n        def paged_attention(\r\n            self,\r\n            query: pl.Tensor[[QUERY_ROWS_DYN, HEAD_DIM_DYN], pl.BF16],\r\n            key_cache: pl.Tensor[[KEY_CACHE_ROWS_DYN, HEAD_DIM_DYN], pl.BF16],\r\n            value_cache: pl.Tensor[[KEY_CACHE_ROWS_DYN, HEAD_DIM_DYN], pl.BF16],\r\n            block_table: pl.Tensor[[BLOCK_TABLE_FLAT_DYN], pl.INT32],\r\n            context_lens: pl.Tensor[[BATCH_DYN], pl.INT32],\r\n            out: pl.Out[pl.Tensor[[QUERY_ROWS_DYN, HEAD_DIM_DYN], pl.FP32]],\r\n        ) -> pl.Tensor[[QUERY_ROWS_DYN, HEAD_DIM_DYN], pl.FP32]:\r\n            \"\"\"Paged attention orchestration with dynamic-shape InCore kernels.\r\n\r\n            Same 5-stage pipeline as the static version (init_inplace,\r\n            qk_matmul, softmax_prepare, pv_matmul, online_update).  InCore\r\n            kernels are closures defined inside build_dynamic_paged_attention_program()\r\n            and referenced here by their local names (dyn_kernel_*).\r\n            Shape derivations: batch = context_lens.dim(0),\r\n            head_dim = query.dim(1), num_heads = query.dim(0) // batch,\r\n            block_num = block_table.dim(0) // batch,\r\n            block_size = value_cache.dim(0) // block_table.dim(0).\r\n            \"\"\"\r\n            batch_cfg = pl.tensor.dim(context_lens, 0)\r\n            query_rows = pl.tensor.dim(query, 0)\r\n            head_dim_cfg = pl.tensor.dim(query, 1)\r\n            value_cache_rows = pl.tensor.dim(value_cache, 0)\r\n            block_table_size = pl.tensor.dim(block_table, 0)\r\n            num_heads_cfg = query_rows // batch_cfg\r\n            block_size_cfg = value_cache_rows // block_table_size\r\n            block_num_cfg = block_table_size // batch_cfg\r\n\r\n            q_head_num = num_heads_cfg\r\n            # ceil-divide: number of q_tile-sized chunks needed to cover all query heads\r\n            q_loop_cfg = (q_head_num + q_tile - 1) // q_tile\r\n\r\n            for b_idx in pl.range(batch_cfg):\r\n                cur_seq = pl.tensor.read(context_lens, [b_idx])\r\n                # ceil-divide: number of KV blocks touched by this request\r\n                bn_this_batch = (cur_seq + block_size_cfg - 1) // block_size_cfg\r\n                for q_idx in pl.range(q_loop_cfg):\r\n                    # Row offset into the flat query tensor for this (batch, q_tile) tile\r\n                    cur_offset = b_idx * q_head_num + q_idx * q_tile\r\n\r\n                    # Allocate zero-initialised accumulators for the online softmax state\r\n                    oi_buf = pl.create_tensor([q_tile, head_dim_cfg], dtype=pl.FP32)\r\n                    li_buf = pl.create_tensor([q_tile, 1], dtype=pl.FP32)\r\n                    mi_buf = pl.create_tensor([q_tile, 1], dtype=pl.FP32)\r\n                    # Bind concrete tensor shapes to dynamic type annotations (no-op passthrough)\r\n                    oi, li_update, mi_update = dyn_kernel_init_inplace(oi_buf, li_buf, mi_buf)\r\n\r\n                    for bn in pl.range(bn_this_batch):\r\n                        # Slice the query tile for this head-tile and batch entry\r\n                        qi = pl.slice(query, [q_tile, head_dim_cfg], [cur_offset, 0])\r\n\r\n                        # Look up the physical block index in the page table\r\n                        cur_block_idx = pl.tensor.read(block_table, [b_idx * block_num_cfg + bn])\r\n                        # Number of valid tokens in this block (last block may be partial)\r\n                        valid_len = pl.min(block_size_cfg, cur_seq - bn * block_size_cfg)\r\n                        # Starting row of this physical block in the flat KV-cache pool\r\n                        kv_block_row = cur_block_idx * block_size_cfg\r\n\r\n                        # Slice the key block: key_cache is [KV_rows, head_dim]\r\n                        kj = pl.slice(key_cache, [block_size_cfg, head_dim_cfg], [kv_block_row, 0])\r\n                        # Slice the value block: value_cache is stored as [KV_rows, head_dim]\r\n                        vj = pl.slice(value_cache, [block_size_cfg, head_dim_cfg], [kv_block_row, 0])\r\n\r\n                        # Stage 1: QK matmul — sij[q_tile, block_size] = qi @ kj.T\r\n                        sij_buf = pl.create_tensor([q_tile, block_size_cfg], dtype=pl.FP32)\r\n                        sij = dyn_kernel_qk_matmul(qi, kj, sij_buf)\r\n\r\n                        # Mask out padding columns beyond valid_len to avoid\r\n                        # including out-of-range tokens in the softmax\r\n                        sij_valid = pl.slice(sij, [q_tile, valid_len], [0, 0])\r\n\r\n                        # Stage 2: softmax prepare — scale, row_max (mi), exp, row_sum (li)\r\n                        pij_f16_buf = pl.create_tensor([q_tile, block_size_cfg], dtype=pl.BF16)\r\n                        mi_sm_buf = pl.create_tensor([q_tile, 1], dtype=pl.FP32)\r\n                        li_sm_buf = pl.create_tensor([q_tile, 1], dtype=pl.FP32)\r\n                        pij_f16, mi, li = dyn_kernel_softmax_prepare(\r\n                            sij_valid,\r\n                            1.0,\r\n                            pij_f16_buf,\r\n                            mi_sm_buf,\r\n                            li_sm_buf,\r\n                        )\r\n\r\n                        # Stage 3: PV matmul — oi_tmp[q_tile, head_dim] = pij @ vj\r\n                        oi_tmp_buf = pl.create_tensor([q_tile, head_dim_cfg], dtype=pl.FP32)\r\n                        oi_tmp = dyn_kernel_pv_matmul(pij_f16, vj, oi_tmp_buf)\r\n\r\n                        # Determine position flags for the online softmax update kernel\r\n                        if bn == 0:\r\n                            is_first = pl.yield_(1)\r\n                        else:\r\n                            is_first = pl.yield_(0)\r\n                        if bn == bn_this_batch - 1:\r\n                            is_last = pl.yield_(1)\r\n                        else:\r\n                            is_last = pl.yield_(0)\r\n\r\n                        # Stage 4: online update — merge (mij, lij, oi_new) into (mi, li, oi)\r\n                        # and write final normalised output on the last block\r\n                        out_view_buf = pl.slice(out, [q_tile, head_dim_cfg], [cur_offset, 0])\r\n                        mi_update, li_update, oi, out_view = dyn_kernel_online_update(\r\n                            mi,\r\n                            li,\r\n                            oi_tmp,\r\n                            mi_update,\r\n                            li_update,\r\n                            oi,\r\n                            out_view_buf,\r\n                            is_first,\r\n                            is_last,\r\n                        )\r\n\r\n            return out\r\n\r\n    return DynamicPagedAttentionProgram\r\n\r\n\r\ndef golden(tensors: dict, params: dict | None = None) -> None:\r\n    \"\"\"Reference paged-attention computation (torch) for the dynamic-shape program.\r\n\r\n    Derives all shape parameters from tensor dimensions instead of a config tensor,\r\n    matching the orchestration function's pl.tensor.dim() derivations.\r\n    Scale is hardcoded to 1.0 to match the orchestration function.\r\n\r\n    Args:\r\n        tensors: Dict mapping tensor names to torch tensors.\r\n        params: Unused.\r\n    \"\"\"\r\n    context_lens = tensors[\"context_lens\"]\r\n    query = tensors[\"query\"]\r\n    key_cache = tensors[\"key_cache\"]\r\n    value_cache = tensors[\"value_cache\"]\r\n    block_table_flat = tensors[\"block_table\"]\r\n\r\n    batch = context_lens.shape[0]\r\n    num_heads = query.shape[0] // batch\r\n    head_dim = query.shape[1]\r\n    # Mirrors the orchestration function's pl.tensor.dim() derivation:\r\n    # block_size = value_cache.rows / block_table.rows  (rows per physical block)\r\n    block_size = value_cache.shape[0] // block_table_flat.shape[0]\r\n    max_num_blocks_per_req = block_table_flat.shape[0] // batch\r\n    scale = 1.0\r\n\r\n    # Reshape flat tensors into 3-D views for batch-matmul\r\n    query_3d = query.float().reshape(batch, num_heads, head_dim)\r\n    total_pool_blocks = batch * max_num_blocks_per_req\r\n    key_cache_3d = key_cache.float().reshape(total_pool_blocks, block_size, head_dim)\r\n    value_cache_3d = value_cache.float().reshape(total_pool_blocks, block_size, head_dim)\r\n    block_table = block_table_flat.reshape(batch, max_num_blocks_per_req)\r\n\r\n    out = torch.zeros((batch, num_heads, head_dim), dtype=torch.float32)\r\n    q_tile = 16\r\n    # Maximum number of KV blocks across all requests in the batch\r\n    max_bn = int((context_lens.max().item() + block_size - 1) // block_size)\r\n\r\n    for q_offset in range(0, num_heads, q_tile):\r\n        q_tile_size = min(q_tile, num_heads - q_offset)\r\n        qi = query_3d[:, q_offset : q_offset + q_tile_size, :]  # [batch, q_tile, head_dim]\r\n        # Online softmax state: sentinel init so the first block is handled by the\r\n        # general update formula (mi=-inf makes alpha=0, beta=1 on the first merge).\r\n        mi = torch.full((batch, q_tile_size, 1), float(\"-inf\"))\r\n        li = torch.zeros((batch, q_tile_size, 1))\r\n        oi = torch.zeros((batch, q_tile_size, head_dim))\r\n\r\n        for bn in range(max_bn):\r\n            # valid_lens[b]: how many tokens of block bn are valid for request b\r\n            valid_lens = torch.clamp(context_lens - bn * block_size, min=0, max=block_size)\r\n            if not (valid_lens > 0).any():\r\n                break\r\n            block_indices = block_table[:, bn]  # [batch]\r\n            kj_all = key_cache_3d[block_indices]  # [batch, block_size, head_dim]\r\n            vj_all = value_cache_3d[block_indices]  # [batch, block_size, head_dim]\r\n\r\n            # Stage 1: QK matmul — sij[batch, q_tile, block_size] = qi @ kj.T * scale\r\n            sij = torch.bmm(qi, kj_all.transpose(1, 2)) * scale  # [batch, q_tile, block_size]\r\n            # Mask padding columns so they don't affect row_max / row_sum\r\n            pos = torch.arange(block_size).unsqueeze(0)  # [1, block_size]\r\n            valid_mask = (pos < valid_lens.unsqueeze(1)).unsqueeze(1)  # [batch, 1, block_size]\r\n            sij = sij.masked_fill(~valid_mask, float(\"-inf\"))\r\n\r\n            # Stage 2: softmax prepare — row_max, exp, cast, row_sum\r\n            mij = sij.max(dim=-1, keepdim=True)[0].clamp(min=-1e30)  # [batch, q_tile, 1]\r\n            pij = torch.exp(sij - mij).masked_fill(~valid_mask, 0.0)\r\n            # Simulate BF16 cast to match the InCore kernel's precision\r\n            pij = pij.to(torch.bfloat16).to(torch.float32)\r\n            lij = pij.sum(dim=-1, keepdim=True)  # [batch, q_tile, 1]\r\n\r\n            # Stage 3: PV matmul — oi_new[batch, q_tile, head_dim] = pij @ vj\r\n            oi_new = torch.bmm(pij, vj_all)  # [batch, q_tile, head_dim]\r\n\r\n            # Stage 4: online update — unconditional merge; the sentinel mi=-inf ensures\r\n            # alpha=0/beta=1 on the first valid block, making explicit bn==0 branching\r\n            # unnecessary and correct for heterogeneous per-request starting points.\r\n            mi_new = torch.maximum(mi, mij)\r\n            alpha = torch.exp(mi - mi_new)  # rescale factor for old accumulator\r\n            beta = torch.exp(mij - mi_new)  # rescale factor for new block\r\n            li = alpha * li + beta * lij\r\n            oi = alpha * oi + beta * oi_new\r\n            mi = mi_new\r\n\r\n        assert (li > 0).any(), \"No KV blocks processed for this query tile\"\r\n        out[:, q_offset : q_offset + q_tile_size, :] = oi / li\r\n\r\n    tensors[\"out\"][:] = out.reshape(batch * num_heads, head_dim)\r\n\r\n\r\ndef build_tensors(\r\n    batch: int,\r\n    num_heads: int,\r\n    head_dim: int,\r\n    block_size: int,\r\n    max_num_blocks_per_req: int,\r\n    context_len: int,\r\n) -> tuple[torch.Tensor, ...]:\r\n    \"\"\"Build torch tensors matching the dynamic paged_attention orchestration signature.\r\n\r\n    Returns:\r\n        (query, key_cache, value_cache, block_table, context_lens, out)\r\n    \"\"\"\r\n    query_rows = batch * num_heads\r\n    key_cache_rows = batch * max_num_blocks_per_req * block_size\r\n    block_table_flat_size = batch * max_num_blocks_per_req\r\n\r\n    context_lens = torch.full((batch,), context_len, dtype=torch.int32)\r\n    block_table = torch.randint(\r\n        0, max(block_table_flat_size, 1), size=(batch, max_num_blocks_per_req), dtype=torch.int32\r\n    ).flatten()\r\n\r\n    query = torch.randn(query_rows, head_dim, dtype=torch.bfloat16)\r\n    key_cache = torch.randn(key_cache_rows, head_dim, dtype=torch.bfloat16)\r\n    value_cache = torch.randn(key_cache_rows, head_dim, dtype=torch.bfloat16)\r\n    out = torch.zeros(query_rows, head_dim, dtype=torch.float32)\r\n\r\n    return query, key_cache, value_cache, block_table, context_lens, out\r\n\r\n\r\ndef main():\r\n    \"\"\"Run a single dynamic paged-attention example and verify against the golden reference.\r\n\r\n    Uses a large batch (64) with 16 query heads, 128-dim heads, and 128-token KV\r\n    blocks.  The program is built once via build_dynamic_paged_attention_program()\r\n    and executed on the target device with tolerance atol/rtol=2e-2.\r\n    \"\"\"\r\n    parser = argparse.ArgumentParser(description=\"Dynamic paged attention example\")\r\n    parser.add_argument(\r\n        \"--enable-l2-swimlane\",\r\n        action=\"store_true\",\r\n        default=False,\r\n        help=\"Enable on-device runtime profiling and generate swimlane JSON\",\r\n    )\r\n    args = parser.parse_args()\r\n\r\n    batch = 64\r\n    num_heads = 16\r\n    head_dim = 128\r\n    block_size = 128\r\n    max_model_len = 32768\r\n    context_len = 8192\r\n    q_tile = 16\r\n    max_num_blocks_per_req = max_model_len // block_size  # 256\r\n\r\n    program = build_dynamic_paged_attention_program(\r\n        q_tile=q_tile,\r\n        head_dim=head_dim,\r\n        block_size=block_size,\r\n    )\r\n\r\n    query, key_cache, value_cache, block_table, context_lens, out = build_tensors(\r\n        batch=batch,\r\n        num_heads=num_heads,\r\n        head_dim=head_dim,\r\n        block_size=block_size,\r\n        max_num_blocks_per_req=max_num_blocks_per_req,\r\n        context_len=context_len,\r\n    )\r\n    run(\r\n        program,\r\n        query,\r\n        key_cache,\r\n        value_cache,\r\n        block_table,\r\n        context_lens,\r\n        out,\r\n        config=RunConfig(\r\n            platform=\"a2a3\",\r\n            device_id=11,\r\n            strategy=OptimizationStrategy.Default,\r\n            dump_passes=True,\r\n            backend_type=BackendType.Ascend910B,\r\n            enable_l2_swimlane=args.enable_l2_swimlane,\r\n        ),\r\n    )\r\n\r\n    # Golden validation\r\n    expected_out = out.clone()\r\n    golden(\r\n        {\r\n            \"query\": query,\r\n            \"key_cache\": key_cache,\r\n            \"value_cache\": value_cache,\r\n            \"block_table\": block_table,\r\n            \"context_lens\": context_lens,\r\n            \"out\": expected_out,\r\n        },\r\n    )\r\n    assert torch.allclose(out, expected_out, rtol=2e-2, atol=2e-2), (\r\n        f\"Validation failed: max diff = {(out - expected_out).abs().max().item()}\"\r\n    )\r\n    print(\"PASSED\")\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    main()\r\n","examples/models/07_paged_attention_multi_config.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\"\"\"\r\nPaged Attention Multi-Config Example\r\n\r\nBuilds a multi-config paged attention program using the PyPTO DSL with:\r\n- N_UNROLL block grouping per unroll iteration\r\n- Dynamic runtime shapes derived from input tensor dimensions via pl.tensor.dim()\r\n- Per-request context length from context_lens tensor\r\n- valid_len support for partial blocks (last block may have fewer valid columns)\r\n- Two-pass softmax within each unroll group + online update across groups\r\n\r\nOrchestration pre-extracts block_indices via pl.slice() from block_table.\r\nKernels receive block_indices tensor view (no block_table + bt_offset indirection).\r\n\r\nDynamic axis description follows the dynamic paged-attention example: tensor\r\ntype annotations use module-level pl.dynamic() variables, while InCore kernel\r\nbodies use builder closures (q_tile, head_dim, block_size) for fixed-size loads.\r\nRuntime values (batch, num_heads, head_dim, block_size, block_num) are derived\r\nfrom input tensor shapes inside the orchestration via pl.tensor.dim().\r\n\r\nKey interface difference vs multi-config C++ impl:\r\n  multi-config passes N_UNROLL individual scalar block_indices to each kernel.\r\n  PyPTO passes a single block_indices tensor view (functionally equivalent —\r\n  same data access pattern: block_indices[i] -> physical block index).\r\n\r\nTile dimensions (matching multi-config Case2, q_tile=16):\r\n  QK Matmul:       qi(16, 128) @ kj.T(128, 64) -> sij(16, 64)\r\n  Softmax:         sij(16, N) -> pij(16, N) bf16, mi(16, 1), li(16, 1)\r\n  PV Matmul:       pij(16, 64) @ vj(64, 128) -> oi(16, 128)\r\n  Online Update:   operates on (16, 128) data tiles, (16, 1) scalar tiles\r\n\r\nModule-level InCore kernels (reusable, importable):\r\n  kernel_softmax_prepare, kernel_online_update\r\n\r\nFactory functions for multi-block kernels:\r\n  make_kernel_qk_matmul()\r\n  make_kernel_pv_matmul()\r\n\"\"\"\r\n\r\n# DSL function bodies are parsed as AST — dynamic var names look undefined to pyright.\r\n# pyright: reportUndefinedVariable=false\r\n\r\nimport argparse\r\n\r\nimport pypto.language as pl\r\nimport torch\r\nfrom pypto.backend import BackendType\r\nfrom pypto.ir.pass_manager import OptimizationStrategy\r\nfrom pypto.runtime import RunConfig, run\r\n\r\n# ── Constants ────────────────────────────────────────────────────────────────\r\nQ_TILE = 16\r\nBLOCK_SIZE = 64\r\nHEAD_DIM = 128\r\nN_UNROLL = 64\r\nN_UNROLL_Q = N_UNROLL * Q_TILE  # 1024 — static sij/pij buffer height\r\n\r\n# ── Module-level dynamic variables ───────────────────────────────────────────\r\n# Used only in tensor type annotations; InCore kernel bodies and orchestration\r\n# bodies use builder closure ints / pl.tensor.dim() Scalars for actual sizes.\r\nQ_HEADS = pl.dynamic(\"Q_HEADS\")  # query tile rows (= q_tile)\r\nHEAD_DIM_DYN = pl.dynamic(\"HEAD_DIM_DYN\")  # per-head feature dim on the Q/output side\r\n# KV-side head_dim is given a distinct dynamic var so that within a single InCore\r\n# kernel call (e.g. PV matmul with value_cache + oi_new outputs), the type-system\r\n# unification does not conflict between the orchestration-typed value_cache\r\n# (KEY_CACHE_ROWS_DYN, HEAD_DIM_DYN) and the create_tensor-typed oi_new buffer\r\n# whose head_dim is the concrete pl.tensor.dim() Scalar.  At call sites both\r\n# resolve to the same runtime value (head_dim_cfg).\r\nKV_HEAD_DIM_DYN = pl.dynamic(\"KV_HEAD_DIM_DYN\")\r\nBLOCK_SIZE_DYN = pl.dynamic(\"BLOCK_SIZE_DYN\")  # KV-cache block size (= block_size)\r\nBATCH_DYN = pl.dynamic(\"BATCH_DYN\")  # number of requests\r\nQUERY_ROWS_DYN = pl.dynamic(\"QUERY_ROWS_DYN\")  # batch * num_heads\r\nKEY_CACHE_ROWS_DYN = pl.dynamic(\"KEY_CACHE_ROWS_DYN\")  # batch * max_blocks_per_req * block_size\r\nBLOCK_TABLE_FLAT_DYN = pl.dynamic(\"BLOCK_TABLE_FLAT_DYN\")  # batch * max_blocks_per_req\r\n\r\n\r\n# ── Kernel factory functions ──────────────────────────────────────────────────\r\n\r\n\r\ndef make_kernel_softmax_prepare(q_tile: int, block_size: int, n_unroll_q: int):\r\n    \"\"\"Create softmax_prepare InCore kernel with parameterised tile dimensions.\"\"\"\r\n\r\n    @pl.function(type=pl.FunctionType.InCore)\r\n    def kernel_softmax_prepare(\r\n        sij_buf: pl.Tensor[[n_unroll_q, BLOCK_SIZE_DYN], pl.FP32],\r\n        scale: pl.Scalar[pl.FP32],\r\n        pij_buf: pl.Out[pl.Tensor[[n_unroll_q, BLOCK_SIZE_DYN], pl.BF16]],\r\n        mi_out: pl.Out[pl.Tensor[[Q_HEADS, 1], pl.FP32]],\r\n        li_out: pl.Out[pl.Tensor[[Q_HEADS, 1], pl.FP32]],\r\n        n_blocks: pl.Scalar[pl.INDEX],\r\n        last_valid_len: pl.Scalar[pl.INDEX],\r\n    ) -> tuple[\r\n        pl.Tensor[[n_unroll_q, BLOCK_SIZE_DYN], pl.BF16],\r\n        pl.Tensor[[Q_HEADS, 1], pl.FP32],\r\n        pl.Tensor[[Q_HEADS, 1], pl.FP32],\r\n    ]:\r\n        \"\"\"Two-pass softmax with partial-block support (VECTOR).\r\n\r\n        Pass 1 finds global row_max, pass 2 computes exp+sum.\r\n        The last block (i == n_blocks - 1) uses valid_shapes + fillpad to mask\r\n        out invalid columns with -inf so they don't affect row_max or row_sum.\r\n        Uses mi_out/li_out as GM scratch for cross-iteration state via store/load round-trips.\r\n        \"\"\"\r\n        # Pass 1: find global row_max across all blocks\r\n        for i, (mi_out_iter,) in pl.range(n_blocks, init_values=(mi_out,)):\r\n            if i == n_blocks - 1:\r\n                valid_len: pl.Scalar[pl.INDEX] = pl.yield_(last_valid_len)\r\n            else:\r\n                valid_len: pl.Scalar[pl.INDEX] = pl.yield_(block_size)\r\n            s_tile = pl.load(\r\n                sij_buf,\r\n                [i * q_tile, 0],\r\n                [q_tile, block_size],\r\n                valid_shapes=[q_tile, valid_len],\r\n                target_memory=pl.MemorySpace.Vec,\r\n            )\r\n            s_tile_padded = pl.tile.fillpad(s_tile, pad_value=pl.PadValue.min)\r\n            scaled = pl.mul(s_tile_padded, scale)\r\n            tmp_tile = pl.create_tile(\r\n                [q_tile, block_size],\r\n                dtype=pl.FP32,\r\n                target_memory=pl.MemorySpace.Vec,\r\n            )\r\n            local_max = pl.row_max(scaled, tmp_tile)\r\n\r\n            if i == 0:\r\n                mi_out_updated = pl.store(local_max, [0, 0], mi_out_iter)\r\n            else:\r\n                global_max = pl.load(\r\n                    mi_out_iter,\r\n                    [0, 0],\r\n                    [q_tile, 1],\r\n                    target_memory=pl.MemorySpace.Vec,\r\n                )\r\n                gm_nd = pl.reshape(global_max, [1, q_tile])\r\n                lm_nd = pl.reshape(local_max, [1, q_tile])\r\n                new_max = pl.reshape(pl.maximum(gm_nd, lm_nd), [q_tile, 1])\r\n                mi_out_updated = pl.store(new_max, [0, 0], mi_out_iter)\r\n            (mi_out_carry,) = pl.yield_(mi_out_updated)\r\n\r\n        # Pass 2: exp(s - global_max), cast to bf16, row_sum accumulation\r\n        for i, (pij_buf_iter, li_out_iter) in pl.range(n_blocks, init_values=(pij_buf, li_out)):\r\n            global_max = pl.load(\r\n                mi_out_carry,\r\n                [0, 0],\r\n                [q_tile, 1],\r\n                target_memory=pl.MemorySpace.Vec,\r\n            )\r\n            if i == n_blocks - 1:\r\n                valid_len_p2: pl.Scalar[pl.INDEX] = pl.yield_(last_valid_len)\r\n            else:\r\n                valid_len_p2: pl.Scalar[pl.INDEX] = pl.yield_(block_size)\r\n            s_tile_raw = pl.load(\r\n                sij_buf,\r\n                [i * q_tile, 0],\r\n                [q_tile, block_size],\r\n                valid_shapes=[q_tile, valid_len_p2],\r\n                target_memory=pl.MemorySpace.Vec,\r\n            )\r\n            s_tile_p2 = pl.tile.fillpad(s_tile_raw, pad_value=pl.PadValue.min)\r\n            scaled_p2 = pl.mul(s_tile_p2, scale)\r\n            centered = pl.row_expand_sub(scaled_p2, global_max)\r\n            exp_tile = pl.exp(centered)\r\n            pij_bf16 = pl.cast(exp_tile, target_type=pl.BF16)\r\n            pij_f32 = pl.cast(pij_bf16, target_type=pl.FP32)\r\n            pij_buf_updated = pl.store(pij_bf16, [i * q_tile, 0], pij_buf_iter)\r\n\r\n            tmp_tile_p2 = pl.create_tile(\r\n                [q_tile, block_size],\r\n                dtype=pl.FP32,\r\n                target_memory=pl.MemorySpace.Vec,\r\n            )\r\n            li_local = pl.row_sum(pij_f32, tmp_tile_p2)\r\n            li_local_nd = pl.reshape(li_local, [1, q_tile])\r\n\r\n            if i == 0:\r\n                li_out_updated = pl.store(li_local, [0, 0], li_out_iter)\r\n            else:\r\n                li_acc = pl.load(li_out_iter, [0, 0], [q_tile, 1])\r\n                li_acc_nd = pl.reshape(li_acc, [1, q_tile])\r\n                li_sum = pl.reshape(pl.add(li_acc_nd, li_local_nd), [q_tile, 1])\r\n                li_out_updated = pl.store(li_sum, [0, 0], li_out_iter)\r\n            pij_buf_carry, li_out_carry = pl.yield_(pij_buf_updated, li_out_updated)\r\n\r\n        return pij_buf_carry, mi_out_carry, li_out_carry\r\n\r\n    return kernel_softmax_prepare\r\n\r\n\r\ndef make_kernel_online_update(q_tile: int, head_dim: int):\r\n    \"\"\"Create online_update InCore kernel with parameterised tile dimensions.\"\"\"\r\n\r\n    @pl.function(type=pl.FunctionType.InCore)\r\n    def kernel_online_update(  # noqa: PLR0913\r\n        mij: pl.Tensor[[Q_HEADS, 1], pl.FP32],\r\n        lij: pl.Tensor[[Q_HEADS, 1], pl.FP32],\r\n        oi_new: pl.Tensor[[Q_HEADS, HEAD_DIM_DYN], pl.FP32],\r\n        mi: pl.InOut[pl.Tensor[[Q_HEADS, 1], pl.FP32]],\r\n        li: pl.InOut[pl.Tensor[[Q_HEADS, 1], pl.FP32]],\r\n        oi: pl.InOut[pl.Tensor[[Q_HEADS, HEAD_DIM_DYN], pl.FP32]],\r\n        dst: pl.Out[pl.Tensor[[Q_HEADS, HEAD_DIM_DYN], pl.FP32]],\r\n        is_first: pl.Scalar[pl.INDEX],\r\n        is_last: pl.Scalar[pl.INDEX],\r\n    ) -> tuple[\r\n        pl.Tensor[[Q_HEADS, 1], pl.FP32],\r\n        pl.Tensor[[Q_HEADS, 1], pl.FP32],\r\n        pl.Tensor[[Q_HEADS, HEAD_DIM_DYN], pl.FP32],\r\n        pl.Tensor[[Q_HEADS, HEAD_DIM_DYN], pl.FP32],\r\n    ]:\r\n        \"\"\"Online softmax update with inplace mi/li/oi (VECTOR).\r\n\r\n        Merges current group's (mij, lij, oi_new) into running accumulators\r\n        (mi, li, oi). On last iteration, writes normalised output to dst.\r\n        \"\"\"\r\n        mij_tile = pl.load(mij, [0, 0], [q_tile, 1], target_memory=pl.MemorySpace.Vec)\r\n        lij_tile = pl.load(lij, [0, 0], [q_tile, 1], target_memory=pl.MemorySpace.Vec)\r\n        oi_new_tile = pl.load(oi_new, [0, 0], [q_tile, head_dim], target_memory=pl.MemorySpace.Vec)\r\n        mi_tile = pl.load(mi, [0, 0], [q_tile, 1], target_memory=pl.MemorySpace.Vec)\r\n        li_tile = pl.load(li, [0, 0], [q_tile, 1], target_memory=pl.MemorySpace.Vec)\r\n        oi_tile = pl.load(oi, [0, 0], [q_tile, head_dim], target_memory=pl.MemorySpace.Vec)\r\n\r\n        if is_first == 1:\r\n            mi_out = pl.store(mij_tile, [0, 0], mi)\r\n            li_out = pl.store(lij_tile, [0, 0], li)\r\n            oi_out = pl.store(oi_new_tile, [0, 0], oi)\r\n            if is_last == 1:\r\n                dst_tile = pl.row_expand_div(oi_new_tile, lij_tile)\r\n                dst_out = pl.store(dst_tile, [0, 0], dst)\r\n            else:\r\n                zero_tile = pl.tile.full([q_tile, head_dim], dtype=pl.FP32, value=0.0)\r\n                dst_out = pl.store(zero_tile, [0, 0], dst)\r\n        else:\r\n            # Reshape DN [q_tile,1] -> ND [1,q_tile] for element-wise ops\r\n            mi_tile_nd = pl.reshape(mi_tile, [1, q_tile])\r\n            mij_tile_nd = pl.reshape(mij_tile, [1, q_tile])\r\n            li_tile_nd = pl.reshape(li_tile, [1, q_tile])\r\n            lij_tile_nd = pl.reshape(lij_tile, [1, q_tile])\r\n\r\n            mi_new = pl.maximum(mi_tile_nd, mij_tile_nd)\r\n            mi_diff = pl.sub(mi_tile_nd, mi_new)\r\n            alpha = pl.exp(mi_diff)\r\n            mij_diff = pl.sub(mij_tile_nd, mi_new)\r\n            beta = pl.exp(mij_diff)\r\n\r\n            li_scaled = pl.mul(alpha, li_tile_nd)\r\n            lij_scaled = pl.mul(beta, lij_tile_nd)\r\n            li_updated = pl.add(li_scaled, lij_scaled)\r\n\r\n            alpha_dn = pl.reshape(alpha, [q_tile, 1])\r\n            oi_scaled = pl.row_expand_mul(oi_tile, alpha_dn)\r\n            beta_dn = pl.reshape(beta, [q_tile, 1])\r\n            oi_new_scaled = pl.row_expand_mul(oi_new_tile, beta_dn)\r\n            oi_updated = pl.add(oi_scaled, oi_new_scaled)\r\n\r\n            mi_new_dn = pl.reshape(mi_new, [q_tile, 1])\r\n            li_updated_dn = pl.reshape(li_updated, [q_tile, 1])\r\n\r\n            mi_out = pl.store(mi_new_dn, [0, 0], mi)\r\n            li_out = pl.store(li_updated_dn, [0, 0], li)\r\n\r\n            oi_out = pl.store(oi_updated, [0, 0], oi)\r\n            if is_last == 1:\r\n                dst_tile = pl.row_expand_div(oi_updated, li_updated_dn)\r\n                dst_out = pl.store(dst_tile, [0, 0], dst)\r\n            else:\r\n                zero_tile = pl.tile.full([q_tile, head_dim], dtype=pl.FP32, value=0.0)\r\n                dst_out = pl.store(zero_tile, [0, 0], dst)\r\n\r\n        return mi_out, li_out, oi_out, dst_out\r\n\r\n    return kernel_online_update\r\n\r\n\r\n# ── Module-level kernel instances (backward-compatible imports) ───────────────\r\nkernel_softmax_prepare = make_kernel_softmax_prepare(Q_TILE, BLOCK_SIZE, N_UNROLL_Q)\r\nkernel_online_update = make_kernel_online_update(Q_TILE, HEAD_DIM)\r\n\r\n\r\n# ── Factory functions for multi-config kernels ──────────────────────────\r\n\r\n\r\ndef make_kernel_qk_matmul(\r\n    q_tile: int = Q_TILE,\r\n    head_dim: int = HEAD_DIM,\r\n    block_size: int = BLOCK_SIZE,\r\n    n_unroll: int = N_UNROLL,\r\n    n_unroll_q: int = N_UNROLL_Q,\r\n):\r\n    \"\"\"Create a multi-block QK matmul InCore kernel using pre-extracted block indices.\r\n\r\n    Multi-config: receives block_indices tensor (pre-sliced by orchestration)\r\n    instead of full block_table + bt_offset.\r\n\r\n    Tensor type annotations use module-level pl.dynamic() variables so the kernel\r\n    accepts any key_cache row count at runtime; load shapes use the builder\r\n    closure ints (q_tile / head_dim / block_size).\r\n\r\n    Parameters\r\n    ----------\r\n    q_tile: query tile height\r\n    head_dim: per-head feature dimension\r\n    block_size: KV-cache block size\r\n    n_unroll: number of blocks per unroll group\r\n    n_unroll_q: n_unroll * q_tile (static buffer height)\r\n    \"\"\"\r\n\r\n    @pl.function(type=pl.FunctionType.InCore)\r\n    def kernel_qk_matmul(\r\n        qi: pl.Tensor[[Q_HEADS, HEAD_DIM_DYN], pl.BF16],\r\n        key_cache: pl.Tensor[[KEY_CACHE_ROWS_DYN, KV_HEAD_DIM_DYN], pl.BF16],\r\n        sij_buf: pl.Out[pl.Tensor[[n_unroll_q, BLOCK_SIZE_DYN], pl.FP32]],\r\n        block_indices: pl.Tensor[[n_unroll], pl.INT32],\r\n        n_blocks: pl.Scalar[pl.INDEX],\r\n    ) -> pl.Tensor[[n_unroll_q, BLOCK_SIZE_DYN], pl.FP32]:\r\n        \"\"\"Multi-block QK matmul: sij[i] = qi @ kj[i].T, vertically stacked (CUBE).\r\n\r\n        Loops over n_blocks, looking up physical block indices via block_indices\r\n        (pre-extracted by orchestration from block_table).\r\n        key_cache is stored as (rows, head_dim); transpose at load to get (head_dim, block_size).\r\n        \"\"\"\r\n        for i, (sij_buf_iter,) in pl.range(n_blocks, init_values=(sij_buf,)):\r\n            phys_block = pl.read(block_indices, i)\r\n\r\n            kj_row = phys_block * block_size\r\n\r\n            qi_l1 = pl.load(\r\n                qi,\r\n                [0, 0],\r\n                [q_tile, head_dim],\r\n                target_memory=pl.MemorySpace.Mat,\r\n            )\r\n            kj_nat = pl.load(\r\n                key_cache,\r\n                [kj_row, 0],\r\n                [block_size, head_dim],\r\n                target_memory=pl.MemorySpace.Mat,\r\n            )\r\n            kj_l1 = pl.tile.transpose_view(kj_nat)\r\n            qi_l0a = pl.move(qi_l1, target_memory=pl.MemorySpace.Left)\r\n            kj_l0b = pl.move(kj_l1, target_memory=pl.MemorySpace.Right)\r\n            sij_l0c = pl.matmul(qi_l0a, kj_l0b)\r\n            sij_buf_updated = pl.store(sij_l0c, [i * q_tile, 0], sij_buf_iter)\r\n            (sij_buf_out,) = pl.yield_(sij_buf_updated)\r\n        return sij_buf_out\r\n\r\n    return kernel_qk_matmul\r\n\r\n\r\ndef make_kernel_pv_matmul(\r\n    q_tile: int = Q_TILE,\r\n    head_dim: int = HEAD_DIM,\r\n    block_size: int = BLOCK_SIZE,\r\n    n_unroll: int = N_UNROLL,\r\n    n_unroll_q: int = N_UNROLL_Q,\r\n):\r\n    \"\"\"Create a SplitK PV matmul InCore kernel using pre-extracted block indices.\r\n\r\n    Multi-config: receives block_indices tensor (pre-sliced by orchestration)\r\n    instead of full block_table + bt_offset.\r\n\r\n    Tensor type annotations use module-level pl.dynamic() variables so the kernel\r\n    accepts any value_cache row count at runtime; load shapes use the builder\r\n    closure ints (q_tile / head_dim / block_size).\r\n\r\n    Parameters\r\n    ----------\r\n    q_tile: query tile height\r\n    head_dim: per-head feature dimension\r\n    block_size: KV-cache block size\r\n    n_unroll: number of blocks per unroll group\r\n    n_unroll_q: n_unroll * q_tile (static buffer height)\r\n    \"\"\"\r\n\r\n    @pl.function(type=pl.FunctionType.InCore)\r\n    def kernel_pv_matmul(\r\n        pij_buf: pl.Tensor[[n_unroll_q, BLOCK_SIZE_DYN], pl.BF16],\r\n        value_cache: pl.Tensor[[KEY_CACHE_ROWS_DYN, KV_HEAD_DIM_DYN], pl.BF16],\r\n        oi_new: pl.Out[pl.Tensor[[Q_HEADS, HEAD_DIM_DYN], pl.FP32]],\r\n        block_indices: pl.Tensor[[n_unroll], pl.INT32],\r\n        n_blocks: pl.Scalar[pl.INDEX],\r\n    ) -> pl.Tensor[[Q_HEADS, HEAD_DIM_DYN], pl.FP32]:\r\n        \"\"\"SplitK PV matmul: first block via matmul, rest via matmul_acc (CUBE).\r\n\r\n        Accumulates pij[i] @ vj[i] across n_blocks on L0C, then stores result.\r\n        block_indices pre-extracted by orchestration from block_table.\r\n        \"\"\"\r\n        # First block: matmul (creates L0C accumulator)\r\n        # Use (n_blocks - n_blocks) to get an INDEX-typed zero for the first read\r\n        first_idx = n_blocks - n_blocks\r\n        phys_block_0 = pl.read(block_indices, first_idx)\r\n        vj_row_0 = phys_block_0 * block_size\r\n\r\n        pij_l1 = pl.load(\r\n            pij_buf,\r\n            [0, 0],\r\n            [q_tile, block_size],\r\n            target_memory=pl.MemorySpace.Mat,\r\n        )\r\n        vj_l1 = pl.load(\r\n            value_cache,\r\n            [vj_row_0, 0],\r\n            [block_size, head_dim],\r\n            target_memory=pl.MemorySpace.Mat,\r\n        )\r\n        pij_l0a = pl.move(pij_l1, target_memory=pl.MemorySpace.Left)\r\n        vj_l0b = pl.move(vj_l1, target_memory=pl.MemorySpace.Right)\r\n        oi_l0c = pl.matmul(pij_l0a, vj_l0b)\r\n        oi_l0c_out = oi_l0c\r\n\r\n        # Remaining blocks: matmul_acc (accumulate onto L0C)\r\n        for i, (oi_l0c_iter,) in pl.range(1, n_blocks, init_values=(oi_l0c,)):\r\n            phys_block = pl.read(block_indices, i)\r\n            vj_row = phys_block * block_size\r\n\r\n            pij_l1_i = pl.load(\r\n                pij_buf,\r\n                [i * q_tile, 0],\r\n                [q_tile, block_size],\r\n                target_memory=pl.MemorySpace.Mat,\r\n            )\r\n            vj_l1_i = pl.load(\r\n                value_cache,\r\n                [vj_row, 0],\r\n                [block_size, head_dim],\r\n                target_memory=pl.MemorySpace.Mat,\r\n            )\r\n            pij_l0a_i = pl.move(pij_l1_i, target_memory=pl.MemorySpace.Left)\r\n            vj_l0b_i = pl.move(vj_l1_i, target_memory=pl.MemorySpace.Right)\r\n            oi_l0c_acc = pl.matmul_acc(oi_l0c_iter, pij_l0a_i, vj_l0b_i)\r\n            (oi_l0c_out,) = pl.yield_(oi_l0c_acc)\r\n\r\n        oi_new = pl.store(oi_l0c_out, [0, 0], oi_new)\r\n        return oi_new\r\n\r\n    return kernel_pv_matmul\r\n\r\n\r\n# ── Program builder ──────────────────────────────────────────────────────────\r\n\r\n\r\ndef build_paged_attention_multi_config_program(\r\n    q_tile: int = Q_TILE,\r\n    head_dim: int = HEAD_DIM,\r\n    block_size: int = BLOCK_SIZE,\r\n    n_unroll: int = N_UNROLL,\r\n):\r\n    \"\"\"Build paged-attention @pl.program with multi-config interface.\r\n\r\n    Orchestration derives runtime shapes (batch, num_heads, head_dim, block_size,\r\n    block_num) from input tensor dimensions via pl.tensor.dim(); per-request\r\n    context lengths come from context_lens.  Block indices are pre-extracted\r\n    via pl.slice() before kernel calls.\r\n\r\n    Parameters\r\n    ----------\r\n    q_tile:     query-head tile size (compile-time constant for InCore kernels)\r\n    head_dim:   per-head feature dimension (compile-time constant for loads)\r\n    block_size: KV-cache block size (compile-time constant for loads)\r\n    n_unroll:   number of blocks per unroll group\r\n    \"\"\"\r\n    n_unroll_q = n_unroll * q_tile\r\n\r\n    @pl.function(type=pl.FunctionType.InCore)\r\n    def kernel_init_inplace(\r\n        oi: pl.Out[pl.Tensor[[Q_HEADS, HEAD_DIM_DYN], pl.FP32]],\r\n        li: pl.Out[pl.Tensor[[Q_HEADS, 1], pl.FP32]],\r\n        mi: pl.Out[pl.Tensor[[Q_HEADS, 1], pl.FP32]],\r\n    ) -> tuple[\r\n        pl.Tensor[[Q_HEADS, HEAD_DIM_DYN], pl.FP32],\r\n        pl.Tensor[[Q_HEADS, 1], pl.FP32],\r\n        pl.Tensor[[Q_HEADS, 1], pl.FP32],\r\n    ]:\r\n        \"\"\"No-op passthrough that binds concrete create_tensor shapes to dynamic types.\r\n\r\n        pl.create_tensor zero-initialises the buffers before this call; this\r\n        function exists solely to propagate dynamic-shape types at the call site\r\n        so downstream kernel returns can be reassigned to the same variables.\r\n        \"\"\"\r\n        return oi, li, mi\r\n\r\n    _sf = make_kernel_softmax_prepare(q_tile, block_size, n_unroll_q)\r\n    _up = make_kernel_online_update(q_tile, head_dim)\r\n    _qk = make_kernel_qk_matmul(q_tile, head_dim, block_size, n_unroll, n_unroll_q)\r\n    _pv = make_kernel_pv_matmul(q_tile, head_dim, block_size, n_unroll, n_unroll_q)\r\n\r\n    @pl.program\r\n    class PagedAttentionMultiConfigProgram:\r\n        \"\"\"Paged attention with dynamic-shape orchestration and valid_len support.\"\"\"\r\n\r\n        @pl.function(type=pl.FunctionType.Orchestration)\r\n        def paged_attention(\r\n            self,\r\n            query: pl.Tensor[[QUERY_ROWS_DYN, HEAD_DIM_DYN], pl.BF16],\r\n            key_cache: pl.Tensor[[KEY_CACHE_ROWS_DYN, HEAD_DIM_DYN], pl.BF16],\r\n            value_cache: pl.Tensor[[KEY_CACHE_ROWS_DYN, HEAD_DIM_DYN], pl.BF16],\r\n            block_table: pl.Tensor[[BLOCK_TABLE_FLAT_DYN], pl.INT32],\r\n            context_lens: pl.Tensor[[BATCH_DYN], pl.INT32],\r\n            out: pl.Out[pl.Tensor[[QUERY_ROWS_DYN, HEAD_DIM_DYN], pl.FP32]],\r\n        ) -> pl.Tensor[[QUERY_ROWS_DYN, HEAD_DIM_DYN], pl.FP32]:\r\n            \"\"\"Paged attention orchestration with shapes derived from tensor dims.\r\n\r\n            Shape derivations: batch = context_lens.dim(0),\r\n            head_dim = query.dim(1), num_heads = query.dim(0) // batch,\r\n            block_num = block_table.dim(0) // batch,\r\n            block_size = value_cache.dim(0) // block_table.dim(0).\r\n            \"\"\"\r\n            batch_cfg = pl.tensor.dim(context_lens, 0)\r\n            query_rows = pl.tensor.dim(query, 0)\r\n            head_dim_cfg = pl.tensor.dim(query, 1)\r\n            value_cache_rows = pl.tensor.dim(value_cache, 0)\r\n            block_table_size = pl.tensor.dim(block_table, 0)\r\n            num_heads_cfg = query_rows // batch_cfg\r\n            block_size_cfg = value_cache_rows // block_table_size\r\n            block_num_cfg = block_table_size // batch_cfg\r\n            q_loop_cfg = (num_heads_cfg + q_tile - 1) // q_tile\r\n\r\n            for b_idx in pl.range(batch_cfg):\r\n                cur_seq = pl.tensor.read(context_lens, [b_idx])\r\n                bn_this_batch = (cur_seq + block_size_cfg - 1) // block_size_cfg\r\n                for q_idx in pl.range(q_loop_cfg):\r\n                    cur_offset = b_idx * num_heads_cfg + q_idx * q_tile\r\n\r\n                    # Allocate accumulators with concrete shapes, then bind to\r\n                    # dynamic-shape types via init_inplace so they can be carried\r\n                    # across iterations of the bn loop without a type mismatch.\r\n                    oi_buf = pl.create_tensor([q_tile, head_dim_cfg], dtype=pl.FP32)\r\n                    li_buf = pl.create_tensor([q_tile, 1], dtype=pl.FP32)\r\n                    mi_buf = pl.create_tensor([q_tile, 1], dtype=pl.FP32)\r\n                    oi, li_update, mi_update = kernel_init_inplace(oi_buf, li_buf, mi_buf)\r\n\r\n                    qi = pl.slice(query, [q_tile, head_dim_cfg], [cur_offset, 0])\r\n\r\n                    # ── n_unroll loop over KV blocks ──────────\r\n                    for bn in pl.range(0, bn_this_batch, n_unroll):  # type: ignore[reportArgumentType]\r\n                        n_blocks = pl.min(n_unroll, bn_this_batch - bn)  # type: ignore[reportArgumentType]\r\n                        bt_offset = b_idx * block_num_cfg + bn\r\n\r\n                        # Pre-extract block indices from block_table (multi-config)\r\n                        block_indices = pl.slice(block_table, [n_unroll], [bt_offset])  # type: ignore[reportArgumentType]\r\n\r\n                        # valid columns for the last block in this unroll group\r\n                        last_valid_len = pl.min(\r\n                            block_size_cfg, cur_seq - (bn + n_blocks - 1) * block_size_cfg\r\n                        )\r\n\r\n                        # 1. QK matmul (CUBE)\r\n                        sij_buf_in = pl.create_tensor([n_unroll_q, block_size_cfg], dtype=pl.FP32)\r\n                        sij_buf = _qk(\r\n                            qi,\r\n                            key_cache,\r\n                            sij_buf_in,\r\n                            block_indices,\r\n                            n_blocks,\r\n                        )\r\n\r\n                        # 2. Softmax prepare (VECTOR)\r\n                        pij_buf_in = pl.create_tensor([n_unroll_q, block_size_cfg], dtype=pl.BF16)\r\n                        mi_buf_in = pl.create_tensor([q_tile, 1], dtype=pl.FP32)\r\n                        li_buf_in = pl.create_tensor([q_tile, 1], dtype=pl.FP32)\r\n                        pij_buf, mi, li = _sf(\r\n                            sij_buf,\r\n                            1.0,\r\n                            pij_buf_in,\r\n                            mi_buf_in,\r\n                            li_buf_in,\r\n                            n_blocks,  # type: ignore[reportArgumentType]\r\n                            last_valid_len,  # type: ignore[reportArgumentType]\r\n                        )\r\n\r\n                        # 3. PV matmul (CUBE)\r\n                        oi_new_in = pl.create_tensor([q_tile, head_dim_cfg], dtype=pl.FP32)\r\n                        oi_new = _pv(\r\n                            pij_buf,\r\n                            value_cache,\r\n                            oi_new_in,\r\n                            block_indices,\r\n                            n_blocks,\r\n                        )\r\n\r\n                        # 4. Online update flags\r\n                        if bn == 0:\r\n                            is_first = pl.yield_(1)\r\n                        else:\r\n                            is_first = pl.yield_(0)\r\n                        if bn + n_blocks == bn_this_batch:\r\n                            is_last = pl.yield_(1)\r\n                        else:\r\n                            is_last = pl.yield_(0)\r\n\r\n                        # 5. Online update (VECTOR)\r\n                        out_view_buf = pl.slice(out, [q_tile, head_dim_cfg], [cur_offset, 0])\r\n                        mi_update, li_update, oi, out_view = _up(\r\n                            mi,\r\n                            li,\r\n                            oi_new,\r\n                            mi_update,\r\n                            li_update,\r\n                            oi,\r\n                            out_view_buf,\r\n                            is_first,\r\n                            is_last,\r\n                        )\r\n\r\n            return out\r\n\r\n    return PagedAttentionMultiConfigProgram\r\n\r\n\r\n# ── Golden reference ─────────────────────────────────────────────────────────\r\n\r\n\r\ndef golden_multi_config(tensors: dict, params: dict | None = None) -> None:\r\n    \"\"\"Golden reference for multi-config paged attention.\r\n\r\n    Mirrors the orchestration structure: each group of up to n_unroll blocks\r\n    uses a two-pass softmax (global row_max across all blocks in the group,\r\n    then exp with that max).  Supports partial blocks via valid_len.\r\n\r\n    Shape derivations match the orchestration's pl.tensor.dim() logic.\r\n    Scale is hardcoded to 1.0 to match the orchestration function.\r\n    \"\"\"\r\n    context_lens = tensors[\"context_lens\"]\r\n    query = tensors[\"query\"]\r\n    key_cache_t = tensors[\"key_cache\"]\r\n    value_cache_t = tensors[\"value_cache\"]\r\n    block_table_flat = tensors[\"block_table\"]\r\n\r\n    batch = context_lens.shape[0]\r\n    num_heads = query.shape[0] // batch\r\n    head_dim = query.shape[1]\r\n    block_size = value_cache_t.shape[0] // block_table_flat.shape[0]\r\n    max_num_blocks_per_req = block_table_flat.shape[0] // batch\r\n    scale = 1.0\r\n\r\n    query = query.float().reshape(batch, num_heads, head_dim)\r\n    total_pool_blocks = batch * max_num_blocks_per_req\r\n    key_cache = key_cache_t.float().reshape(total_pool_blocks, block_size, head_dim)\r\n    value_cache = value_cache_t.float().reshape(total_pool_blocks, block_size, head_dim)\r\n    block_table = block_table_flat.reshape(batch, max_num_blocks_per_req)\r\n\r\n    out = torch.zeros((batch, num_heads, head_dim), dtype=torch.float32)\r\n    params = params or {}\r\n    # Default q_tile clamps to num_heads so callers using num_heads < Q_TILE still\r\n    # get a divisible q-row tiling instead of running zero outer iterations.\r\n    q_tile = params.get(\"q_tile\", min(num_heads, Q_TILE))\r\n    n_unroll = params.get(\"n_unroll\", N_UNROLL)\r\n\r\n    def _update(\r\n        oi_a: torch.Tensor | None,\r\n        li_a: torch.Tensor | None,\r\n        mi_a: torch.Tensor | None,\r\n        oi_new: torch.Tensor,\r\n        li_new: torch.Tensor,\r\n        mi_new: torch.Tensor,\r\n    ) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:\r\n        \"\"\"Online softmax update.\"\"\"\r\n        if oi_a is None or li_a is None or mi_a is None:\r\n            return oi_new, li_new, mi_new\r\n        mi_u = torch.maximum(mi_a, mi_new)\r\n        a = torch.exp(mi_a - mi_u)\r\n        b_ = torch.exp(mi_new - mi_u)\r\n        return a * oi_a + b_ * oi_new, a * li_a + b_ * li_new, mi_u\r\n\r\n    for b in range(batch):\r\n        cur_seq = int(context_lens[b].item())\r\n        max_bn_b = (cur_seq + block_size - 1) // block_size\r\n\r\n        for q_idx in range(num_heads // q_tile):\r\n            q_off = q_idx * q_tile\r\n            qi = query[b, q_off : q_off + q_tile, :]\r\n\r\n            oi_acc, li_acc, mi_acc = None, None, None\r\n\r\n            for bn in range(0, max_bn_b, n_unroll):\r\n                n_blocks = min(n_unroll, max_bn_b - bn)\r\n\r\n                # QK matmul for each block in the group\r\n                all_sij = []\r\n                for i in range(n_blocks):\r\n                    bidx = int(block_table[b, bn + i].item())\r\n                    kj = key_cache[bidx]\r\n                    sij = torch.mm(qi, kj.T) * scale\r\n                    # Mask invalid columns on the last block\r\n                    if i == n_blocks - 1:\r\n                        last_valid = min(block_size, cur_seq - (bn + i) * block_size)\r\n                        if last_valid < block_size:\r\n                            sij[:, last_valid:] = float(\"-inf\")\r\n                    all_sij.append(sij)\r\n\r\n                # Two-pass softmax: global row_max across all blocks in group\r\n                global_max = all_sij[0].max(dim=-1, keepdim=True)[0]\r\n                for sij in all_sij[1:]:\r\n                    local_max = sij.max(dim=-1, keepdim=True)[0]\r\n                    global_max = torch.maximum(global_max, local_max)\r\n                global_max = global_max.clamp(min=-1e30)\r\n\r\n                # Exp with global max, sum, PV matmul\r\n                li_group = torch.zeros(q_tile, 1)\r\n                oi_group = torch.zeros(q_tile, head_dim, dtype=torch.float32)\r\n                for i, sij in enumerate(all_sij):\r\n                    pij = torch.exp(sij - global_max).to(torch.bfloat16).to(torch.float32)\r\n                    li_group += pij.sum(dim=-1, keepdim=True)\r\n                    bidx = int(block_table[b, bn + i].item())\r\n                    vj = value_cache[bidx]\r\n                    oi_group += torch.mm(pij, vj)\r\n\r\n                # Online update\r\n                oi_acc, li_acc, mi_acc = _update(oi_acc, li_acc, mi_acc, oi_group, li_group, global_max)\r\n\r\n            assert oi_acc is not None and li_acc is not None, f\"No valid blocks for b={b} q={q_off}\"\r\n            out[b, q_off : q_off + q_tile, :] = oi_acc / li_acc\r\n\r\n    tensors[\"out\"][:] = out.reshape(batch * num_heads, head_dim)\r\n\r\n\r\n# ── TensorSpec builder ───────────────────────────────────────────────────────\r\n\r\n\r\ndef build_tensors_multi_config(\r\n    batch: int,\r\n    num_heads: int,\r\n    head_dim: int,\r\n    block_size: int,\r\n    max_num_blocks_per_req: int,\r\n    context_len: int,\r\n) -> tuple[torch.Tensor, ...]:\r\n    \"\"\"Build torch tensors for multi-config paged attention.\r\n\r\n    Returns:\r\n        (query, key_cache, value_cache, block_table, context_lens, out)\r\n    \"\"\"\r\n    query_rows = batch * num_heads\r\n    key_cache_rows = batch * max_num_blocks_per_req * block_size\r\n    total_cache_blocks = key_cache_rows // block_size\r\n\r\n    context_lens = torch.full((batch,), context_len, dtype=torch.int32)\r\n    block_table = torch.randint(\r\n        0, max(total_cache_blocks, 1), size=(batch, max_num_blocks_per_req), dtype=torch.int32\r\n    ).flatten()\r\n\r\n    query = torch.randn(query_rows, head_dim, dtype=torch.bfloat16)\r\n    key_cache = torch.randn(key_cache_rows, head_dim, dtype=torch.bfloat16)\r\n    value_cache = torch.randn(key_cache_rows, head_dim, dtype=torch.bfloat16)\r\n    out = torch.zeros(query_rows, head_dim, dtype=torch.float32)\r\n\r\n    return (\r\n        query,\r\n        key_cache,\r\n        value_cache,\r\n        block_table,\r\n        context_lens,\r\n        out,\r\n    )\r\n\r\n\r\n# ── Main ─────────────────────────────────────────────────────────────────────\r\n\r\n\r\ndef main():\r\n    parser = argparse.ArgumentParser(description=\"Multi-config paged attention example\")\r\n    parser.add_argument(\r\n        \"--enable-l2-swimlane\",\r\n        action=\"store_true\",\r\n        default=False,\r\n        help=\"Enable on-device runtime profiling and generate swimlane JSON\",\r\n    )\r\n    args = parser.parse_args()\r\n\r\n    batch = 4\r\n    num_heads = 16\r\n    head_dim = HEAD_DIM\r\n    block_size = BLOCK_SIZE\r\n    max_model_len = 2048\r\n    context_len = 1024\r\n    max_num_blocks_per_req = max_model_len // block_size  # 32\r\n\r\n    program = build_paged_attention_multi_config_program(\r\n        head_dim=head_dim,\r\n        block_size=block_size,\r\n    )\r\n\r\n    (\r\n        query,\r\n        key_cache,\r\n        value_cache,\r\n        block_table,\r\n        context_lens,\r\n        out,\r\n    ) = build_tensors_multi_config(\r\n        batch=batch,\r\n        num_heads=num_heads,\r\n        head_dim=head_dim,\r\n        block_size=block_size,\r\n        max_num_blocks_per_req=max_num_blocks_per_req,\r\n        context_len=context_len,\r\n    )\r\n    run(\r\n        program,\r\n        query,\r\n        key_cache,\r\n        value_cache,\r\n        block_table,\r\n        context_lens,\r\n        out,\r\n        config=RunConfig(\r\n            platform=\"a2a3sim\",\r\n            device_id=11,\r\n            strategy=OptimizationStrategy.Default,\r\n            dump_passes=True,\r\n            backend_type=BackendType.Ascend910B,\r\n            compile_profiling=True,\r\n            enable_l2_swimlane=args.enable_l2_swimlane,\r\n        ),\r\n    )\r\n\r\n    # Golden validation\r\n    expected_out = out.clone()\r\n    golden_multi_config(\r\n        {\r\n            \"query\": query,\r\n            \"key_cache\": key_cache,\r\n            \"value_cache\": value_cache,\r\n            \"block_table\": block_table,\r\n            \"context_lens\": context_lens,\r\n            \"out\": expected_out,\r\n        },\r\n    )\r\n    assert torch.allclose(out, expected_out, rtol=2e-2, atol=2e-2), (\r\n        f\"Validation failed: max diff = {(out - expected_out).abs().max().item()}\"\r\n    )\r\n    print(\"PASSED\")\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    main()\r\n","examples/models/08_llama_mini.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"\r\nMinimal complete LLaMA 7B-style language model, using PyPTO language DSL.\r\n\r\nDefault single-head configuration:\r\n  hidden_size = 64  (num_heads=1 × head_dim=64)\r\n  num_heads   = 1\r\n  head_dim    = 64\r\n  head_dim/2  = 32  (for RoPE half-rotation)\r\n  seq_len     = 16\r\n  vocab_size  = 64  (reduced for hardware compatibility)\r\n\r\nArchitecture (same as llama_7b_full.py, simplified for single head):\r\n  hidden [S, D]\r\n    → Decoder Layer: RMSNorm → QKV[S,D] → RoPE → scaled Q@K^T[S,S] → +mask\r\n                    → softmax → @V → dense → residual →\r\n                    → RMSNorm → SwiGLU MLP → residual\r\n    → Final RMSNorm\r\n    → LM Head: [S,D] @ [D,V] → logits [S,V]\r\n\r\nKey simplification vs llama_7b_full.py:\r\n  - Single head: no head splitting (kernel_extract_head) or concat needed\r\n  - All square projection weights are [D, D]\r\n  - Score matrix is [S, S] with single-head\r\n\r\nConstraints:\r\n  - head_dim must be divisible by 16 (K-tiling in kernel_matmul_trans_b)\r\n\r\nUse build_llama_mini_program() to obtain the @pl.program class parameterised\r\nby runtime tensor dimensions.\r\n\r\nReference: LLaMA: Open and Efficient Foundation Language Models (Touvron et al., 2023)\r\n\"\"\"\r\n\r\nimport pypto.language as pl\r\n\r\n\r\ndef build_llama_mini_program(\r\n    seq_len: int = 16,\r\n    head_dim: int = 64,\r\n    vocab_size: int = 64,\r\n):\r\n    \"\"\"Build a minimal single-head LLaMA @pl.program for the given shapes.\r\n\r\n    Returns the decorated program class (not an instance).  The tensor type\r\n    annotations in all kernels and the orchestration function are filled in\r\n    from the arguments so that the PyPTO DSL can resolve static dimensions\r\n    at compile time.\r\n\r\n    Parameters\r\n    ----------\r\n    seq_len:    sequence length (default: 16)\r\n    head_dim:   per-head feature dimension = hidden_size for single head (default: 64)\r\n    vocab_size: vocabulary size for LM head output (default: 64)\r\n\r\n    Note: head_dim must be divisible by 16 (K-tiling constraint).\r\n    \"\"\"\r\n    half_dim = head_dim // 2\r\n    k_tile_width = 16  # hardware TMOV constraint: src.shape == dst.shape\r\n    k1 = k_tile_width  # K-tile column offset 1\r\n    k2 = k_tile_width * 2  # K-tile column offset 2\r\n    k3 = k_tile_width * 3  # K-tile column offset 3\r\n    inv_head_dim = 1.0 / head_dim  # pre-computed Python float for RMSNorm divisor\r\n    attn_scale = head_dim**-0.5  # pre-computed Python float for attention scaling\r\n\r\n    @pl.program\r\n    class LlamaMiniProgram:\r\n        \"\"\"Minimal LLaMA 7B-style model: 1 decoder layer, 1 head, RoPE, LM head.\r\n\r\n        Dimensions: hidden_size=head_dim, num_heads=1, seq_len, vocab_size.\r\n\r\n        Architecture:\r\n          hidden [S,D]\r\n            → Decoder Layer: RMSNorm→QKV→RoPE→scaled-attn→dense→add\r\n                           → RMSNorm→SwiGLU MLP→add\r\n            → Final RMSNorm\r\n            → LM Head: [S,D] @ [D,V] → logits [S,V]\r\n        \"\"\"\r\n\r\n        # =========================================================================\r\n        # InCore kernel: RMSNorm [S, D]\r\n        # Formula: x / sqrt(mean(x^2) + eps), divisor = head_dim\r\n        # =========================================================================\r\n\r\n        @pl.function(type=pl.FunctionType.InCore)\r\n        def kernel_rms_norm(\r\n            self,\r\n            x: pl.Tensor[[seq_len, head_dim], pl.FP32],\r\n            output: pl.Out[pl.Tensor[[seq_len, head_dim], pl.FP32]],\r\n        ) -> pl.Tensor[[seq_len, head_dim], pl.FP32]:\r\n            \"\"\"RMSNorm: x / sqrt(mean(x^2) + eps) across head_dim.\"\"\"\r\n            tile_x = pl.load(x, [0, 0], [seq_len, head_dim], target_memory=pl.MemorySpace.Vec)\r\n\r\n            squared = pl.mul(tile_x, tile_x)\r\n\r\n            tmp = pl.create_tile([seq_len, head_dim], dtype=pl.FP32, target_memory=pl.MemorySpace.Vec)\r\n            mean_sq = pl.row_sum(squared, tmp)\r\n            # [S, 1] is ColMajor; reshape to [1, S] for scalar mul, then back\r\n            mean_sq_T = pl.reshape(mean_sq, [1, seq_len])\r\n            mean_sq_T = pl.mul(mean_sq_T, inv_head_dim)\r\n            mean_sq = pl.reshape(mean_sq_T, [seq_len, 1])\r\n\r\n            mean_sq_T2 = pl.reshape(mean_sq, [1, seq_len])\r\n            rms_T = pl.add(mean_sq_T2, 1e-6)\r\n            rms_T = pl.sqrt(rms_T)\r\n            rms = pl.reshape(rms_T, [seq_len, 1])\r\n\r\n            normalized = pl.row_expand_div(tile_x, rms)\r\n            out = pl.store(normalized, [0, 0], output)\r\n            return out\r\n\r\n        # =========================================================================\r\n        # InCore kernel: matmul [S, D] @ [D, D] → [S, D]\r\n        # Used for QKV projections, dense projection, and MLP projections.\r\n        # =========================================================================\r\n\r\n        @pl.function(type=pl.FunctionType.InCore)\r\n        def kernel_matmul(\r\n            self,\r\n            a: pl.Tensor[[seq_len, head_dim], pl.FP32],\r\n            b: pl.Tensor[[head_dim, head_dim], pl.FP32],\r\n            output: pl.Out[pl.Tensor[[seq_len, head_dim], pl.FP32]],\r\n        ) -> pl.Tensor[[seq_len, head_dim], pl.FP32]:\r\n            \"\"\"[S,D] @ [D,D] → [S,D] matrix multiplication.\"\"\"\r\n            tile_a_l1 = pl.load(a, [0, 0], [seq_len, head_dim], target_memory=pl.MemorySpace.Mat)\r\n            tile_b_l1 = pl.load(b, [0, 0], [head_dim, head_dim], target_memory=pl.MemorySpace.Mat)\r\n            tile_a_l0a = pl.move(tile_a_l1, target_memory=pl.MemorySpace.Left)\r\n            tile_b_l0b = pl.move(tile_b_l1, target_memory=pl.MemorySpace.Right)\r\n            tile_c_l0c = pl.matmul(tile_a_l0a, tile_b_l0b)\r\n            out = pl.store(tile_c_l0c, [0, 0], output)\r\n            return out\r\n\r\n        # =========================================================================\r\n        # InCore kernel: LM head matmul [S, D] @ [D, V] → [S, V]\r\n        # Separate kernel because vocab_size may differ from head_dim.\r\n        # =========================================================================\r\n\r\n        @pl.function(type=pl.FunctionType.InCore)\r\n        def kernel_lm_head(\r\n            self,\r\n            a: pl.Tensor[[seq_len, head_dim], pl.FP32],\r\n            b: pl.Tensor[[head_dim, vocab_size], pl.FP32],\r\n            output: pl.Out[pl.Tensor[[seq_len, vocab_size], pl.FP32]],\r\n        ) -> pl.Tensor[[seq_len, vocab_size], pl.FP32]:\r\n            \"\"\"[S,D] @ [D,V] → [S,V] LM head projection.\"\"\"\r\n            tile_a_l1 = pl.load(a, [0, 0], [seq_len, head_dim], target_memory=pl.MemorySpace.Mat)\r\n            tile_b_l1 = pl.load(b, [0, 0], [head_dim, vocab_size], target_memory=pl.MemorySpace.Mat)\r\n            tile_a_l0a = pl.move(tile_a_l1, target_memory=pl.MemorySpace.Left)\r\n            tile_b_l0b = pl.move(tile_b_l1, target_memory=pl.MemorySpace.Right)\r\n            tile_c_l0c = pl.matmul(tile_a_l0a, tile_b_l0b)\r\n            out = pl.store(tile_c_l0c, [0, 0], output)\r\n            return out\r\n\r\n        # =========================================================================\r\n        # InCore kernel: Q @ K^T via K-tiled matmul [S, D] @ [S, D]^T → [S, S]\r\n        # K-dimension (head_dim) is tiled into k_tile_width=16 blocks (unrolled at\r\n        # compile time) to satisfy the hardware src.shape == dst.shape constraint\r\n        # for TMOV into Right memory.\r\n        # =========================================================================\r\n\r\n        @pl.function(type=pl.FunctionType.InCore)\r\n        def kernel_matmul_trans_b(\r\n            self,\r\n            a: pl.Tensor[[seq_len, head_dim], pl.FP32],\r\n            b: pl.Tensor[[seq_len, head_dim], pl.FP32],\r\n            output: pl.Out[pl.Tensor[[seq_len, seq_len], pl.FP32]],\r\n        ) -> pl.Tensor[[seq_len, seq_len], pl.FP32]:\r\n            \"\"\"[S,D] @ [S,D](DN)^T → [S,S]: Q @ K^T via K-tiled 16-wide blocks.\r\n\r\n            Tiles K-dimension (head_dim) into 4×k_tile_width=16 blocks so each\r\n            TMOV operates on Mat[S,16] → Right[S,16], satisfying the hardware\r\n            src.shape == dst.shape constraint. Requires head_dim == 4*k_tile_width.\r\n            \"\"\"\r\n            # K-tile 0: columns [0 : k_tile_width]\r\n            a0 = pl.load(a, [0, 0], [seq_len, k_tile_width], target_memory=pl.MemorySpace.Mat)\r\n            b0_nat = pl.load(b, [0, 0], [seq_len, k_tile_width], target_memory=pl.MemorySpace.Mat)\r\n            b0 = pl.tile.transpose_view(b0_nat)\r\n            a0_l = pl.move(a0, target_memory=pl.MemorySpace.Left)\r\n            b0_r = pl.move(b0, target_memory=pl.MemorySpace.Right)\r\n            acc = pl.matmul(a0_l, b0_r)\r\n\r\n            # K-tile 1: columns [k1 : k1+k_tile_width]\r\n            a1 = pl.load(a, [0, k1], [seq_len, k_tile_width], target_memory=pl.MemorySpace.Mat)\r\n            b1_nat = pl.load(b, [0, k1], [seq_len, k_tile_width], target_memory=pl.MemorySpace.Mat)\r\n            b1 = pl.tile.transpose_view(b1_nat)\r\n            a1_l = pl.move(a1, target_memory=pl.MemorySpace.Left)\r\n            b1_r = pl.move(b1, target_memory=pl.MemorySpace.Right)\r\n            acc = pl.matmul_acc(acc, a1_l, b1_r)\r\n\r\n            # K-tile 2: columns [k2 : k2+k_tile_width]\r\n            a2 = pl.load(a, [0, k2], [seq_len, k_tile_width], target_memory=pl.MemorySpace.Mat)\r\n            b2_nat = pl.load(b, [0, k2], [seq_len, k_tile_width], target_memory=pl.MemorySpace.Mat)\r\n            b2 = pl.tile.transpose_view(b2_nat)\r\n            a2_l = pl.move(a2, target_memory=pl.MemorySpace.Left)\r\n            b2_r = pl.move(b2, target_memory=pl.MemorySpace.Right)\r\n            acc = pl.matmul_acc(acc, a2_l, b2_r)\r\n\r\n            # K-tile 3: columns [k3 : k3+k_tile_width]\r\n            a3 = pl.load(a, [0, k3], [seq_len, k_tile_width], target_memory=pl.MemorySpace.Mat)\r\n            b3_nat = pl.load(b, [0, k3], [seq_len, k_tile_width], target_memory=pl.MemorySpace.Mat)\r\n            b3 = pl.tile.transpose_view(b3_nat)\r\n            a3_l = pl.move(a3, target_memory=pl.MemorySpace.Left)\r\n            b3_r = pl.move(b3, target_memory=pl.MemorySpace.Right)\r\n            acc = pl.matmul_acc(acc, a3_l, b3_r)\r\n\r\n            out = pl.store(acc, [0, 0], output)\r\n            return out\r\n\r\n        # =========================================================================\r\n        # InCore kernel: probs @ V → [S, D]\r\n        # [S, S] @ [S, D] → [S, D]\r\n        # =========================================================================\r\n\r\n        @pl.function(type=pl.FunctionType.InCore)\r\n        def kernel_matmul_attn(\r\n            self,\r\n            a: pl.Tensor[[seq_len, seq_len], pl.FP32],\r\n            b: pl.Tensor[[seq_len, head_dim], pl.FP32],\r\n            output: pl.Out[pl.Tensor[[seq_len, head_dim], pl.FP32]],\r\n        ) -> pl.Tensor[[seq_len, head_dim], pl.FP32]:\r\n            \"\"\"[S,S] @ [S,D] → [S,D]: probs @ V for single-head attention.\"\"\"\r\n            tile_a_l1 = pl.load(a, [0, 0], [seq_len, seq_len], target_memory=pl.MemorySpace.Mat)\r\n            tile_b_l1 = pl.load(b, [0, 0], [seq_len, head_dim], target_memory=pl.MemorySpace.Mat)\r\n            tile_a_l0a = pl.move(tile_a_l1, target_memory=pl.MemorySpace.Left)\r\n            tile_b_l0b = pl.move(tile_b_l1, target_memory=pl.MemorySpace.Right)\r\n            tile_c_l0c = pl.matmul(tile_a_l0a, tile_b_l0b)\r\n            out = pl.store(tile_c_l0c, [0, 0], output)\r\n            return out\r\n\r\n        # =========================================================================\r\n        # InCore kernel: row-wise softmax [S, S]\r\n        # =========================================================================\r\n\r\n        @pl.function(type=pl.FunctionType.InCore)\r\n        def kernel_softmax(\r\n            self,\r\n            a: pl.Tensor[[seq_len, seq_len], pl.FP32],\r\n            output: pl.Out[pl.Tensor[[seq_len, seq_len], pl.FP32]],\r\n        ) -> pl.Tensor[[seq_len, seq_len], pl.FP32]:\r\n            \"\"\"Row-wise numerically stable softmax.\"\"\"\r\n            tile_a = pl.load(a, [0, 0], [seq_len, seq_len])\r\n\r\n            max_tmp = pl.create_tile([seq_len, seq_len], dtype=pl.FP32, target_memory=pl.MemorySpace.Vec)\r\n            row_max = pl.row_max(tile_a, max_tmp)\r\n\r\n            shifted = pl.row_expand_sub(tile_a, row_max)\r\n            exp_shifted = pl.exp(shifted)\r\n\r\n            sum_tmp = pl.create_tile([seq_len, seq_len], dtype=pl.FP32, target_memory=pl.MemorySpace.Vec)\r\n            row_sum = pl.row_sum(exp_shifted, sum_tmp)\r\n            result = pl.row_expand_div(exp_shifted, row_sum)\r\n\r\n            out = pl.store(result, [0, 0], output)\r\n            return out\r\n\r\n        # =========================================================================\r\n        # InCore kernel: scale attention scores [S, S] × (1/sqrt(head_dim))\r\n        # =========================================================================\r\n\r\n        @pl.function(type=pl.FunctionType.InCore)\r\n        def kernel_scale_scores(\r\n            self,\r\n            scores: pl.Tensor[[seq_len, seq_len], pl.FP32],\r\n            output: pl.Out[pl.Tensor[[seq_len, seq_len], pl.FP32]],\r\n        ) -> pl.Tensor[[seq_len, seq_len], pl.FP32]:\r\n            \"\"\"Scale attention scores by 1/sqrt(head_dim).\"\"\"\r\n            tile = pl.load(scores, [0, 0], [seq_len, seq_len])\r\n            scaled = pl.mul(tile, attn_scale)\r\n            out = pl.store(scaled, [0, 0], output)\r\n            return out\r\n\r\n        # =========================================================================\r\n        # InCore kernel: element-wise add [S, S]\r\n        # Used for applying causal mask to attention scores.\r\n        # =========================================================================\r\n\r\n        @pl.function(type=pl.FunctionType.InCore)\r\n        def kernel_add_scores(\r\n            self,\r\n            a: pl.Tensor[[seq_len, seq_len], pl.FP32],\r\n            b: pl.Tensor[[seq_len, seq_len], pl.FP32],\r\n            output: pl.Out[pl.Tensor[[seq_len, seq_len], pl.FP32]],\r\n        ) -> pl.Tensor[[seq_len, seq_len], pl.FP32]:\r\n            \"\"\"Element-wise addition [S,S]: output = a + b.\"\"\"\r\n            tile_a = pl.load(a, [0, 0], [seq_len, seq_len])\r\n            tile_b = pl.load(b, [0, 0], [seq_len, seq_len])\r\n            result = pl.add(tile_a, tile_b)\r\n            out = pl.store(result, [0, 0], output)\r\n            return out\r\n\r\n        # =========================================================================\r\n        # InCore kernel: element-wise add [S, D]\r\n        # Used for residual connections.\r\n        # =========================================================================\r\n\r\n        @pl.function(type=pl.FunctionType.InCore)\r\n        def kernel_add(\r\n            self,\r\n            a: pl.Tensor[[seq_len, head_dim], pl.FP32],\r\n            b: pl.Tensor[[seq_len, head_dim], pl.FP32],\r\n            output: pl.Out[pl.Tensor[[seq_len, head_dim], pl.FP32]],\r\n        ) -> pl.Tensor[[seq_len, head_dim], pl.FP32]:\r\n            \"\"\"Element-wise addition [S,D]: output = a + b.\"\"\"\r\n            tile_a = pl.load(a, [0, 0], [seq_len, head_dim], target_memory=pl.MemorySpace.Vec)\r\n            tile_b = pl.load(b, [0, 0], [seq_len, head_dim], target_memory=pl.MemorySpace.Vec)\r\n            result = pl.add(tile_a, tile_b)\r\n            out = pl.store(result, [0, 0], output)\r\n            return out\r\n\r\n        # =========================================================================\r\n        # InCore kernel: RoPE [S, D] using [S, D/2] cos/sin tables\r\n        # Rotate-half pattern: x_left = x[:, :D/2], x_right = x[:, D/2:]\r\n        # =========================================================================\r\n\r\n        @pl.function(type=pl.FunctionType.InCore)\r\n        def kernel_rope(\r\n            self,\r\n            x: pl.Tensor[[seq_len, head_dim], pl.FP32],\r\n            cos_emb: pl.Tensor[[seq_len, half_dim], pl.FP32],\r\n            sin_emb: pl.Tensor[[seq_len, half_dim], pl.FP32],\r\n            output: pl.Out[pl.Tensor[[seq_len, head_dim], pl.FP32]],\r\n        ) -> pl.Tensor[[seq_len, head_dim], pl.FP32]:\r\n            \"\"\"Apply Rotary Position Embedding to a [S, head_dim] tensor.\r\n\r\n            Rotate-half RoPE:\r\n              x_left  = x[:, :half_dim]   rotated_left  = x_left * cos - x_right * sin\r\n              x_right = x[:, half_dim:]   rotated_right = x_right * cos + x_left * sin\r\n            \"\"\"\r\n            x_left = pl.load(x, [0, 0], [seq_len, half_dim])\r\n            x_right = pl.load(x, [0, half_dim], [seq_len, half_dim])\r\n            cos_tile = pl.load(cos_emb, [0, 0], [seq_len, half_dim])\r\n            sin_tile = pl.load(sin_emb, [0, 0], [seq_len, half_dim])\r\n\r\n            left_cos = pl.mul(x_left, cos_tile)\r\n            right_sin = pl.mul(x_right, sin_tile)\r\n            rotated_left = pl.sub(left_cos, right_sin)\r\n\r\n            right_cos = pl.mul(x_right, cos_tile)\r\n            left_sin = pl.mul(x_left, sin_tile)\r\n            rotated_right = pl.add(right_cos, left_sin)\r\n\r\n            out_left = pl.store(rotated_left, [0, 0], output)\r\n            out = pl.store(rotated_right, [0, half_dim], out_left)\r\n            return out\r\n\r\n        # =========================================================================\r\n        # InCore kernel: SwiGLU [S, D]\r\n        # Formula: SiLU(gate) * up = gate * sigmoid(gate) * up\r\n        # =========================================================================\r\n\r\n        @pl.function(type=pl.FunctionType.InCore)\r\n        def kernel_swiglu(\r\n            self,\r\n            gate: pl.Tensor[[seq_len, head_dim], pl.FP32],\r\n            up: pl.Tensor[[seq_len, head_dim], pl.FP32],\r\n            output: pl.Out[pl.Tensor[[seq_len, head_dim], pl.FP32]],\r\n        ) -> pl.Tensor[[seq_len, head_dim], pl.FP32]:\r\n            \"\"\"SwiGLU: SiLU(gate) * up = gate * sigmoid(gate) * up.\"\"\"\r\n            tile_gate = pl.load(gate, [0, 0], [seq_len, head_dim], target_memory=pl.MemorySpace.Vec)\r\n            tile_up = pl.load(up, [0, 0], [seq_len, head_dim], target_memory=pl.MemorySpace.Vec)\r\n\r\n            gate_neg = pl.mul(tile_gate, -1.0)\r\n            exp_neg = pl.exp(gate_neg)\r\n            denom = pl.add(exp_neg, 1.0)\r\n            sigmoid = pl.recip(denom)\r\n            swish = pl.mul(tile_gate, sigmoid)\r\n            result = pl.mul(swish, tile_up)\r\n\r\n            out = pl.store(result, [0, 0], output)\r\n            return out\r\n\r\n        # =========================================================================\r\n        # Top-level orchestration: minimal 1-layer, 1-head LLaMA 7B model\r\n        # =========================================================================\r\n\r\n        @pl.function(type=pl.FunctionType.Orchestration)\r\n        def llama_mini_orch(  # noqa: PLR0913\r\n            self,\r\n            # Input hidden states\r\n            hidden: pl.Tensor[[seq_len, head_dim], pl.FP32],\r\n            # Causal attention mask\r\n            causal_mask: pl.Tensor[[seq_len, seq_len], pl.FP32],\r\n            # RoPE embeddings: positions × head_dim/2\r\n            cos_emb: pl.Tensor[[seq_len, half_dim], pl.FP32],\r\n            sin_emb: pl.Tensor[[seq_len, half_dim], pl.FP32],\r\n            # QKV and projection weights [D, D]\r\n            wq: pl.Tensor[[head_dim, head_dim], pl.FP32],\r\n            wk: pl.Tensor[[head_dim, head_dim], pl.FP32],\r\n            wv: pl.Tensor[[head_dim, head_dim], pl.FP32],\r\n            w_dense: pl.Tensor[[head_dim, head_dim], pl.FP32],\r\n            # MLP weights [D, D]\r\n            w_gate: pl.Tensor[[head_dim, head_dim], pl.FP32],\r\n            w_up: pl.Tensor[[head_dim, head_dim], pl.FP32],\r\n            w_down: pl.Tensor[[head_dim, head_dim], pl.FP32],\r\n            # LM head weight [D, V]\r\n            w_lm: pl.Tensor[[head_dim, vocab_size], pl.FP32],\r\n            # Output\r\n            logits: pl.Out[pl.Tensor[[seq_len, vocab_size], pl.FP32]],\r\n        ) -> pl.Tensor[[seq_len, vocab_size], pl.FP32]:\r\n            \"\"\"Minimal LLaMA 7B-style model forward pass (1 layer, 1 head).\r\n\r\n            Pipeline:\r\n              hidden [S,D]\r\n                → Decoder Layer:\r\n                    RMSNorm → QKV[S,D] → RoPE →\r\n                    scaled Q@K^T[S,S] → +mask → softmax → @V[S,D] →\r\n                    dense → residual →\r\n                    RMSNorm → SwiGLU MLP → residual\r\n                → Final RMSNorm\r\n                → LM Head: [S,D] @ [D,V] → logits [S,V]\r\n            \"\"\"\r\n            # ===== Decoder Layer =====\r\n\r\n            # Pre-attention RMSNorm\r\n            normed = pl.create_tensor([seq_len, head_dim], dtype=pl.FP32)\r\n            normed = self.kernel_rms_norm(hidden, normed)\r\n\r\n            # QKV projections: [S,D] @ [D,D] → [S,D] each\r\n            q = pl.create_tensor([seq_len, head_dim], dtype=pl.FP32)\r\n            q = self.kernel_matmul(normed, wq, q)\r\n            k = pl.create_tensor([seq_len, head_dim], dtype=pl.FP32)\r\n            k = self.kernel_matmul(normed, wk, k)\r\n            v = pl.create_tensor([seq_len, head_dim], dtype=pl.FP32)\r\n            v = self.kernel_matmul(normed, wv, v)\r\n\r\n            # Apply RoPE to Q and K\r\n            q_rot = pl.create_tensor([seq_len, head_dim], dtype=pl.FP32)\r\n            q_rot = self.kernel_rope(q, cos_emb, sin_emb, q_rot)\r\n            k_rot_buf = pl.create_tensor([seq_len, head_dim], dtype=pl.FP32)\r\n            k_rot = self.kernel_rope(k, cos_emb, sin_emb, k_rot_buf)\r\n\r\n            # Scaled causal dot-product attention\r\n            scores = pl.create_tensor([seq_len, seq_len], dtype=pl.FP32)\r\n            scores = self.kernel_matmul_trans_b(q_rot, k_rot, scores)\r\n            scaled = pl.create_tensor([seq_len, seq_len], dtype=pl.FP32)\r\n            scaled = self.kernel_scale_scores(scores, scaled)\r\n            masked = pl.create_tensor([seq_len, seq_len], dtype=pl.FP32)\r\n            masked = self.kernel_add_scores(scaled, causal_mask, masked)\r\n            probs = pl.create_tensor([seq_len, seq_len], dtype=pl.FP32)\r\n            probs = self.kernel_softmax(masked, probs)\r\n            attn_out = pl.create_tensor([seq_len, head_dim], dtype=pl.FP32)\r\n            attn_out = self.kernel_matmul_attn(probs, v, attn_out)\r\n\r\n            # Dense projection + first residual\r\n            dense_out = pl.create_tensor([seq_len, head_dim], dtype=pl.FP32)\r\n            dense_out = self.kernel_matmul(attn_out, w_dense, dense_out)\r\n            attn_res = pl.create_tensor([seq_len, head_dim], dtype=pl.FP32)\r\n            attn_res = self.kernel_add(hidden, dense_out, attn_res)\r\n\r\n            # Pre-MLP RMSNorm\r\n            normed2 = pl.create_tensor([seq_len, head_dim], dtype=pl.FP32)\r\n            normed2 = self.kernel_rms_norm(attn_res, normed2)\r\n\r\n            # SwiGLU MLP\r\n            gate = pl.create_tensor([seq_len, head_dim], dtype=pl.FP32)\r\n            gate = self.kernel_matmul(normed2, w_gate, gate)\r\n            up = pl.create_tensor([seq_len, head_dim], dtype=pl.FP32)\r\n            up = self.kernel_matmul(normed2, w_up, up)\r\n            swish_up = pl.create_tensor([seq_len, head_dim], dtype=pl.FP32)\r\n            swish_up = self.kernel_swiglu(gate, up, swish_up)\r\n            mlp_out = pl.create_tensor([seq_len, head_dim], dtype=pl.FP32)\r\n            mlp_out = self.kernel_matmul(swish_up, w_down, mlp_out)\r\n\r\n            # Second residual → h1\r\n            h1 = pl.create_tensor([seq_len, head_dim], dtype=pl.FP32)\r\n            h1 = self.kernel_add(attn_res, mlp_out, h1)\r\n\r\n            # ===== Final RMSNorm =====\r\n            h_normed = pl.create_tensor([seq_len, head_dim], dtype=pl.FP32)\r\n            h_normed = self.kernel_rms_norm(h1, h_normed)\r\n\r\n            # ===== LM Head: [S,D] @ [D,V] → logits [S,V] =====\r\n            logits = self.kernel_lm_head(h_normed, w_lm, logits)\r\n\r\n            return logits\r\n\r\n    return LlamaMiniProgram\r\n","examples/models/09_paged_attention_spmd.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\"\"\"\r\nSPMD Paged Attention Example\r\n\r\nDemonstrates multi-block SPMD dispatch of paged attention using pl.spmd().\r\nEach SPMD block processes a subset of batch items via a stride loop,\r\nparallelizing the batch dimension across hardware blocks.\r\n\r\nArchitecture (per KV-block iteration, 4 sequential SPMD submissions):\r\n  1. QK Matmul (SPMD):        sij = SpmdQkMatmul(...)           [CUBE]\r\n  2. Softmax Prepare (SPMD):   pij, mij, lij = SpmdSoftmaxPrepare(...)  [VECTOR]\r\n  3. PV Matmul (SPMD):         oi_new = SpmdPvMatmul(...)        [CUBE]\r\n  4. Online Update (SPMD):     mi, li, oi = SpmdOnlineUpdate(...) [VECTOR]\r\n\r\nAfter the KV-block loop, a final SPMD normalization (SpmdNormalize) divides\r\nthe accumulated output by the softmax denominator and scatters to the output tensor.\r\n\r\nWork partitioning: each HW block processes batch items in a stride loop where\r\n  b starts at block_idx and increments by block_num (core_num=4).\r\n\r\nOrchestration structure:\r\n  - Outer loop over q_tile groups (tiling the num_heads dimension)\r\n  - Inner loop over KV blocks (up to max_bn, the maximum number of\r\n    KV blocks across all requests, clamped by active_block_num)\r\n  - Each kernel stage is dispatched via pl.spmd(core_num=4)\r\n  - SpmdSoftmaxPrepare and SpmdOnlineUpdate are additionally wrapped\r\n    in pl.cluster() for cooperative execution\r\n\r\nTensor layout:\r\n  query:       [batch * num_heads, head_dim]                    BF16\r\n  key_cache:   [batch * max_num_blocks_per_req * block_size, head_dim]  BF16\r\n  value_cache: [batch * max_num_blocks_per_req * block_size, head_dim]  BF16\r\n  block_table: [batch * max_num_blocks_per_req]                 INT32\r\n  context_lens:[batch]                                          INT32\r\n  scale:       [1]                                              FP32\r\n  out:         [batch * num_heads, head_dim]                    FP32\r\n  config:      [7]  (batch, num_heads, kv_head_num, head_dim,\r\n                     block_size, block_num_capacity, active_block_num)  INT64\r\n\"\"\"\r\n\r\nimport argparse\r\nimport os\r\nfrom collections.abc import Sequence\r\n\r\nimport pypto.language as pl\r\nimport torch\r\nfrom pypto.backend import BackendType\r\nfrom pypto.ir.pass_manager import OptimizationStrategy\r\nfrom pypto.runtime import RunConfig, run\r\n\r\n\r\ndef _get_default_device_id() -> int:\r\n    \"\"\"Return the runtime device id from env, defaulting to 0.\"\"\"\r\n    for env_name in (\"TILE_FWK_DEVICE_ID\", \"ASCEND_DEVICE_ID\", \"ACL_DEVICE_ID\", \"DEVICE_ID\"):\r\n        env_value = os.environ.get(env_name)\r\n        if env_value is None:\r\n            continue\r\n        try:\r\n            return int(env_value)\r\n        except (TypeError, ValueError):\r\n            continue\r\n    return 0\r\n\r\n\r\ndef build_paged_attention_spmd_program(\r\n    batch: int,\r\n    num_heads: int,\r\n    head_dim: int,\r\n    block_size: int,\r\n    max_num_blocks_per_req: int,\r\n    q_tile: int = 16,\r\n):\r\n    \"\"\"Build a parameterised SPMD paged-attention @pl.program.\r\n\r\n    Returns the decorated program class (not an instance). Uses pl.spmd()\r\n    to dispatch each kernel stage across multiple hardware blocks, with\r\n    batch-parallel stride partitioning inside InCore kernels.\r\n\r\n    Parameters\r\n    ----------\r\n    batch:                  number of requests in the batch\r\n    num_heads:              number of query heads\r\n    head_dim:               per-head feature dimension\r\n    block_size:             KV-cache block size (rows per physical block)\r\n    max_num_blocks_per_req: maximum number of KV blocks per request\r\n    q_tile:                 query-head tile size used by the InCore kernels\r\n    \"\"\"\r\n    query_rows = batch * num_heads\r\n    key_cache_rows = batch * max_num_blocks_per_req * block_size\r\n    out_rows = batch * num_heads\r\n    block_table_flat_size = batch * max_num_blocks_per_req\r\n    batch_q_tile = batch * q_tile\r\n\r\n    @pl.program\r\n    class SpmdPagedAttentionProgram:\r\n        \"\"\"SPMD paged attention with batch-parallel stride partitioning.\"\"\"\r\n\r\n        # ── CUBE kernel: QK matmul ─────────────────────────────────────\r\n        # For each batch item b (stride-partitioned across HW blocks):\r\n        #   1. Compute the valid KV length for this block index\r\n        #   2. Look up the physical block from block_table\r\n        #   3. Load query tile [q_tile, head_dim] and key tile [block_size, head_dim]\r\n        #   4. Compute sij = Q @ K^T and store to sij_batch at batch offset\r\n        @pl.function(type=pl.FunctionType.InCore)\r\n        def SpmdQkMatmul(  # noqa: PLR0913\r\n            self,\r\n            query: pl.Tensor[[query_rows, head_dim], pl.BF16],\r\n            key_cache: pl.Tensor[[key_cache_rows, head_dim], pl.BF16],\r\n            sij_batch: pl.Out[pl.Tensor[[batch_q_tile, block_size], pl.FP32]],\r\n            block_table: pl.Tensor[[block_table_flat_size], pl.INT32],\r\n            context_lens: pl.Tensor[[batch], pl.INT32],\r\n            batch_count: pl.Scalar[pl.INDEX],\r\n            block_idx_kv: pl.Scalar[pl.INDEX],\r\n            q_offset: pl.Scalar[pl.INDEX],\r\n            block_num: pl.Scalar[pl.INDEX],\r\n            block_size_param: pl.Scalar[pl.INDEX],\r\n            num_heads_param: pl.Scalar[pl.INDEX],\r\n        ) -> pl.Tensor[[batch_q_tile, block_size], pl.FP32]:\r\n            \"\"\"QK matmul with SPMD stride partitioning over batch (CUBE).\"\"\"\r\n            spmd_idx = pl.tile.get_block_idx()\r\n            spmd_block_num = pl.tile.get_block_num()\r\n            for b in pl.range(spmd_idx, batch_count, spmd_block_num):\r\n                qi_row = b * num_heads_param + q_offset\r\n                cur_seq = pl.tensor.read(context_lens, [b])\r\n                start = block_idx_kv * block_size_param\r\n                remaining = cur_seq - start\r\n                valid_len = pl.max(pl.min(remaining, block_size_param), 0)\r\n\r\n                if valid_len > 0:\r\n                    phys_block_raw: pl.Scalar[pl.INT32] = pl.read(block_table, b * block_num + block_idx_kv)\r\n                    phys_block_idx: pl.Scalar[pl.INDEX] = pl.cast(phys_block_raw, pl.INDEX)\r\n                    kj_row = phys_block_idx * block_size_param\r\n\r\n                    qi_l1 = pl.load(\r\n                        query,\r\n                        [qi_row, 0],\r\n                        [q_tile, head_dim],\r\n                        target_memory=pl.MemorySpace.Mat,\r\n                    )\r\n                    kj_nat = pl.load(\r\n                        key_cache,\r\n                        [kj_row, 0],\r\n                        [block_size, head_dim],\r\n                        target_memory=pl.MemorySpace.Mat,\r\n                    )\r\n                    kj_l1 = pl.tile.transpose_view(kj_nat)\r\n                    qi_l0a = pl.move(qi_l1, target_memory=pl.MemorySpace.Left)\r\n                    kj_l0b = pl.move(kj_l1, target_memory=pl.MemorySpace.Right)\r\n                    sij_l0c = pl.matmul(qi_l0a, kj_l0b)\r\n                    sij_batch = pl.store(sij_l0c, [b * q_tile, 0], sij_batch)\r\n            return sij_batch\r\n\r\n        # ── VECTOR kernel: softmax prepare ─────────────────────────────\r\n        # For each batch item b (stride-partitioned across HW blocks):\r\n        #   If valid_len == 0: produce zero pij, -inf mij, zero lij\r\n        #   Else:\r\n        #     1. Load sij scores, pad invalid positions with min value\r\n        #     2. Scale scores by scale_value\r\n        #     3. Compute row-wise max (mij) and center scores\r\n        #     4. Compute exp(sij - mij) -> pij, and row-wise sum -> lij\r\n        @pl.function(type=pl.FunctionType.InCore)\r\n        def SpmdSoftmaxPrepare(\r\n            self,\r\n            sij_batch: pl.Tensor[[batch_q_tile, block_size], pl.FP32],\r\n            pij_batch: pl.Out[pl.Tensor[[batch_q_tile, block_size], pl.BF16]],\r\n            mij_batch: pl.Out[pl.Tensor[[batch_q_tile, 1], pl.FP32]],\r\n            lij_batch: pl.Out[pl.Tensor[[batch_q_tile, 1], pl.FP32]],\r\n            scale_value: pl.Scalar[pl.FP32],\r\n            context_lens: pl.Tensor[[batch], pl.INT32],\r\n            batch_count: pl.Scalar[pl.INDEX],\r\n            block_idx_kv: pl.Scalar[pl.INDEX],\r\n            block_size_param: pl.Scalar[pl.INDEX],\r\n        ) -> tuple[\r\n            pl.Tensor[[batch_q_tile, block_size], pl.BF16],\r\n            pl.Tensor[[batch_q_tile, 1], pl.FP32],\r\n            pl.Tensor[[batch_q_tile, 1], pl.FP32],\r\n        ]:\r\n            \"\"\"Softmax prepare with SPMD stride over batch (VECTOR).\"\"\"\r\n            spmd_idx = pl.tile.get_block_idx()\r\n            spmd_block_num = pl.tile.get_block_num()\r\n            for b in pl.range(spmd_idx, batch_count, spmd_block_num):\r\n                cur_seq = pl.tensor.read(context_lens, [b])\r\n                start = block_idx_kv * block_size_param\r\n                remaining = cur_seq - start\r\n                valid_len = pl.max(pl.min(remaining, block_size_param), 0)\r\n\r\n                if valid_len == 0:\r\n                    zero_pij_f32_tile = pl.tile.full([q_tile, block_size], dtype=pl.FP32, value=0.0)\r\n                    zero_pij_tile = pl.cast(zero_pij_f32_tile, target_type=pl.BF16)\r\n                    zero_tmp_tile = pl.create_tile(\r\n                        [q_tile, block_size],\r\n                        dtype=pl.FP32,\r\n                        target_memory=pl.MemorySpace.Vec,\r\n                    )\r\n                    zero_li_tile = pl.row_sum(zero_pij_f32_tile, zero_tmp_tile)\r\n\r\n                    neg_inf_scores_tile = pl.tile.full([q_tile, block_size], dtype=pl.FP32, value=-1e30)\r\n                    neg_inf_tmp_tile = pl.create_tile(\r\n                        [q_tile, block_size],\r\n                        dtype=pl.FP32,\r\n                        target_memory=pl.MemorySpace.Vec,\r\n                    )\r\n                    neg_inf_mi_tile = pl.row_max(neg_inf_scores_tile, neg_inf_tmp_tile)\r\n                    pij_batch = pl.store(zero_pij_tile, [b * q_tile, 0], pij_batch, [q_tile, block_size])\r\n                    mij_batch = pl.store(neg_inf_mi_tile, [b * q_tile, 0], mij_batch, [q_tile, 1])\r\n                    lij_batch = pl.store(zero_li_tile, [b * q_tile, 0], lij_batch, [q_tile, 1])\r\n                else:\r\n                    s_tile = pl.load(\r\n                        sij_batch,\r\n                        [b * q_tile, 0],\r\n                        [q_tile, block_size],\r\n                        target_memory=pl.MemorySpace.Vec,\r\n                        valid_shapes=[q_tile, valid_len],\r\n                    )\r\n                    s_padded = pl.tile.fillpad(s_tile, pad_value=pl.PadValue.min)\r\n                    scaled = pl.mul(s_padded, scale_value)\r\n                    tmp_tile = pl.create_tile(\r\n                        [q_tile, block_size],\r\n                        dtype=pl.FP32,\r\n                        target_memory=pl.MemorySpace.Vec,\r\n                    )\r\n                    mi_tile = pl.row_max(scaled, tmp_tile)\r\n                    sij_centered = pl.row_expand_sub(scaled, mi_tile)\r\n                    exp_tile = pl.exp(sij_centered)\r\n                    pij_tile_f16 = pl.cast(exp_tile, target_type=pl.BF16)\r\n                    pij_tile = pl.cast(pij_tile_f16, target_type=pl.FP32)\r\n                    li_tile = pl.row_sum(pij_tile, tmp_tile)\r\n                    pij_batch = pl.store(pij_tile_f16, [b * q_tile, 0], pij_batch, [q_tile, block_size])\r\n                    mij_batch = pl.store(mi_tile, [b * q_tile, 0], mij_batch, [q_tile, 1])\r\n                    lij_batch = pl.store(li_tile, [b * q_tile, 0], lij_batch, [q_tile, 1])\r\n            return pij_batch, mij_batch, lij_batch\r\n\r\n        # ── CUBE kernel: PV matmul ─────────────────────────────────────\r\n        # For each batch item b (stride-partitioned across HW blocks):\r\n        #   1. Look up physical block from block_table (same logic as QK)\r\n        #   2. Load pij tile [q_tile, block_size] and value tile [block_size, head_dim]\r\n        #   3. Compute oi_new = pij @ V and store to oi_new_batch\r\n        @pl.function(type=pl.FunctionType.InCore)\r\n        def SpmdPvMatmul(\r\n            self,\r\n            pij_batch: pl.Tensor[[batch_q_tile, block_size], pl.BF16],\r\n            value_cache: pl.Tensor[[key_cache_rows, head_dim], pl.BF16],\r\n            oi_new_batch: pl.Out[pl.Tensor[[batch_q_tile, head_dim], pl.FP32]],\r\n            block_table: pl.Tensor[[block_table_flat_size], pl.INT32],\r\n            context_lens: pl.Tensor[[batch], pl.INT32],\r\n            batch_count: pl.Scalar[pl.INDEX],\r\n            block_idx_kv: pl.Scalar[pl.INDEX],\r\n            block_num: pl.Scalar[pl.INDEX],\r\n            block_size_param: pl.Scalar[pl.INDEX],\r\n        ) -> pl.Tensor[[batch_q_tile, head_dim], pl.FP32]:\r\n            \"\"\"PV matmul with SPMD stride partitioning over batch (CUBE).\"\"\"\r\n            spmd_idx = pl.tile.get_block_idx()\r\n            spmd_block_num = pl.tile.get_block_num()\r\n            for b in pl.range(spmd_idx, batch_count, spmd_block_num):\r\n                cur_seq = pl.tensor.read(context_lens, [b])\r\n                start = block_idx_kv * block_size_param\r\n                remaining = cur_seq - start\r\n                valid_len = pl.max(pl.min(remaining, block_size_param), 0)\r\n\r\n                if valid_len > 0:\r\n                    phys_block_raw: pl.Scalar[pl.INT32] = pl.read(block_table, b * block_num + block_idx_kv)\r\n                    phys_block_idx: pl.Scalar[pl.INDEX] = pl.cast(phys_block_raw, pl.INDEX)\r\n                    vj_row = phys_block_idx * block_size_param\r\n\r\n                    pij_l1 = pl.load(\r\n                        pij_batch,\r\n                        [b * q_tile, 0],\r\n                        [q_tile, block_size],\r\n                        target_memory=pl.MemorySpace.Mat,\r\n                    )\r\n                    vj_l1 = pl.load(\r\n                        value_cache,\r\n                        [vj_row, 0],\r\n                        [block_size, head_dim],\r\n                        target_memory=pl.MemorySpace.Mat,\r\n                    )\r\n                    pij_l0a = pl.move(pij_l1, target_memory=pl.MemorySpace.Left)\r\n                    vj_l0b = pl.move(vj_l1, target_memory=pl.MemorySpace.Right)\r\n                    oi_l0c = pl.matmul(pij_l0a, vj_l0b)\r\n                    oi_new_batch = pl.store(oi_l0c, [b * q_tile, 0], oi_new_batch)\r\n            return oi_new_batch\r\n\r\n        # ── VECTOR kernel: online softmax update (in-place accumulators) ─\r\n        # For each batch item b (stride-partitioned across HW blocks):\r\n        #   If is_first (first KV block): directly copy mij, lij, oi_new\r\n        #   Else: apply online softmax update:\r\n        #     mi_new = max(mi, mij)\r\n        #     alpha = exp(mi - mi_new), beta = exp(mij - mi_new)\r\n        #     li = alpha * li + beta * lij\r\n        #     oi = alpha * oi + beta * oi_new\r\n        @pl.function(type=pl.FunctionType.InCore)\r\n        def SpmdOnlineUpdate(  # noqa: PLR0913\r\n            self,\r\n            mij_batch: pl.Tensor[[batch_q_tile, 1], pl.FP32],\r\n            lij_batch: pl.Tensor[[batch_q_tile, 1], pl.FP32],\r\n            oi_new_batch: pl.Tensor[[batch_q_tile, head_dim], pl.FP32],\r\n            mi_batch: pl.InOut[pl.Tensor[[batch_q_tile, 1], pl.FP32]],\r\n            li_batch: pl.InOut[pl.Tensor[[batch_q_tile, 1], pl.FP32]],\r\n            oi_batch: pl.InOut[pl.Tensor[[batch_q_tile, head_dim], pl.FP32]],\r\n            is_first: pl.Scalar[pl.INDEX],\r\n            batch_count: pl.Scalar[pl.INDEX],\r\n        ) -> tuple[\r\n            pl.Tensor[[batch_q_tile, 1], pl.FP32],\r\n            pl.Tensor[[batch_q_tile, 1], pl.FP32],\r\n            pl.Tensor[[batch_q_tile, head_dim], pl.FP32],\r\n        ]:\r\n            \"\"\"Online softmax accumulator update (VECTOR).\"\"\"\r\n            spmd_idx = pl.tile.get_block_idx()\r\n            spmd_block_num = pl.tile.get_block_num()\r\n            if is_first != 0:\r\n                for b in pl.range(spmd_idx, batch_count, spmd_block_num):\r\n                    mij_tile = pl.load(\r\n                        mij_batch,\r\n                        [b * q_tile, 0],\r\n                        [q_tile, 1],\r\n                        target_memory=pl.MemorySpace.Vec,\r\n                    )\r\n                    lij_tile = pl.load(\r\n                        lij_batch,\r\n                        [b * q_tile, 0],\r\n                        [q_tile, 1],\r\n                        target_memory=pl.MemorySpace.Vec,\r\n                    )\r\n                    oi_new_tile = pl.load(\r\n                        oi_new_batch,\r\n                        [b * q_tile, 0],\r\n                        [q_tile, head_dim],\r\n                        target_memory=pl.MemorySpace.Vec,\r\n                    )\r\n                    mi_batch = pl.store(mij_tile, [b * q_tile, 0], mi_batch, [q_tile, 1])\r\n                    li_batch = pl.store(lij_tile, [b * q_tile, 0], li_batch, [q_tile, 1])\r\n                    oi_batch = pl.store(oi_new_tile, [b * q_tile, 0], oi_batch, [q_tile, head_dim])\r\n            else:\r\n                for b in pl.range(spmd_idx, batch_count, spmd_block_num):\r\n                    mij_tile = pl.load(\r\n                        mij_batch,\r\n                        [b * q_tile, 0],\r\n                        [q_tile, 1],\r\n                        target_memory=pl.MemorySpace.Vec,\r\n                    )\r\n                    lij_tile = pl.load(\r\n                        lij_batch,\r\n                        [b * q_tile, 0],\r\n                        [q_tile, 1],\r\n                        target_memory=pl.MemorySpace.Vec,\r\n                    )\r\n                    oi_new_tile = pl.load(\r\n                        oi_new_batch,\r\n                        [b * q_tile, 0],\r\n                        [q_tile, head_dim],\r\n                        target_memory=pl.MemorySpace.Vec,\r\n                    )\r\n                    mi_tile = pl.load(\r\n                        mi_batch,\r\n                        [b * q_tile, 0],\r\n                        [q_tile, 1],\r\n                        target_memory=pl.MemorySpace.Vec,\r\n                    )\r\n                    li_tile = pl.load(\r\n                        li_batch,\r\n                        [b * q_tile, 0],\r\n                        [q_tile, 1],\r\n                        target_memory=pl.MemorySpace.Vec,\r\n                    )\r\n                    oi_tile = pl.load(\r\n                        oi_batch,\r\n                        [b * q_tile, 0],\r\n                        [q_tile, head_dim],\r\n                        target_memory=pl.MemorySpace.Vec,\r\n                    )\r\n\r\n                    mi_tile_nd = pl.reshape(mi_tile, [1, q_tile])\r\n                    mij_tile_nd = pl.reshape(mij_tile, [1, q_tile])\r\n                    li_tile_nd = pl.reshape(li_tile, [1, q_tile])\r\n                    lij_tile_nd = pl.reshape(lij_tile, [1, q_tile])\r\n\r\n                    mi_new = pl.maximum(mi_tile_nd, mij_tile_nd)\r\n                    alpha = pl.exp(pl.sub(mi_tile_nd, mi_new))\r\n                    beta = pl.exp(pl.sub(mij_tile_nd, mi_new))\r\n                    li_updated = pl.add(pl.mul(alpha, li_tile_nd), pl.mul(beta, lij_tile_nd))\r\n\r\n                    mi_new_dn = pl.reshape(mi_new, [q_tile, 1])\r\n                    li_updated_dn = pl.reshape(li_updated, [q_tile, 1])\r\n\r\n                    mi_batch = pl.store(mi_new_dn, [b * q_tile, 0], mi_batch, [q_tile, 1])\r\n                    li_batch = pl.store(li_updated_dn, [b * q_tile, 0], li_batch, [q_tile, 1])\r\n\r\n                    alpha_dn = pl.reshape(alpha, [q_tile, 1])\r\n                    beta_dn = pl.reshape(beta, [q_tile, 1])\r\n                    oi_scaled = pl.row_expand_mul(oi_tile, alpha_dn)\r\n                    oi_new_scaled = pl.row_expand_mul(oi_new_tile, beta_dn)\r\n                    oi_updated = pl.add(oi_scaled, oi_new_scaled)\r\n                    oi_batch = pl.store(oi_updated, [b * q_tile, 0], oi_batch, [q_tile, head_dim])\r\n\r\n            return mi_batch, li_batch, oi_batch\r\n\r\n        # ── VECTOR kernel: final normalization ─────────────────────────\r\n        # For each batch item b (stride-partitioned across HW blocks):\r\n        #   Compute out = oi / li and scatter to the output tensor at\r\n        #   row (b * num_heads + q_offset)\r\n        @pl.function(type=pl.FunctionType.InCore)\r\n        def SpmdNormalize(\r\n            self,\r\n            oi_batch: pl.Tensor[[batch_q_tile, head_dim], pl.FP32],\r\n            li_batch: pl.Tensor[[batch_q_tile, 1], pl.FP32],\r\n            out_tensor: pl.Out[pl.Tensor[[out_rows, head_dim], pl.FP32]],\r\n            batch_count: pl.Scalar[pl.INDEX],\r\n            q_offset: pl.Scalar[pl.INDEX],\r\n            num_heads_param: pl.Scalar[pl.INDEX],\r\n        ) -> pl.Tensor[[out_rows, head_dim], pl.FP32]:\r\n            \"\"\"Normalize accumulators and scatter to output (VECTOR).\"\"\"\r\n            spmd_idx = pl.tile.get_block_idx()\r\n            spmd_block_num = pl.tile.get_block_num()\r\n            for b in pl.range(spmd_idx, batch_count, spmd_block_num):\r\n                oi_tile = pl.load(\r\n                    oi_batch,\r\n                    [b * q_tile, 0],\r\n                    [q_tile, head_dim],\r\n                    target_memory=pl.MemorySpace.Vec,\r\n                )\r\n                li_tile = pl.load(\r\n                    li_batch,\r\n                    [b * q_tile, 0],\r\n                    [q_tile, 1],\r\n                    target_memory=pl.MemorySpace.Vec,\r\n                )\r\n                dst_tile = pl.row_expand_div(oi_tile, li_tile)\r\n                dst_row = b * num_heads_param + q_offset\r\n                out_tensor = pl.store(dst_tile, [dst_row, 0], out_tensor, [q_tile, head_dim])\r\n            return out_tensor\r\n\r\n        # ── Orchestration ──────────────────────────────────────────────\r\n        # Reads runtime config, computes max KV blocks across all requests,\r\n        # then runs a two-level loop:\r\n        #   Outer: iterate over q_tile groups (tiling num_heads)\r\n        #   Inner: iterate over KV blocks, dispatching 4 SPMD kernels per block\r\n        # After inner loop, dispatches SpmdNormalize to produce final output.\r\n        @pl.function(type=pl.FunctionType.Orchestration)\r\n        def paged_attention_spmd(\r\n            self,\r\n            query: pl.Tensor[[query_rows, head_dim], pl.BF16],\r\n            key_cache: pl.Tensor[[key_cache_rows, head_dim], pl.BF16],\r\n            value_cache: pl.Tensor[[key_cache_rows, head_dim], pl.BF16],\r\n            block_table: pl.Tensor[[block_table_flat_size], pl.INT32],\r\n            context_lens: pl.Tensor[[batch], pl.INT32],\r\n            scale: pl.Tensor[[1], pl.FP32],\r\n            out: pl.Out[pl.Tensor[[out_rows, head_dim], pl.FP32]],\r\n            config: pl.Tensor[[7], pl.INT64],\r\n        ) -> pl.Tensor[[out_rows, head_dim], pl.FP32]:\r\n            \"\"\"SPMD paged attention orchestration.\r\n\r\n            Outer loop over q_tile groups, inner loop over KV blocks.\r\n            Each kernel stage dispatched as SPMD across multiple hardware blocks.\r\n            Config: [batch, num_heads, kv_head_num, head_dim,\r\n                     block_size, block_num_capacity, active_block_num]\r\n            \"\"\"\r\n            batch_cfg = pl.tensor.read(config, [0])\r\n            num_heads_cfg = pl.tensor.read(config, [1])\r\n            block_size_cfg = pl.tensor.read(config, [4])\r\n            block_num_capacity_cfg = pl.tensor.read(config, [5])\r\n            active_block_num_cfg = pl.tensor.read(config, [6])\r\n            scale_value: pl.Scalar[pl.FP32] = pl.tensor.read(scale, [0])\r\n            zero_bn_cfg: pl.Scalar[pl.INT64] = 0\r\n            if batch_cfg == 0:\r\n                max_bn_cfg: pl.Scalar[pl.INT64] = pl.yield_(zero_bn_cfg)\r\n            else:\r\n                first_seq = pl.tensor.read(context_lens, [0])\r\n                first_bn_cfg: pl.Scalar[pl.INT64] = (first_seq + block_size_cfg - 1) // block_size_cfg\r\n                max_bn_cfg: pl.Scalar[pl.INT64] = pl.yield_(first_bn_cfg)\r\n            for b in pl.range(1, batch_cfg):\r\n                cur_seq_b = pl.tensor.read(context_lens, [b])\r\n                bn_b = (cur_seq_b + block_size_cfg - 1) // block_size_cfg\r\n                max_bn_cfg = pl.max(max_bn_cfg, bn_b)\r\n\r\n            max_bn_cfg = pl.min(max_bn_cfg, active_block_num_cfg)\r\n            q_loop_cfg = (num_heads_cfg + q_tile - 1) // q_tile\r\n\r\n            for q_idx in pl.range(q_loop_cfg):\r\n                q_offset = q_idx * q_tile\r\n\r\n                # Per-batch accumulators for online softmax across KV blocks.\r\n                mi_a = pl.create_tensor([batch_q_tile, 1], dtype=pl.FP32)\r\n                li_a = pl.create_tensor([batch_q_tile, 1], dtype=pl.FP32)\r\n                oi_a = pl.create_tensor([batch_q_tile, head_dim], dtype=pl.FP32)\r\n\r\n                for bn in pl.range(max_bn_cfg):\r\n                    # Temporary tensors for this KV block iteration.\r\n                    sij_b = pl.create_tensor([batch_q_tile, block_size], dtype=pl.FP32)\r\n                    pij_b = pl.create_tensor([batch_q_tile, block_size], dtype=pl.BF16)\r\n                    mij_b = pl.create_tensor([batch_q_tile, 1], dtype=pl.FP32)\r\n                    lij_b = pl.create_tensor([batch_q_tile, 1], dtype=pl.FP32)\r\n                    oi_new_b = pl.create_tensor([batch_q_tile, head_dim], dtype=pl.FP32)\r\n\r\n                    # sync_start ensures all HW blocks begin together before\r\n                    # the cooperative SPMD wave.\r\n                    with pl.spmd(core_num=4, sync_start=True):\r\n                        sij_b = self.SpmdQkMatmul(\r\n                            query,\r\n                            key_cache,\r\n                            sij_b,\r\n                            block_table,\r\n                            context_lens,\r\n                            batch_cfg,\r\n                            bn,\r\n                            q_offset,\r\n                            block_num_capacity_cfg,\r\n                            block_size_cfg,\r\n                            num_heads_cfg,\r\n                        )\r\n\r\n                    with pl.cluster():\r\n                        with pl.spmd(core_num=4):\r\n                            pij_b, mij_b, lij_b = self.SpmdSoftmaxPrepare(\r\n                                sij_b,\r\n                                pij_b,\r\n                                mij_b,\r\n                                lij_b,\r\n                                scale_value,\r\n                                context_lens,\r\n                                batch_cfg,\r\n                                bn,\r\n                                block_size_cfg,\r\n                            )\r\n\r\n                    with pl.spmd(core_num=4):\r\n                        oi_new_b = self.SpmdPvMatmul(\r\n                            pij_b,\r\n                            value_cache,\r\n                            oi_new_b,\r\n                            block_table,\r\n                            context_lens,\r\n                            batch_cfg,\r\n                            bn,\r\n                            block_num_capacity_cfg,\r\n                            block_size_cfg,\r\n                        )\r\n\r\n                    if bn == 0:\r\n                        is_first = pl.yield_(1)\r\n                    else:\r\n                        is_first = pl.yield_(0)\r\n\r\n                    with pl.cluster():\r\n                        with pl.spmd(core_num=4):\r\n                            mi_a, li_a, oi_a = self.SpmdOnlineUpdate(\r\n                                mij_b,\r\n                                lij_b,\r\n                                oi_new_b,\r\n                                mi_a,\r\n                                li_a,\r\n                                oi_a,\r\n                                is_first,\r\n                                batch_cfg,\r\n                            )\r\n\r\n                # Final normalization: out = oi / li, scattered to output tensor.\r\n                with pl.spmd(core_num=4):\r\n                    out = self.SpmdNormalize(\r\n                        oi_a,\r\n                        li_a,\r\n                        out,\r\n                        batch_cfg,\r\n                        q_offset,\r\n                        num_heads_cfg,\r\n                    )\r\n\r\n            return out\r\n\r\n    return SpmdPagedAttentionProgram\r\n\r\n\r\ndef golden(tensors: dict, params: dict | None = None) -> None:\r\n    \"\"\"Reference paged-attention computation (torch), mirroring the kernel pipeline.\"\"\"\r\n    config = tensors[\"config\"]\r\n    batch_size = int(config[0].item())\r\n    num_heads = int(config[1].item())\r\n    head_dim = int(config[3].item())\r\n    block_size = int(config[4].item())\r\n    max_num_blocks_per_req = int(config[5].item())\r\n    active_num_blocks = int(config[6].item())\r\n    scale = float(tensors[\"scale\"][0].item())\r\n\r\n    query = tensors[\"query\"].float().reshape(batch_size, num_heads, head_dim)\r\n    total_pool_blocks = batch_size * max_num_blocks_per_req\r\n    key_cache = tensors[\"key_cache\"].float().reshape(total_pool_blocks, block_size, head_dim)\r\n    value_cache = tensors[\"value_cache\"].float().reshape(total_pool_blocks, block_size, head_dim)\r\n    block_table = tensors[\"block_table\"].reshape(batch_size, max_num_blocks_per_req)\r\n    context_lens = tensors[\"context_lens\"]\r\n\r\n    out = torch.zeros((batch_size, num_heads, head_dim), dtype=torch.float32)\r\n    q_tile = 16\r\n    max_bn = min(\r\n        active_num_blocks,\r\n        int((context_lens.max().item() + block_size - 1) // block_size),\r\n    )\r\n\r\n    for q_offset in range(0, num_heads, q_tile):\r\n        q_tile_size = min(q_tile, num_heads - q_offset)\r\n        qi = query[:, q_offset : q_offset + q_tile_size, :]\r\n        oi = torch.zeros(\r\n            (batch_size, q_tile_size, head_dim),\r\n            dtype=value_cache.dtype,\r\n            device=qi.device,\r\n        )\r\n        li = torch.zeros(\r\n            (batch_size, q_tile_size, 1),\r\n            dtype=qi.dtype,\r\n            device=qi.device,\r\n        )\r\n        mi = torch.zeros_like(li)\r\n\r\n        for bn in range(max_bn):\r\n            valid_lens = torch.clamp(context_lens - bn * block_size, min=0, max=block_size)\r\n            if not (valid_lens > 0).any():\r\n                break\r\n            block_indices = block_table[:, bn]\r\n            kj_all = key_cache[block_indices]\r\n            vj_all = value_cache[block_indices]\r\n\r\n            sij = torch.bmm(qi, kj_all.transpose(1, 2)) * scale\r\n            pos = torch.arange(block_size).unsqueeze(0)\r\n            valid_mask = (pos < valid_lens.unsqueeze(1)).unsqueeze(1)\r\n            sij = sij.masked_fill(~valid_mask, float(\"-inf\"))\r\n            mij = sij.max(dim=-1, keepdim=True)[0].clamp(min=-1e30)\r\n            pij = torch.exp(sij - mij).masked_fill(~valid_mask, 0.0)\r\n            pij = pij.to(torch.bfloat16).to(torch.float32)\r\n            lij = pij.sum(dim=-1, keepdim=True)\r\n            oi_new = torch.bmm(pij, vj_all)\r\n\r\n            if bn == 0:\r\n                oi, li, mi = oi_new, lij, mij\r\n            else:\r\n                mi_new = torch.maximum(mi, mij)\r\n                alpha = torch.exp(mi - mi_new)\r\n                beta = torch.exp(mij - mi_new)\r\n                li = alpha * li + beta * lij\r\n                oi = alpha * oi + beta * oi_new\r\n                mi = mi_new\r\n\r\n        out[:, q_offset : q_offset + q_tile_size, :] = torch.where(\r\n            li > 0,\r\n            oi / li,\r\n            torch.zeros_like(oi),\r\n        )\r\n\r\n    tensors[\"out\"][:] = out.reshape(batch_size * num_heads, head_dim)\r\n\r\n\r\ndef build_tensor_specs(\r\n    batch: int,\r\n    num_heads: int,\r\n    head_dim: int,\r\n    block_size: int,\r\n    max_num_blocks_per_req: int,\r\n    active_num_blocks: int,\r\n    context_len: int | Sequence[int] | torch.Tensor,\r\n    scale: float = 1.0,\r\n):\r\n    \"\"\"Build TensorSpec objects matching the paged_attention_spmd signature.\"\"\"\r\n    from pypto.runtime import TensorSpec  # noqa: PLC0415\r\n\r\n    query_rows = batch * num_heads\r\n    key_cache_rows = batch * max_num_blocks_per_req * block_size\r\n    block_table_flat_size = batch * max_num_blocks_per_req\r\n\r\n    if isinstance(context_len, torch.Tensor):\r\n        context_lens_init = context_len.to(dtype=torch.int32)\r\n    elif isinstance(context_len, Sequence) and not isinstance(context_len, (str, bytes)):\r\n        context_lens_init = torch.tensor(list(context_len), dtype=torch.int32)\r\n    else:\r\n        context_lens_init = torch.full((batch,), int(context_len), dtype=torch.int32)\r\n\r\n    if context_lens_init.numel() != batch:\r\n        raise ValueError(\r\n            f\"context_len must provide exactly {batch} elements, got {context_lens_init.numel()}\"\r\n        )\r\n\r\n    max_context_len = int(context_lens_init.max().item()) if batch > 0 else 0\r\n    max_blocks_from_context = (max_context_len + block_size - 1) // block_size if block_size > 0 else 0\r\n\r\n    if active_num_blocks > max_num_blocks_per_req:\r\n        raise ValueError(\"active_num_blocks must not exceed max_num_blocks_per_req\")\r\n    active_num_blocks = min(active_num_blocks, max_blocks_from_context)\r\n\r\n    def init_config():\r\n        return torch.tensor(\r\n            [\r\n                batch,\r\n                num_heads,\r\n                1,\r\n                head_dim,\r\n                block_size,\r\n                max_num_blocks_per_req,\r\n                active_num_blocks,\r\n            ],\r\n            dtype=torch.int64,\r\n        )\r\n\r\n    def init_scale():\r\n        return torch.tensor([scale], dtype=torch.float32)\r\n\r\n    def init_context_lens():\r\n        return context_lens_init.clone()\r\n\r\n    def init_block_table():\r\n        return torch.randint(\r\n            0,\r\n            max(block_table_flat_size, 1),\r\n            size=(batch, max_num_blocks_per_req),\r\n            dtype=torch.int32,\r\n        ).flatten()\r\n\r\n    return [\r\n        TensorSpec(\"query\", [query_rows, head_dim], torch.bfloat16, init_value=torch.randn),\r\n        TensorSpec(\"key_cache\", [key_cache_rows, head_dim], torch.bfloat16, init_value=torch.randn),\r\n        TensorSpec(\"value_cache\", [key_cache_rows, head_dim], torch.bfloat16, init_value=torch.randn),\r\n        TensorSpec(\"block_table\", [block_table_flat_size], torch.int32, init_value=init_block_table),\r\n        TensorSpec(\"context_lens\", [batch], torch.int32, init_value=init_context_lens),\r\n        TensorSpec(\"scale\", [1], torch.float32, init_value=init_scale),\r\n        TensorSpec(\"out\", [query_rows, head_dim], torch.float32, is_output=True),\r\n        TensorSpec(\"config\", [7], torch.int64, init_value=init_config),\r\n    ]\r\n\r\n\r\ndef _build_runtime_tensors(tensor_specs):\r\n    tensors = {spec.name: spec.create_tensor() for spec in tensor_specs}\r\n    input_tensors = tuple(tensors[spec.name] for spec in tensor_specs if not spec.is_output)\r\n    return tensors, input_tensors\r\n\r\n\r\ndef main():\r\n    parser = argparse.ArgumentParser(description=\"SPMD paged attention example\")\r\n    default_device = _get_default_device_id()\r\n    parser.add_argument(\r\n        \"-p\",\r\n        \"--platform\",\r\n        type=str,\r\n        default=\"a2a3\",\r\n        choices=[\"a2a3\", \"a2a3sim\", \"a5\", \"a5sim\"],\r\n    )\r\n    parser.add_argument(\"-d\", \"--device\", type=int, default=default_device)\r\n    parser.add_argument(\r\n        \"--enable-l2-swimlane\",\r\n        action=\"store_true\",\r\n        default=False,\r\n        help=\"Enable on-device runtime profiling and generate swimlane JSON\",\r\n    )\r\n    args = parser.parse_args()\r\n    print(f\"Using platform={args.platform}, device_id={args.device}\")\r\n\r\n    batch = 4\r\n    num_heads = 16\r\n    head_dim = 128\r\n    block_size = 128\r\n    max_model_len = 32768\r\n    context_len = 8192\r\n    scale = 1.0\r\n    max_num_blocks_per_req = max_model_len // block_size\r\n    active_num_blocks = (context_len + block_size - 1) // block_size\r\n\r\n    program = build_paged_attention_spmd_program(\r\n        batch=batch,\r\n        num_heads=num_heads,\r\n        head_dim=head_dim,\r\n        block_size=block_size,\r\n        max_num_blocks_per_req=max_num_blocks_per_req,\r\n    )\r\n\r\n    tensor_specs = build_tensor_specs(\r\n        batch=batch,\r\n        num_heads=num_heads,\r\n        head_dim=head_dim,\r\n        block_size=block_size,\r\n        max_num_blocks_per_req=max_num_blocks_per_req,\r\n        active_num_blocks=active_num_blocks,\r\n        context_len=context_len,\r\n        scale=scale,\r\n    )\r\n    tensors, input_tensors = _build_runtime_tensors(tensor_specs)\r\n    query = tensors[\"query\"]\r\n    key_cache = tensors[\"key_cache\"]\r\n    value_cache = tensors[\"value_cache\"]\r\n    block_table = tensors[\"block_table\"]\r\n    context_lens = tensors[\"context_lens\"]\r\n    scale_tensor = tensors[\"scale\"]\r\n    config = tensors[\"config\"]\r\n    run_config = RunConfig(\r\n        platform=args.platform,\r\n        device_id=args.device,\r\n        strategy=OptimizationStrategy.Default,\r\n        dump_passes=True,\r\n        backend_type=BackendType.Ascend950 if args.platform.startswith(\"a5\") else BackendType.Ascend910B,\r\n        enable_l2_swimlane=args.enable_l2_swimlane,\r\n    )\r\n    compiled = run(program, config=run_config)\r\n    output = compiled(*input_tensors, config=run_config)\r\n    if not isinstance(output, torch.Tensor):\r\n        raise TypeError(f\"Expected tensor output from compiled program, got {type(output).__name__}\")\r\n\r\n    expected_out = torch.zeros_like(output)\r\n    golden(\r\n        {\r\n            \"query\": query,\r\n            \"key_cache\": key_cache,\r\n            \"value_cache\": value_cache,\r\n            \"block_table\": block_table,\r\n            \"context_lens\": context_lens,\r\n            \"scale\": scale_tensor,\r\n            \"out\": expected_out,\r\n            \"config\": config,\r\n        },\r\n    )\r\n    assert torch.allclose(output, expected_out, rtol=2e-2, atol=2e-2), (\r\n        f\"Validation failed: max diff = {(output - expected_out).abs().max().item()}\"\r\n    )\r\n    print(\"PASSED\")\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    main()\r\n","examples/models/qwen3_jit/config.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"Shape and tiling constants for Qwen3-32B single-layer decode.\r\n\r\nCentralised so every kernel file imports the same values. Mirrors the\r\nconstants from the upstream ``qwen3_32b_decode.py`` reference.\"\"\"\r\n\r\n# ─── Model dimensions ───\r\nBATCH = 16\r\nMAX_SEQ = 4096\r\nNUM_HEADS = 64\r\nNUM_KV_HEADS = 8\r\nHEAD_DIM = 128\r\nHIDDEN = NUM_HEADS * HEAD_DIM  # 8192\r\nINTERMEDIATE = 25600\r\nKV_HIDDEN = NUM_KV_HEADS * HEAD_DIM\r\nCACHE_ROWS = BATCH * NUM_KV_HEADS * MAX_SEQ\r\nHALF_DIM = HEAD_DIM // 2\r\nQ_PER_KV = NUM_HEADS // NUM_KV_HEADS\r\nATTN_SCALE = 1.0 / (HEAD_DIM**0.5)\r\nEPS = 1e-6\r\nHIDDEN_INV = 1.0 / HIDDEN\r\n\r\n# ─── Scope 1 tiles ───\r\nRMSNORM_K_CHUNK = 512\r\nQ_OUT_CHUNK = 256\r\nQ_PROJ_K_CHUNK = 128\r\nKV_OUT_CHUNK = 256\r\nKV_PROJ_K_CHUNK = 128\r\n\r\n# ─── Scope 2 tiles ───\r\nQ_HEAD_BATCH = 8\r\nQ_HEAD_PAD = 16\r\nSEQ_TILE = 256\r\nQ_GROUPS = Q_PER_KV // Q_HEAD_BATCH\r\nTOTAL_Q_GROUPS = NUM_KV_HEADS * Q_GROUPS\r\nMAX_CTX_BLOCKS = (MAX_SEQ + SEQ_TILE - 1) // SEQ_TILE\r\n\r\n# ─── Scope 3 tiles ───\r\nK_CHUNK = 128\r\nOUT_PROJ_K_CHUNK = 128\r\nMLP_OUT_CHUNK = 256\r\nDOWN_N_CHUNK = 256\r\nDOWN_K_CHUNK = 128\r\n","examples/models/qwen3_jit/kernels/attention.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"Scope 2 attention kernels.\r\n\r\nThis file demonstrates the cross-file utility pattern for the attention\r\nsection of Qwen3-32B decode. Currently implements one representative\r\nsub-stage — RoPE rotation + K/V cache writes + Q pad — as a single\r\n``@pl.jit.inline`` kernel.\r\n\r\nThe full grouped-query attention (QK matmul, softmax, SV matmul, online\r\nsoftmax accumulation) follows the same composition pattern; each stage\r\nbecomes another ``@pl.jit.inline`` (or ``@pl.jit.incore``) kernel called\r\nfrom the entry's per-batch / per-group loops. See ``qwen3_decode.py`` and\r\nthe upstream monolithic reference for the full structure.\r\n\"\"\"\r\n\r\nimport pypto.language as pl\r\n\r\nfrom ..config import (\r\n    BATCH,\r\n    HALF_DIM,\r\n    HEAD_DIM,\r\n    MAX_SEQ,\r\n    NUM_KV_HEADS,\r\n    Q_HEAD_BATCH,\r\n    Q_HEAD_PAD,\r\n    Q_PER_KV,\r\n    TOTAL_Q_GROUPS,\r\n)\r\n\r\n\r\n@pl.jit.inline\r\ndef rope_kv_cache_update(\r\n    q_proj: pl.Tensor,\r\n    k_proj: pl.Tensor,\r\n    v_proj: pl.Tensor,\r\n    seq_lens: pl.Tensor,\r\n    rope_cos: pl.Tensor,\r\n    rope_sin: pl.Tensor,\r\n    k_cache: pl.Out[pl.Tensor],\r\n    v_cache: pl.Out[pl.Tensor],\r\n    all_q_padded: pl.Out[pl.Tensor],\r\n):\r\n    \"\"\"Per-batch: rotate K/V via RoPE, write to KV cache, rotate-and-pad Q.\"\"\"\r\n    for b in pl.parallel(BATCH):\r\n        ctx_len = pl.read(seq_lens, [b])\r\n        pos = ctx_len - 1\r\n\r\n        # Keep the row dim explicit: `rope_cos[pos, ...]` now rank-reduces to 1D\r\n        # under numpy-style indexing, but col_expand_mul needs a 2D [1, N] operand.\r\n        cos_lo = rope_cos[pos : pos + 1, 0:HALF_DIM]\r\n        cos_hi = rope_cos[pos : pos + 1, HALF_DIM:HEAD_DIM]\r\n        sin_lo = rope_sin[pos : pos + 1, 0:HALF_DIM]\r\n        sin_hi = rope_sin[pos : pos + 1, HALF_DIM:HEAD_DIM]\r\n\r\n        with pl.at(level=pl.Level.CORE_GROUP, name_hint=\"rope_kv_cache\"):\r\n            for ki in pl.range(NUM_KV_HEADS):\r\n                kv_col = ki * HEAD_DIM\r\n                k_lo = k_proj[b : b + 1, kv_col : kv_col + HALF_DIM]\r\n                k_hi = k_proj[b : b + 1, kv_col + HALF_DIM : kv_col + HEAD_DIM]\r\n\r\n                rot_lo = pl.sub(pl.col_expand_mul(k_lo, cos_lo), pl.col_expand_mul(k_hi, sin_lo))\r\n                rot_hi = pl.add(pl.col_expand_mul(k_hi, cos_hi), pl.col_expand_mul(k_lo, sin_hi))\r\n\r\n                cache_row = b * NUM_KV_HEADS * MAX_SEQ + ki * MAX_SEQ + pos\r\n                k_cache = pl.assemble(k_cache, pl.cast(rot_lo, target_type=pl.BF16), [cache_row, 0])\r\n                k_cache = pl.assemble(k_cache, pl.cast(rot_hi, target_type=pl.BF16), [cache_row, HALF_DIM])\r\n\r\n                v_row_bf16 = pl.cast(\r\n                    v_proj[b : b + 1, ki * HEAD_DIM : (ki + 1) * HEAD_DIM], target_type=pl.BF16\r\n                )\r\n                v_cache = pl.assemble(v_cache, v_row_bf16, [cache_row, 0])\r\n\r\n                # Q rotate + pad\r\n                q_base = ki * Q_PER_KV\r\n                q_block = pl.reshape(\r\n                    q_proj[b : b + 1, q_base * HEAD_DIM : (q_base + Q_HEAD_BATCH) * HEAD_DIM],\r\n                    [Q_HEAD_BATCH, HEAD_DIM],\r\n                )\r\n\r\n                q_lo = q_block[:, 0:HALF_DIM]\r\n                q_hi = q_block[:, HALF_DIM:HEAD_DIM]\r\n\r\n                q_rot_lo = pl.sub(pl.col_expand_mul(q_lo, cos_lo), pl.col_expand_mul(q_hi, sin_lo))\r\n                q_rot_hi = pl.add(pl.col_expand_mul(q_hi, cos_hi), pl.col_expand_mul(q_lo, sin_hi))\r\n\r\n                q_pad_row0 = b * TOTAL_Q_GROUPS * Q_HEAD_PAD + ki * Q_HEAD_PAD\r\n                all_q_padded = pl.assemble(\r\n                    all_q_padded, pl.cast(q_rot_lo, target_type=pl.BF16), [q_pad_row0, 0]\r\n                )\r\n                all_q_padded = pl.assemble(\r\n                    all_q_padded, pl.cast(q_rot_hi, target_type=pl.BF16), [q_pad_row0, HALF_DIM]\r\n                )\r\n\r\n                q_pad_zero = pl.cast(\r\n                    pl.full([Q_HEAD_PAD - Q_HEAD_BATCH, HEAD_DIM], dtype=pl.FP32, value=0.0),\r\n                    target_type=pl.BF16,\r\n                )\r\n                all_q_padded = pl.assemble(all_q_padded, q_pad_zero, [q_pad_row0 + Q_HEAD_BATCH, 0])\r\n    # All three Out params are rebound via pl.assemble. Returning only k_cache\r\n    # is intentional: pl.Out parameters share memory with the caller, so the\r\n    # in-place writes to v_cache and all_q_padded persist across the inline\r\n    # splice — only one of the three is returned as the SSA-name handle.\r\n    return k_cache\r\n","examples/models/qwen3_jit/kernels/mlp.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"MLP block kernels for Scope 3 stages 4-6: gate proj + up proj + SiLU.\r\n\r\nDecorated as ``@pl.jit.inline``: the body is spliced into the entry,\r\nwhich lets ``OutlineIncoreScopes`` extract each ``pl.at`` block as a\r\nseparate InCore function — same shape as the monolithic reference.\r\n\"\"\"\r\n\r\nimport pypto.language as pl\r\n\r\nfrom ..config import BATCH, HIDDEN, INTERMEDIATE, K_CHUNK, MLP_OUT_CHUNK\r\n\r\n\r\n@pl.jit.inline\r\ndef mlp_block(\r\n    post_norm_tile: pl.Tensor,\r\n    w_gate: pl.Tensor,\r\n    w_up: pl.Tensor,\r\n    mlp_tile: pl.Out[pl.Tensor],\r\n):\r\n    \"\"\"Three ``pl.at`` scopes per output chunk: gate proj, up proj, SiLU+mul.\"\"\"\r\n    for o0 in pl.parallel(0, INTERMEDIATE, MLP_OUT_CHUNK):\r\n        with pl.at(level=pl.Level.CORE_GROUP, name_hint=\"gate_proj\"):\r\n            gate_acc = pl.create_tensor([BATCH, MLP_OUT_CHUNK], dtype=pl.FP32)\r\n\r\n            for kb in pl.pipeline(0, HIDDEN // K_CHUNK, stage=2):\r\n                k0 = kb * K_CHUNK\r\n                post_chunk = post_norm_tile[:, k0 : k0 + K_CHUNK]\r\n                wg = w_gate[k0 : k0 + K_CHUNK, o0 : o0 + MLP_OUT_CHUNK]\r\n\r\n                if k0 == 0:\r\n                    gate_acc = pl.matmul(post_chunk, wg, out_dtype=pl.FP32)\r\n                else:\r\n                    gate_acc = pl.matmul_acc(gate_acc, post_chunk, wg)\r\n\r\n        with pl.at(level=pl.Level.CORE_GROUP, name_hint=\"up_proj\"):\r\n            up_acc = pl.create_tensor([BATCH, MLP_OUT_CHUNK], dtype=pl.FP32)\r\n\r\n            for kb_u in pl.pipeline(0, HIDDEN // K_CHUNK, stage=2):\r\n                k0_u = kb_u * K_CHUNK\r\n                post_chunk_u = post_norm_tile[:, k0_u : k0_u + K_CHUNK]\r\n                wu = w_up[k0_u : k0_u + K_CHUNK, o0 : o0 + MLP_OUT_CHUNK]\r\n\r\n                if k0_u == 0:\r\n                    up_acc = pl.matmul(post_chunk_u, wu, out_dtype=pl.FP32)\r\n                else:\r\n                    up_acc = pl.matmul_acc(up_acc, post_chunk_u, wu)\r\n\r\n        with pl.at(level=pl.Level.CORE_GROUP, name_hint=\"silu\"):\r\n            sigmoid = pl.recip(pl.add(pl.exp(pl.neg(gate_acc)), 1.0))\r\n            mlp_chunk = pl.mul(pl.mul(gate_acc, sigmoid), up_acc)\r\n            mlp_tile = pl.assemble(mlp_tile, pl.cast(mlp_chunk, target_type=pl.BF16), [0, o0])\r\n    return mlp_tile\r\n","examples/models/qwen3_jit/kernels/projection.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"Q/K/V/Output/MLP projection kernels.\r\n\r\nEach utility wraps both the orchestration ``pl.parallel`` loop and the\r\ninner ``pl.at`` compute scope. Decorated as ``@pl.jit.inline`` because the\r\nsplice keeps the IR structurally close to the monolithic reference while\r\nenabling cross-file reuse.\r\n\"\"\"\r\n\r\nimport pypto.language as pl\r\n\r\nfrom ..config import (\r\n    BATCH,\r\n    DOWN_K_CHUNK,\r\n    DOWN_N_CHUNK,\r\n    HIDDEN,\r\n    INTERMEDIATE,\r\n    KV_HIDDEN,\r\n    KV_OUT_CHUNK,\r\n    KV_PROJ_K_CHUNK,\r\n    OUT_PROJ_K_CHUNK,\r\n    Q_OUT_CHUNK,\r\n    Q_PROJ_K_CHUNK,\r\n)\r\n\r\n\r\n@pl.jit.inline\r\ndef q_projection(\r\n    normed_states: pl.Tensor,\r\n    wq: pl.Tensor,\r\n    q_proj: pl.Out[pl.Tensor],\r\n):\r\n    \"\"\"Q projection: tiled matmul over the K dimension, parallel over N.\"\"\"\r\n    for q0 in pl.parallel(0, HIDDEN, Q_OUT_CHUNK):\r\n        with pl.at(level=pl.Level.CORE_GROUP, name_hint=\"q_proj\"):\r\n            q_acc = pl.create_tensor([BATCH, Q_OUT_CHUNK], dtype=pl.FP32)\r\n\r\n            for kb in pl.pipeline(0, HIDDEN // Q_PROJ_K_CHUNK, stage=2):\r\n                k0 = kb * Q_PROJ_K_CHUNK\r\n                tile_a = normed_states[:, k0 : k0 + Q_PROJ_K_CHUNK]\r\n                tile_b = wq[k0 : k0 + Q_PROJ_K_CHUNK, q0 : q0 + Q_OUT_CHUNK]\r\n\r\n                if k0 == 0:\r\n                    q_acc = pl.matmul(tile_a, tile_b, out_dtype=pl.FP32)\r\n                else:\r\n                    q_acc = pl.matmul_acc(q_acc, tile_a, tile_b)\r\n\r\n            q_proj = pl.assemble(q_proj, q_acc, [0, q0])\r\n    return q_proj\r\n\r\n\r\n@pl.jit.inline\r\ndef k_projection(\r\n    normed_states: pl.Tensor,\r\n    wk: pl.Tensor,\r\n    k_proj: pl.Out[pl.Tensor],\r\n):\r\n    \"\"\"K projection.\r\n\r\n    Note: in the upstream monolithic Qwen3 reference K and V projections share\r\n    one ``pl.at`` scope to amortise ``normed_states`` loads. Split here because\r\n    the JIT specializer currently emits a single-tensor return-type annotation\r\n    even when the body returns a tuple — flagged as a follow-up.\r\n    \"\"\"\r\n    for kv0 in pl.parallel(0, KV_HIDDEN, KV_OUT_CHUNK):\r\n        with pl.at(level=pl.Level.CORE_GROUP, name_hint=\"k_proj\"):\r\n            k_acc = pl.create_tensor([BATCH, KV_OUT_CHUNK], dtype=pl.FP32)\r\n            for kb in pl.pipeline(0, HIDDEN // KV_PROJ_K_CHUNK, stage=2):\r\n                k0 = kb * KV_PROJ_K_CHUNK\r\n                tile_a = normed_states[:, k0 : k0 + KV_PROJ_K_CHUNK]\r\n                tile_wk = wk[k0 : k0 + KV_PROJ_K_CHUNK, kv0 : kv0 + KV_OUT_CHUNK]\r\n                if k0 == 0:\r\n                    k_acc = pl.matmul(tile_a, tile_wk, out_dtype=pl.FP32)\r\n                else:\r\n                    k_acc = pl.matmul_acc(k_acc, tile_a, tile_wk)\r\n            k_proj = pl.assemble(k_proj, k_acc, [0, kv0])\r\n    return k_proj\r\n\r\n\r\n@pl.jit.inline\r\ndef v_projection(\r\n    normed_states: pl.Tensor,\r\n    wv: pl.Tensor,\r\n    v_proj: pl.Out[pl.Tensor],\r\n):\r\n    \"\"\"V projection — symmetric to K.\"\"\"\r\n    for kv0 in pl.parallel(0, KV_HIDDEN, KV_OUT_CHUNK):\r\n        with pl.at(level=pl.Level.CORE_GROUP, name_hint=\"v_proj\"):\r\n            v_acc = pl.create_tensor([BATCH, KV_OUT_CHUNK], dtype=pl.FP32)\r\n            for kb in pl.pipeline(0, HIDDEN // KV_PROJ_K_CHUNK, stage=2):\r\n                k0 = kb * KV_PROJ_K_CHUNK\r\n                tile_a = normed_states[:, k0 : k0 + KV_PROJ_K_CHUNK]\r\n                tile_wv = wv[k0 : k0 + KV_PROJ_K_CHUNK, kv0 : kv0 + KV_OUT_CHUNK]\r\n                if k0 == 0:\r\n                    v_acc = pl.matmul(tile_a, tile_wv, out_dtype=pl.FP32)\r\n                else:\r\n                    v_acc = pl.matmul_acc(v_acc, tile_a, tile_wv)\r\n            v_proj = pl.assemble(v_proj, v_acc, [0, kv0])\r\n    return v_proj\r\n\r\n\r\n@pl.jit.inline\r\ndef out_projection_residual(\r\n    attn_out: pl.Tensor,\r\n    hidden_states: pl.Tensor,\r\n    wo: pl.Tensor,\r\n    resid1_tile: pl.Out[pl.Tensor],\r\n):\r\n    \"\"\"attn_out @ wo + hidden_states  (Scope 3 stages 1+2).\"\"\"\r\n    for ob in pl.parallel(0, HIDDEN // Q_OUT_CHUNK, 2):\r\n        with pl.at(\r\n            level=pl.Level.CORE_GROUP,\r\n            optimizations=[pl.split(pl.SplitMode.UP_DOWN)],\r\n            name_hint=\"out_proj_residual\",\r\n        ):\r\n            for oi in pl.range(ob, ob + 2):\r\n                o0 = oi * Q_OUT_CHUNK\r\n                hidden_chunk = hidden_states[:, o0 : o0 + Q_OUT_CHUNK]\r\n\r\n                o_acc = pl.create_tensor([BATCH, Q_OUT_CHUNK], dtype=pl.FP32)\r\n\r\n                for kb in pl.pipeline(0, HIDDEN // OUT_PROJ_K_CHUNK, stage=2):\r\n                    k0 = kb * OUT_PROJ_K_CHUNK\r\n                    a_chunk = attn_out[:, k0 : k0 + OUT_PROJ_K_CHUNK]\r\n                    w_chunk = wo[k0 : k0 + OUT_PROJ_K_CHUNK, o0 : o0 + Q_OUT_CHUNK]\r\n\r\n                    if k0 == 0:\r\n                        o_acc = pl.matmul(a_chunk, w_chunk, out_dtype=pl.FP32)\r\n                    else:\r\n                        o_acc = pl.matmul_acc(o_acc, a_chunk, w_chunk)\r\n\r\n                resid = pl.cast(hidden_chunk, target_type=pl.FP32)\r\n                resid1_tile = pl.assemble(resid1_tile, pl.add(o_acc, resid), [0, o0])\r\n    return resid1_tile\r\n\r\n\r\n@pl.jit.inline\r\ndef down_projection_residual(\r\n    mlp_tile: pl.Tensor,\r\n    resid1_tile: pl.Tensor,\r\n    w_down: pl.Tensor,\r\n    out: pl.Out[pl.Tensor],\r\n):\r\n    \"\"\"Down projection of MLP output + final residual writeback (Scope 3 stages 7+8).\"\"\"\r\n    for db in pl.parallel(0, HIDDEN // DOWN_N_CHUNK, 2):\r\n        with pl.at(\r\n            level=pl.Level.CORE_GROUP,\r\n            optimizations=[pl.split(pl.SplitMode.UP_DOWN)],\r\n            name_hint=\"down_proj_residual\",\r\n        ):\r\n            for di in pl.range(db, db + 2):\r\n                d0 = di * DOWN_N_CHUNK\r\n                resid_chunk = resid1_tile[:, d0 : d0 + DOWN_N_CHUNK]\r\n\r\n                down_acc = pl.create_tensor([BATCH, DOWN_N_CHUNK], dtype=pl.FP32)\r\n\r\n                for ob in pl.pipeline(0, INTERMEDIATE // DOWN_K_CHUNK, stage=2):\r\n                    o0 = ob * DOWN_K_CHUNK\r\n                    mlp_chunk = mlp_tile[:, o0 : o0 + DOWN_K_CHUNK]\r\n                    w_chunk = w_down[o0 : o0 + DOWN_K_CHUNK, d0 : d0 + DOWN_N_CHUNK]\r\n\r\n                    if o0 == 0:\r\n                        down_acc = pl.matmul(mlp_chunk, w_chunk, out_dtype=pl.FP32)\r\n                    else:\r\n                        down_acc = pl.matmul_acc(down_acc, mlp_chunk, w_chunk)\r\n\r\n                out_chunk = pl.add(down_acc, resid_chunk)\r\n                out = pl.assemble(out, pl.cast(out_chunk, target_type=pl.BF16), [0, d0])\r\n    return out\r\n","examples/models/qwen3_jit/kernels/rmsnorm.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"RMSNorm kernels.\r\n\r\nTwo flavours, one per call site in the model:\r\n  - ``input_rmsnorm`` — pre-attention RMSNorm of hidden_states (chunk=512, stage=4)\r\n  - ``post_rmsnorm`` — post-attention RMSNorm of the residual (chunk=128, stage=2)\r\n\r\nBoth are ``@pl.jit.inline``: each is called exactly once, so splicing avoids\r\nthe need for a separate Function in the IR while keeping the kernel source\r\nreusable across other models that need the same shape.\r\n\"\"\"\r\n\r\nimport pypto.language as pl\r\n\r\nfrom ..config import BATCH, EPS, HIDDEN, HIDDEN_INV, K_CHUNK, RMSNORM_K_CHUNK\r\n\r\n\r\n@pl.jit.inline\r\ndef input_rmsnorm(\r\n    hidden_states: pl.Tensor,\r\n    input_rms_weight: pl.Tensor,\r\n    normed_states: pl.Out[pl.Tensor],\r\n):\r\n    \"\"\"Two-pass RMSNorm: variance reduction, then normalisation × gamma.\"\"\"\r\n    with pl.at(level=pl.Level.CORE_GROUP, name_hint=\"rmsnorm\"):\r\n        partial_sq = pl.full([1, BATCH], dtype=pl.FP32, value=0.0)\r\n\r\n        for kb in pl.pipeline(HIDDEN // RMSNORM_K_CHUNK, stage=4):\r\n            k0 = kb * RMSNORM_K_CHUNK\r\n            x_chunk = pl.cast(hidden_states[:, k0 : k0 + RMSNORM_K_CHUNK], target_type=pl.FP32)\r\n            partial_sq = pl.add(\r\n                partial_sq,\r\n                pl.reshape(pl.row_sum(pl.mul(x_chunk, x_chunk)), [1, BATCH]),\r\n            )\r\n\r\n        variance = pl.reshape(pl.add(pl.mul(partial_sq, HIDDEN_INV), EPS), [BATCH, 1])\r\n        inv_rms = pl.recip(pl.sqrt(variance))\r\n\r\n        for kb in pl.pipeline(HIDDEN // RMSNORM_K_CHUNK, stage=4):\r\n            k0 = kb * RMSNORM_K_CHUNK\r\n            x_chunk = pl.cast(hidden_states[:, k0 : k0 + RMSNORM_K_CHUNK], target_type=pl.FP32)\r\n            gamma = input_rms_weight[:, k0 : k0 + RMSNORM_K_CHUNK]\r\n            normed = pl.col_expand_mul(pl.row_expand_mul(x_chunk, inv_rms), gamma)\r\n            normed_states = pl.assemble(normed_states, pl.cast(normed, target_type=pl.BF16), [0, k0])\r\n    return normed_states\r\n\r\n\r\n@pl.jit.inline\r\ndef post_rmsnorm(\r\n    resid: pl.Tensor,\r\n    post_rms_weight: pl.Tensor,\r\n    post_norm_tile: pl.Out[pl.Tensor],\r\n):\r\n    \"\"\"Post-attention RMSNorm. Different chunk size from input_rmsnorm.\r\n\r\n    ``resid`` here is the FP32 residual stream produced by\r\n    ``out_projection_residual`` — the squared-sum + normalize passes consume\r\n    it directly without any dtype conversion. ``post_norm_tile`` is BF16, so\r\n    the final ``normed`` chunk is cast to BF16 at the assemble site.\r\n    \"\"\"\r\n    with pl.at(level=pl.Level.CORE_GROUP, name_hint=\"post_rmsnorm\"):\r\n        sq_sum = pl.full([1, BATCH], dtype=pl.FP32, value=0.0)\r\n\r\n        for kb in pl.pipeline(HIDDEN // K_CHUNK, stage=2):\r\n            k0 = kb * K_CHUNK\r\n            resid_chunk = resid[:, k0 : k0 + K_CHUNK]\r\n            sq_sum = pl.add(\r\n                sq_sum,\r\n                pl.reshape(pl.row_sum(pl.mul(resid_chunk, resid_chunk)), [1, BATCH]),\r\n            )\r\n\r\n        inv_rms = pl.recip(pl.sqrt(pl.add(pl.mul(sq_sum, HIDDEN_INV), EPS)))\r\n        inv_rms_col = pl.reshape(inv_rms, [BATCH, 1])\r\n\r\n        for kb in pl.pipeline(HIDDEN // K_CHUNK, stage=2):\r\n            k0 = kb * K_CHUNK\r\n            resid_chunk = resid[:, k0 : k0 + K_CHUNK]\r\n            gamma = post_rms_weight[:, k0 : k0 + K_CHUNK]\r\n            normed = pl.col_expand_mul(pl.row_expand_mul(resid_chunk, inv_rms_col), gamma)\r\n            post_norm_tile = pl.assemble(post_norm_tile, pl.cast(normed, target_type=pl.BF16), [0, k0])\r\n    return post_norm_tile\r\n","examples/models/qwen3_jit/kernels/__init__.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"Reusable kernel utilities for Qwen3-32B JIT decode.\"\"\"\r\n","examples/models/qwen3_jit/qwen3_decode.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"Qwen3-32B single-layer decode forward — JIT entry point.\r\n\r\nComposes the per-scope kernels from ``kernels/`` via plain Python imports.\r\nEach kernel marked ``@pl.jit.inline`` is auto-discovered as a dep and\r\nspliced into this entry by the ``InlineFunctions`` IR pass.\r\n\r\nRun with::\r\n\r\n    python -m examples.models.qwen3_jit.qwen3_decode\r\n\r\n(For numerical validation against a PyTorch golden, see\r\n``qwen3_32b_decode.py`` from the upstream pypto-lib repository.)\r\n\"\"\"\r\n\r\nimport pypto.language as pl\r\n\r\nfrom .config import (\r\n    BATCH,\r\n    CACHE_ROWS,\r\n    HEAD_DIM,\r\n    HIDDEN,\r\n    INTERMEDIATE,\r\n    KV_HIDDEN,\r\n    MAX_SEQ,\r\n    Q_HEAD_PAD,\r\n    TOTAL_Q_GROUPS,\r\n)\r\nfrom .kernels.attention import rope_kv_cache_update\r\nfrom .kernels.mlp import mlp_block\r\nfrom .kernels.projection import (\r\n    down_projection_residual,\r\n    k_projection,\r\n    out_projection_residual,\r\n    q_projection,\r\n    v_projection,\r\n)\r\nfrom .kernels.rmsnorm import input_rmsnorm, post_rmsnorm\r\n\r\n\r\n@pl.jit\r\ndef qwen3_decode(  # noqa: PLR0913 — model signature is intrinsic\r\n    hidden_states: pl.Tensor,\r\n    input_rms_weight: pl.Tensor,\r\n    wq: pl.Tensor,\r\n    wk: pl.Tensor,\r\n    wv: pl.Tensor,\r\n    seq_lens: pl.Tensor,\r\n    rope_cos: pl.Tensor,\r\n    rope_sin: pl.Tensor,\r\n    k_cache: pl.Tensor,\r\n    v_cache: pl.Tensor,\r\n    wo: pl.Tensor,\r\n    post_rms_weight: pl.Tensor,\r\n    w_gate: pl.Tensor,\r\n    w_up: pl.Tensor,\r\n    w_down: pl.Tensor,\r\n    out: pl.Out[pl.Tensor],\r\n):\r\n    # ── Scope 1: input RMSNorm + Q/K/V projection ──\r\n    normed_states = pl.create_tensor([BATCH, HIDDEN], dtype=pl.BF16)\r\n    q_proj = pl.create_tensor([BATCH, HIDDEN], dtype=pl.FP32)\r\n    k_proj = pl.create_tensor([BATCH, KV_HIDDEN], dtype=pl.FP32)\r\n    v_proj = pl.create_tensor([BATCH, KV_HIDDEN], dtype=pl.FP32)\r\n\r\n    normed_states = input_rmsnorm(hidden_states, input_rms_weight, normed_states)\r\n    q_proj = q_projection(normed_states, wq, q_proj)\r\n    k_proj = k_projection(normed_states, wk, k_proj)\r\n    v_proj = v_projection(normed_states, wv, v_proj)\r\n\r\n    # ── Scope 2: RoPE + KV cache update ──\r\n    # rope_kv_cache_update writes to k_cache/v_cache and pre-pads Q for\r\n    # downstream grouped-query attention.\r\n    all_q_padded = pl.create_tensor([BATCH * TOTAL_Q_GROUPS * Q_HEAD_PAD, HEAD_DIM], dtype=pl.BF16)\r\n    k_cache = rope_kv_cache_update(\r\n        q_proj,\r\n        k_proj,\r\n        v_proj,\r\n        seq_lens,\r\n        rope_cos,\r\n        rope_sin,\r\n        k_cache,\r\n        v_cache,\r\n        all_q_padded,\r\n    )\r\n\r\n    # The full grouped-query attention (5 sub-stages × 2 group-pairs) follows\r\n    # the same composition pattern as Scope 1/Scope 3 kernels — see\r\n    # ``kernels/attention.py`` for the pattern doc. For now, attn_out is\r\n    # created here so Scope 3 has something to consume.\r\n    attn_out = pl.create_tensor([BATCH, HIDDEN], dtype=pl.BF16)\r\n\r\n    # ── Scope 3: output projection + residual + post-RMSNorm + MLP + residual ──\r\n    resid1_tile = pl.create_tensor([BATCH, HIDDEN], dtype=pl.FP32)\r\n    post_norm_tile = pl.create_tensor([BATCH, HIDDEN], dtype=pl.BF16)\r\n\r\n    resid1_tile = out_projection_residual(attn_out, hidden_states, wo, resid1_tile)\r\n    post_norm_tile = post_rmsnorm(resid1_tile, post_rms_weight, post_norm_tile)\r\n\r\n    mlp_tile = pl.create_tensor([BATCH, INTERMEDIATE], dtype=pl.BF16)\r\n    mlp_tile = mlp_block(post_norm_tile, w_gate, w_up, mlp_tile)\r\n    out = down_projection_residual(mlp_tile, resid1_tile, w_down, out)\r\n\r\n    return out\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    # Minimal smoke test: build TensorMeta-shaped inputs and call\r\n    # ``compile_for_test`` to run the full pass pipeline (no device execution).\r\n    import torch\r\n\r\n    def randn(shape, dtype):\r\n        return torch.empty(shape, dtype=dtype).normal_()\r\n\r\n    args = [\r\n        randn([BATCH, HIDDEN], torch.bfloat16),  # hidden_states\r\n        randn([1, HIDDEN], torch.float32),  # input_rms_weight\r\n        randn([HIDDEN, HIDDEN], torch.bfloat16),  # wq\r\n        randn([HIDDEN, KV_HIDDEN], torch.bfloat16),  # wk\r\n        randn([HIDDEN, KV_HIDDEN], torch.bfloat16),  # wv\r\n        torch.randint(1, MAX_SEQ + 1, (BATCH,), dtype=torch.int32),\r\n        randn([MAX_SEQ, HEAD_DIM], torch.float32),  # rope_cos\r\n        randn([MAX_SEQ, HEAD_DIM], torch.float32),  # rope_sin\r\n        randn([CACHE_ROWS, HEAD_DIM], torch.bfloat16),  # k_cache\r\n        randn([CACHE_ROWS, HEAD_DIM], torch.bfloat16),  # v_cache\r\n        randn([HIDDEN, HIDDEN], torch.bfloat16),  # wo\r\n        randn([1, HIDDEN], torch.float32),  # post_rms_weight\r\n        randn([HIDDEN, INTERMEDIATE], torch.bfloat16),  # w_gate\r\n        randn([HIDDEN, INTERMEDIATE], torch.bfloat16),  # w_up\r\n        randn([INTERMEDIATE, HIDDEN], torch.bfloat16),  # w_down\r\n        torch.empty([BATCH, HIDDEN], dtype=torch.bfloat16),  # out\r\n    ]\r\n    post_pass = qwen3_decode.compile_for_test(*args)\r\n    print(f\"Compiled program has {len(post_pass.functions)} function(s):\")\r\n    for fn in post_pass.functions.values():\r\n        print(f\"  {fn.name}: {fn.func_type}\")\r\n","examples/models/qwen3_jit/__init__.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"Qwen3-32B single-layer decode forward, expressed via the JIT interface.\r\n\r\nDemonstrates cross-file utility composition:\r\n\r\n  - ``kernels/`` holds reusable per-scope utilities decorated with\r\n    ``@pl.jit.inline`` / ``@pl.jit.incore`` / ``@pl.jit.opaque``. Each kernel\r\n    file is independently importable.\r\n  - ``qwen3_decode.py`` is the ``@pl.jit`` entry that composes the kernels.\r\n  - ``config.py`` holds shape/tile constants shared across kernels and entry.\r\n\r\nThe IR pass pipeline (``InlineFunctions`` runs first) splices Inline\r\nutilities into the entry, then ``OutlineIncoreScopes`` extracts each\r\n``pl.at`` block normally — the post-pass IR matches what a single monolithic\r\n``@pl.program`` would produce.\r\n\"\"\"\r\n","examples/models/__init__.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"\r\nModel examples — multi-kernel programs with orchestration, ordered by complexity.\r\n\r\n  01_ffn.py                         — FFN modules with shared matmul_kernel\r\n  02_vector_dag.py                  — multi-kernel task DAG\r\n  03_flash_attention.py             — flash attention with loop iter_args\r\n  04_paged_attention.py             — standard paged attention + runtime\r\n  05_paged_attention_batch.py       — batch variant\r\n  06_paged_attention_dynamic.py     — dynamic shapes\r\n  07_paged_attention_multi_config.py — multi-config variant\r\n  08_llama_mini.py                  — single-head LLaMA 7B\r\n\"\"\"\r\n\r\nimport importlib\r\nimport sys\r\n\r\n_ALIASES = {\r\n    \"ffn\": \"01_ffn\",\r\n    \"vector_dag\": \"02_vector_dag\",\r\n    \"flash_attention\": \"03_flash_attention\",\r\n    \"paged_attention\": \"04_paged_attention\",\r\n    \"paged_attention_batch\": \"05_paged_attention_batch\",\r\n    \"paged_attention_dynamic\": \"06_paged_attention_dynamic\",\r\n    \"paged_attention_multi_config\": \"07_paged_attention_multi_config\",\r\n    \"llama_mini\": \"08_llama_mini\",\r\n}\r\n\r\nfor _alias, _numbered in _ALIASES.items():\r\n    _mod = importlib.import_module(f\".{_numbered}\", __package__)\r\n    globals()[_alias] = _mod\r\n    sys.modules[f\"{__package__}.{_alias}\"] = _mod\r\n","examples/runtime/distributed_callback.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"Runtime-bound SubWorker callbacks in an L3 distributed program.\r\n\r\nA HOST-level ``SubWorker`` is a pure-Python callback that runs in the forked\r\norchestrator process. When its logic cannot be written at compile time — a\r\nsampling closure that needs live model state, a host-side metric collector, a\r\nresult inspector — declare its body as ``...`` to mark it an **abstract,\r\nruntime-bound callback point**:\r\n\r\n    @pl.function(level=pl.Level.HOST, role=pl.Role.SubWorker)\r\n    def inspect_result(f: pl.Tensor[[128, 128], pl.FP32]):\r\n        ...   # implementation supplied at runtime, NOT here\r\n\r\nThe implementation is then bound at ``prepare(callbacks={...})``. Forgetting to\r\nbind it raises ``ValueError`` at prepare time (not silently at dispatch), and\r\ncodegen emits a guard stub that raises if the callback is ever dispatched\r\nunbound.\r\n\r\nThis script shows:\r\n\r\n  1. Declaring an abstract ``...``-body SubWorker.\r\n  2. Binding a real closure to it via ``compiled.prepare(callbacks={...})``.\r\n  3. The fail-fast error when a required callback is omitted.\r\n\r\nThe pipeline is HOST orchestrator → CHIP add (``f = a + b``) → ``inspect_result``\r\ncallback, mirroring tests/st/distributed/test_l3_distributed.py.\r\n\r\nRun:  python examples/runtime/distributed_callback.py\r\n      (needs the simpler L3 runtime; defaults to the a2a3 simulator platform)\r\n\"\"\"\r\n\r\nimport pypto.language as pl\r\nimport torch\r\nfrom pypto import ir\r\nfrom pypto.ir.distributed_compiled_program import DistributedConfig\r\n\r\nPLATFORM = \"a2a3sim\"  # swap for \"a2a3\" to target a real device\r\n\r\n\r\n@pl.program\r\nclass InspectProgram:\r\n    \"\"\"L3: HOST orch → CHIP worker (a + b) → abstract ``inspect_result`` callback.\"\"\"\r\n\r\n    @pl.function(type=pl.FunctionType.InCore)\r\n    def tile_add(\r\n        self,\r\n        a: pl.Tensor[[128, 128], pl.FP32],\r\n        b: pl.Tensor[[128, 128], pl.FP32],\r\n        f: pl.Out[pl.Tensor[[128, 128], pl.FP32]],\r\n    ) -> pl.Tensor[[128, 128], pl.FP32]:\r\n        tile_a = pl.load(a, [0, 0], [128, 128])\r\n        tile_b = pl.load(b, [0, 0], [128, 128])\r\n        tile_f = pl.add(tile_a, tile_b)\r\n        return pl.store(tile_f, [0, 0], f)\r\n\r\n    @pl.function(type=pl.FunctionType.Orchestration)\r\n    def chip_orch(\r\n        self,\r\n        a: pl.Tensor[[128, 128], pl.FP32],\r\n        b: pl.Tensor[[128, 128], pl.FP32],\r\n        f: pl.Out[pl.Tensor[[128, 128], pl.FP32]],\r\n    ) -> pl.Tensor[[128, 128], pl.FP32]:\r\n        return self.tile_add(a, b, f)\r\n\r\n    @pl.function(level=pl.Level.HOST, role=pl.Role.SubWorker)\r\n    def inspect_result(f: pl.Tensor[[128, 128], pl.FP32]):\r\n        # Abstract body: this SubWorker is a runtime-bound callback. The real\r\n        # implementation is supplied via prepare(callbacks={\"inspect_result\": ...}).\r\n        ...\r\n\r\n    @pl.function(level=pl.Level.HOST, role=pl.Role.Orchestrator)\r\n    def host_orch(\r\n        self,\r\n        a: pl.Tensor[[128, 128], pl.FP32],\r\n        b: pl.Tensor[[128, 128], pl.FP32],\r\n        f: pl.Out[pl.Tensor[[128, 128], pl.FP32]],\r\n    ) -> pl.Tensor[[128, 128], pl.FP32]:\r\n        out_f: pl.Tensor[[128, 128], pl.FP32] = self.chip_orch(a, b, f)\r\n        self.inspect_result(out_f)\r\n        return out_f\r\n\r\n\r\ndef show_abstract_flag() -> None:\r\n    \"\"\"The ``...`` body marks the SubWorker as runtime-bound at the IR level.\"\"\"\r\n    fn = InspectProgram.get_function(\"inspect_result\")\r\n    assert fn is not None\r\n    assert fn.requires_runtime_binding is True\r\n    print(\"inspect_result.requires_runtime_binding =\", fn.requires_runtime_binding)\r\n\r\n\r\ndef run_with_callback() -> None:\r\n    \"\"\"Bind a real closure to the abstract callback and dispatch once.\"\"\"\r\n    from pypto.runtime.distributed_runner import _tensor_from_continuous  # noqa: PLC0415\r\n\r\n    compiled = ir.compile(\r\n        InspectProgram,\r\n        platform=PLATFORM,\r\n        distributed_config=DistributedConfig(\r\n            device_ids=[0], num_sub_workers=1, block_dim=3, aicpu_thread_num=4\r\n        ),\r\n    )\r\n\r\n    # Shared-memory IO, allocated BEFORE prepare() so the forked workers inherit\r\n    # the host mappings. ``observed`` is the callback's side channel back to us.\r\n    host_a = torch.full((128, 128), 2.0, dtype=torch.float32).share_memory_()\r\n    host_b = torch.full((128, 128), 3.0, dtype=torch.float32).share_memory_()\r\n    host_f = torch.zeros((128, 128), dtype=torch.float32).share_memory_()\r\n    observed = torch.zeros(1, dtype=torch.float32).share_memory_()\r\n\r\n    def inspect_result(args) -> None:\r\n        # Real implementation: read the computed tensor and stash a summary.\r\n        f = _tensor_from_continuous(args.tensor(0))\r\n        observed[0] = float(f.reshape(-1)[0].item())\r\n\r\n    with compiled.prepare(callbacks={\"inspect_result\": inspect_result}) as rt:\r\n        rt(host_a, host_b, host_f)\r\n\r\n    expected = torch.full((128, 128), 5.0, dtype=torch.float32)\r\n    assert torch.allclose(host_f, expected, rtol=1e-5, atol=1e-5)\r\n    assert abs(observed[0].item() - 5.0) < 1e-5, observed[0].item()\r\n    print(f\"callback ran — observed f[0] = {observed[0].item():.1f} (expected 5.0)\")\r\n\r\n\r\ndef show_missing_binding_error() -> None:\r\n    \"\"\"Omitting a required callback fails fast at prepare(), not at dispatch.\"\"\"\r\n    compiled = ir.compile(\r\n        InspectProgram,\r\n        platform=PLATFORM,\r\n        distributed_config=DistributedConfig(\r\n            device_ids=[0], num_sub_workers=1, block_dim=3, aicpu_thread_num=4\r\n        ),\r\n    )\r\n    try:\r\n        compiled.prepare()  # no callbacks → inspect_result is unbound\r\n    except ValueError as exc:\r\n        print(\"missing binding rejected at prepare():\", exc)\r\n    else:\r\n        raise AssertionError(\"expected prepare() to reject the missing callback\")\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    show_abstract_flag()\r\n    run_with_callback()\r\n    show_missing_binding_error()\r\n    print(\"OK\")\r\n","examples/runtime/explicit_dispatch.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"Explicit runtime dispatch with ChipWorker.run / register.\r\n\r\nThree end-to-end patterns showing how to use ChipWorker explicitly instead of\r\nrelying on ``with ChipWorker(): compiled(...)`` ContextVar discovery:\r\n\r\n  mode_a_inference_service — pre-register N compiled kernels, dispatch by name\r\n  mode_b_training_loop      — persistent weight DeviceTensor + hot register/run loop\r\n  mode_c_register_dispatch_overhead — register warms the callable cache once\r\n                                       (uses its own ChipWorker — see note in the mode)\r\n\r\nAll three modes use a ``@pl.jit`` kernel and the new\r\n:meth:`JITFunction.compile` entry point so the same script demonstrates:\r\n\r\n  1. ``my_kernel.compile(*sample_args) -> CompiledProgram`` (stage compile)\r\n  2. ``worker.register(compiled) -> RegistrationHandle`` (eager registration)\r\n  3. ``handle(*args)`` (dispatch — repeat in a hot loop)\r\n  4. Long-lived ``worker.alloc_tensor`` for weights / KV cache\r\n  5. ``worker.close()`` cleaning up cids + DeviceTensors in one shot\r\n\r\nRun:  python examples/runtime/explicit_dispatch.py\r\n\"\"\"\r\n\r\nfrom __future__ import annotations\r\n\r\nimport pypto.language as pl\r\nimport torch\r\nfrom pypto.runtime import ChipWorker, RunConfig\r\n\r\n# ---------------------------------------------------------------------------\r\n# Kernels (shared across the three modes)\r\n# ---------------------------------------------------------------------------\r\n\r\n\r\n@pl.jit\r\ndef tile_add_128(a: pl.Tensor, b: pl.Tensor, c: pl.Out[pl.Tensor]):\r\n    \"\"\"c = a + b on 128x128 fp32 tiles.\"\"\"\r\n    with pl.at(level=pl.Level.CORE_GROUP):\r\n        tile_a = pl.load(a, [0, 0], [128, 128])\r\n        tile_b = pl.load(b, [0, 0], [128, 128])\r\n        tile_c = pl.add(tile_a, tile_b)\r\n        pl.store(tile_c, [0, 0], c)\r\n    return c\r\n\r\n\r\n@pl.jit\r\ndef tile_mul_128(a: pl.Tensor, b: pl.Tensor, c: pl.Out[pl.Tensor]):\r\n    \"\"\"c = a * b on 128x128 fp32 tiles.\"\"\"\r\n    with pl.at(level=pl.Level.CORE_GROUP):\r\n        tile_a = pl.load(a, [0, 0], [128, 128])\r\n        tile_b = pl.load(b, [0, 0], [128, 128])\r\n        tile_c = pl.mul(tile_a, tile_b)\r\n        pl.store(tile_c, [0, 0], c)\r\n    return c\r\n\r\n\r\n# ---------------------------------------------------------------------------\r\n# Mode A — inference service: pre-register multiple kernels, dispatch by name\r\n# ---------------------------------------------------------------------------\r\n\r\n\r\ndef mode_a_inference_service(worker: ChipWorker) -> None:\r\n    \"\"\"Pattern: long-lived service holds one ``ChipWorker`` and a dict of\r\n    pre-registered handles. Per-request work is just ``handles[op](...)``.\r\n\r\n    Compile the JIT kernels once with sample args, ``worker.register`` each\r\n    CompiledProgram, then dispatch many times without re-checking the cid\r\n    cache.\r\n    \"\"\"\r\n    # Sample inputs only used to drive JIT specialization (shape/dtype only,\r\n    # values are not read by ``compile``).\r\n    sample = torch.zeros((128, 128), dtype=torch.float32)\r\n    handles = {\r\n        \"add\": worker.register(tile_add_128.compile(sample, sample, sample.clone())),\r\n        \"mul\": worker.register(tile_mul_128.compile(sample, sample, sample.clone())),\r\n    }\r\n\r\n    # Per-request dispatch — no cid lookup, no compile-and-assemble.\r\n    a = torch.full((128, 128), 2.0, dtype=torch.float32)\r\n    b = torch.full((128, 128), 3.0, dtype=torch.float32)\r\n    out = torch.zeros((128, 128), dtype=torch.float32)\r\n\r\n    handles[\"add\"](a, b, out)\r\n    assert torch.allclose(out, a + b, rtol=1e-5, atol=1e-5)\r\n\r\n    handles[\"mul\"](a, b, out)\r\n    assert torch.allclose(out, a * b, rtol=1e-5, atol=1e-5)\r\n\r\n    print(\"mode A OK — pre-registered handles dispatched correctly\")\r\n\r\n\r\n# ---------------------------------------------------------------------------\r\n# Mode B — training loop: persistent weight DeviceTensor, hot register/run loop\r\n# ---------------------------------------------------------------------------\r\n\r\n\r\ndef mode_b_training_loop(worker: ChipWorker) -> None:\r\n    \"\"\"Pattern: training / inference loop with a static weight tensor uploaded\r\n    to device once and reused across many dispatches.\r\n\r\n    ``worker.alloc_tensor(init=host_weight)`` performs malloc + H2D in one\r\n    rollback-safe step and tracks the DeviceTensor in ``worker._owned_tensors``\r\n    so ``worker.close()`` releases it even if the loop forgets ``free_tensor``.\r\n    \"\"\"\r\n    # Pretend ``host_weight`` is a per-model static buffer (e.g. an MLP weight).\r\n    host_weight = torch.full((128, 128), 0.5, dtype=torch.float32)\r\n    w_dev = worker.alloc_tensor(host_weight.shape, host_weight.dtype, init=host_weight)\r\n\r\n    # Compile the kernel once for the shape/dtype combination we'll dispatch\r\n    # with — DeviceTensor and torch.Tensor are interchangeable shape-wise.\r\n    sample = torch.zeros((128, 128), dtype=torch.float32)\r\n    compiled = tile_add_128.compile(sample, sample, sample.clone())\r\n    h = worker.register(compiled)\r\n\r\n    # Hot loop: per-step input + persistent weight + per-step output.\r\n    # The weight DeviceTensor has ``child_memory=True`` semantics — no H2D\r\n    # cost per step.\r\n    for step in range(5):\r\n        x = torch.full((128, 128), float(step), dtype=torch.float32)\r\n        out = torch.zeros((128, 128), dtype=torch.float32)\r\n        h(x, w_dev, out)\r\n        expected = x + host_weight\r\n        assert torch.allclose(out, expected, rtol=1e-5, atol=1e-5), f\"step {step} mismatch\"\r\n\r\n    # Explicit free even though ``worker.close()`` would auto-free —\r\n    # documented best practice (and shown in 00-getting_started.md caveats).\r\n    worker.free_tensor(w_dev)\r\n    print(\"mode B OK — 5 dispatches with persistent weight DeviceTensor\")\r\n\r\n\r\n# ---------------------------------------------------------------------------\r\n# Mode C — register warms the callable cache once\r\n# ---------------------------------------------------------------------------\r\n\r\n\r\ndef mode_c_register_dispatch_overhead() -> None:\r\n    \"\"\"Demonstrate that ``worker.register(compiled)`` triggers exactly one\r\n    AICPU dlopen for that callable, and subsequent ``handle(*args)`` calls\r\n    reuse it.\r\n\r\n    The diagnostic counter ``ChipWorker.aicpu_dlopen_count`` is a direct\r\n    passthrough to the underlying simpler worker — useful for benchmarking\r\n    and for verifying the cid cache is doing its job.\r\n\r\n    **Uses its own ChipWorker** rather than sharing with the other modes:\r\n    ``ChipWorker._cid_cache`` is keyed by ``id(chip_callable)``, so once\r\n    ``tile_add_128`` is registered on a worker (e.g. by ``mode_a`` above),\r\n    a second ``worker.register`` of the same kernel would be a cache hit\r\n    and would NOT bump ``aicpu_dlopen_count``. A fresh worker guarantees\r\n    the first ``register`` is observable.\r\n    \"\"\"\r\n    worker = ChipWorker(config=RunConfig())\r\n    try:\r\n        before = worker.aicpu_dlopen_count\r\n\r\n        sample = torch.zeros((128, 128), dtype=torch.float32)\r\n        compiled = tile_add_128.compile(sample, sample, sample.clone())\r\n        h = worker.register(compiled)\r\n\r\n        after_register = worker.aicpu_dlopen_count\r\n\r\n        a = torch.full((128, 128), 1.0, dtype=torch.float32)\r\n        b = torch.full((128, 128), 2.0, dtype=torch.float32)\r\n        out = torch.zeros((128, 128), dtype=torch.float32)\r\n        for _ in range(20):\r\n            h(a, b, out)\r\n\r\n        after_runs = worker.aicpu_dlopen_count\r\n\r\n        assert after_register == before + 1, (\r\n            f\"register should dlopen exactly once: before={before}, after_register={after_register}\"\r\n        )\r\n        assert after_runs == after_register, (\r\n            f\"20 dispatches should not re-dlopen: after_register={after_register}, after_runs={after_runs}\"\r\n        )\r\n        print(\r\n            f\"mode C OK — aicpu_dlopen_count: \"\r\n            f\"{before} -> {after_register} (1 register) -> {after_runs} (20 runs)\"\r\n        )\r\n    finally:\r\n        worker.close()\r\n\r\n\r\n# ---------------------------------------------------------------------------\r\n# Entry point — run all three modes against one worker\r\n# ---------------------------------------------------------------------------\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    # Modes A and B share a worker (init / close amortised); mode C uses\r\n    # its own to keep the ``aicpu_dlopen_count`` assertion meaningful.\r\n    # ``RunConfig()`` picks the default simulator platform; pass\r\n    # ``RunConfig(platform=\"a2a3\")`` to target a real device.\r\n    worker = ChipWorker(config=RunConfig())\r\n    try:\r\n        mode_a_inference_service(worker)\r\n        mode_b_training_loop(worker)\r\n    finally:\r\n        worker.close()\r\n\r\n    mode_c_register_dispatch_overhead()\r\n\r\n    print(\"OK\")\r\n","examples/runtime/multi_program_kv_cache.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"Multi-program L3 dispatch sharing one worker and one resident KV cache (JIT style).\r\n\r\nServing skeleton (Qwen3-style): ``prefill`` and ``decode`` are two separate\r\n``@pl.jit.host`` kernels that must share **one** L3 worker and **one**\r\nworker-resident :class:`~pypto.runtime.DeviceTensor` KV cache. ``prefill``\r\nwrites the KV cache once; each ``decode`` step reads and updates it — so the KV\r\ncache must survive across dispatches from *different* compiled programs, which a\r\nworker-per-program design cannot do.\r\n\r\nKey APIs:\r\n\r\n  1. ``@pl.jit.host`` → ``@pl.jit`` (chip orch) → ``@pl.jit.incore`` — the JIT\r\n     three-level L3 kernel; shapes specialize from the sample args.\r\n  2. ``kernel.compile(*sample_args, config=RunConfig(distributed_config=...))``\r\n     — compile without dispatching; returns a ``DistributedCompiledProgram``.\r\n  3. ``DistributedWorker([prefill, decode])`` — prepare both programs on one\r\n     worker (or, symmetrically, ``prefill.prepare(extra_compiled=[decode])``).\r\n  4. ``rt.alloc_tensor(...)`` — a resident KV-cache DeviceTensor, valid across\r\n     dispatches from either program.\r\n  5. ``rt.run(compiled, *args)`` — pick which prepared program to dispatch.\r\n     ``rt(*args)`` is intentionally disabled in multi-program mode (ambiguous).\r\n  6. ``rt.close()`` — release the worker + all DeviceTensors in one shot.\r\n\r\nTo keep the math trivial and the focus on the dispatch/sharing API:\r\n\r\n  prefill:  kv = prompt + prompt            (writes the KV cache)\r\n  decode:   logits = token + kv             (reads the KV cache, per step)\r\n\r\nThis needs a real device + the ``simpler`` runtime; without one it prints a\r\nskip notice instead of failing.\r\n\r\nRun:  python examples/runtime/multi_program_kv_cache.py\r\n\"\"\"\r\n\r\nfrom __future__ import annotations\r\n\r\nimport pypto.language as pl\r\nimport torch\r\nfrom pypto.ir.distributed_compiled_program import DistributedCompiledProgram, DistributedConfig\r\nfrom pypto.runtime import DistributedWorker, RunConfig\r\n\r\nTILE = 128\r\n\r\n\r\n# ---------------------------------------------------------------------------\r\n# Program 1 — prefill: write the KV cache (kv = prompt + prompt)\r\n# ---------------------------------------------------------------------------\r\n\r\n\r\n@pl.jit.incore\r\ndef write_kv(prompt: pl.Tensor, kv: pl.Out[pl.Tensor]):\r\n    tile_p = pl.load(prompt, [0, 0], [TILE, TILE])\r\n    tile_kv = pl.add(tile_p, tile_p)\r\n    return pl.store(tile_kv, [0, 0], kv)\r\n\r\n\r\n@pl.jit\r\ndef prefill_chip(prompt: pl.Tensor, kv: pl.Out[pl.Tensor]):\r\n    out_kv = write_kv(prompt, kv)\r\n    return out_kv\r\n\r\n\r\n@pl.jit.host\r\ndef prefill(prompt: pl.Tensor, kv: pl.Out[pl.Tensor]):\r\n    out_kv = prefill_chip(prompt, kv)\r\n    return out_kv\r\n\r\n\r\n# ---------------------------------------------------------------------------\r\n# Program 2 — decode: read the KV cache (logits = token + kv)\r\n# ---------------------------------------------------------------------------\r\n\r\n\r\n@pl.jit.incore\r\ndef read_kv(token: pl.Tensor, kv: pl.Tensor, logits: pl.Out[pl.Tensor]):\r\n    tile_t = pl.load(token, [0, 0], [TILE, TILE])\r\n    tile_kv = pl.load(kv, [0, 0], [TILE, TILE])\r\n    tile_o = pl.add(tile_t, tile_kv)\r\n    return pl.store(tile_o, [0, 0], logits)\r\n\r\n\r\n@pl.jit\r\ndef decode_chip(token: pl.Tensor, kv: pl.Tensor, logits: pl.Out[pl.Tensor]):\r\n    out = read_kv(token, kv, logits)\r\n    return out\r\n\r\n\r\n@pl.jit.host\r\ndef decode(token: pl.Tensor, kv: pl.Tensor, logits: pl.Out[pl.Tensor]):\r\n    out = decode_chip(token, kv, logits)\r\n    return out\r\n\r\n\r\n# ---------------------------------------------------------------------------\r\n# Serving loop — one worker, one resident KV cache, two programs\r\n# ---------------------------------------------------------------------------\r\n\r\n\r\ndef serve(platform: str = \"a2a3\", device_ids: list[int] | None = None) -> None:\r\n    dc = DistributedConfig(device_ids=device_ids or [0], num_sub_workers=0, block_dim=3)\r\n    cfg = RunConfig(platform=platform, distributed_config=dc)\r\n\r\n    # Per-call IO buffers must be shared-memory host tensors allocated BEFORE the\r\n    # worker forks, so the chip worker sees them through the inherited mapping.\r\n    host_prompt = torch.full((TILE, TILE), 2.0, dtype=torch.float32).share_memory_()\r\n    host_token = torch.zeros((TILE, TILE), dtype=torch.float32).share_memory_()\r\n    host_logits = torch.zeros((TILE, TILE), dtype=torch.float32).share_memory_()\r\n\r\n    # compile() specializes on the sample shapes/dtypes without dispatching;\r\n    # passing distributed_config makes it return a DistributedCompiledProgram\r\n    # (assert to narrow the CompiledProgram | DistributedCompiledProgram union).\r\n    kv_sample = torch.zeros((TILE, TILE), dtype=torch.float32)\r\n    prefill_c = prefill.compile(host_prompt, kv_sample, config=cfg)\r\n    decode_c = decode.compile(host_token, kv_sample, host_logits, config=cfg)\r\n    assert isinstance(prefill_c, DistributedCompiledProgram)\r\n    assert isinstance(decode_c, DistributedCompiledProgram)\r\n\r\n    # Both programs prepared on ONE worker. Equivalent symmetric form:\r\n    #   with prefill_c.prepare(extra_compiled=[decode_c]) as rt:\r\n    with DistributedWorker([prefill_c, decode_c]) as rt:\r\n        # Resident KV cache: written by prefill, read by every decode step.\r\n        kv_cache = rt.alloc_tensor((TILE, TILE), torch.float32)\r\n\r\n        rt.run(prefill_c, host_prompt, kv_cache)  # kv_cache = 2 * prompt = 4.0\r\n\r\n        for step in range(3):\r\n            host_token.fill_(float(step))  # refresh per-step input in place\r\n            host_logits.zero_()\r\n            rt.run(decode_c, host_token, kv_cache, host_logits)  # logits = token + kv\r\n\r\n            expected = torch.full((TILE, TILE), float(step) + 4.0, dtype=torch.float32)\r\n            torch.testing.assert_close(host_logits, expected, rtol=1e-5, atol=1e-5)\r\n\r\n        rt.free_tensor(kv_cache)\r\n\r\n    print(\"OK — prefill wrote the KV cache; 3 decode steps read it on one shared worker\")\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    # L3 distributed dispatch needs a real device + the ``simpler`` runtime.\r\n    # Pass the platform / device ids your host exposes (e.g. serve(\"a2a3\", [0])).\r\n    try:\r\n        serve()\r\n    except Exception as exc:  # noqa: BLE001 — example: degrade gracefully without a device\r\n        print(f\"skipped (needs a device + simpler runtime): {type(exc).__name__}: {exc}\")\r\n","examples/runtime/__init__.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"User-facing examples for the explicit runtime dispatch APIs.\r\n\r\nSee :mod:`pypto.runtime.ChipWorker` for the dispatch surface used here:\r\n``run(compiled, *args)`` for one-shot dispatch and ``register(compiled)``\r\nreturning a :class:`~pypto.runtime.RegistrationHandle` for hot loops.\r\n\r\nExamples in this directory:\r\n\r\n- ``explicit_dispatch.py`` — three end-to-end patterns:\r\n   * ``mode_a_inference_service``: pre-register multiple compiled kernels and\r\n     dispatch by name (recommended for serving runtimes).\r\n   * ``mode_b_training_loop``: long-lived weight ``DeviceTensor`` + per-step\r\n     inputs, hot loop on a single registration handle.\r\n   * ``mode_c_register_dispatch_overhead``: verify that ``register`` warms the\r\n     callable cache once (``aicpu_dlopen_count`` does not grow per dispatch).\r\n\"\"\"\r\n","examples/utils/cross_function_calls.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"Cross-function composition with @pl.jit.\r\n\r\nDemonstrates that ``@pl.jit.inline`` helpers are auto-discovered as deps of a\r\n``@pl.jit`` entry function and spliced at the call site. Each helper is a normal\r\nDSL function; the entry composes them by calling them like Python functions.\r\n\r\nThis is the @pl.jit equivalent of the older ``@pl.program`` + ``self.method()``\r\ncross-function-call pattern: in the JIT world, dep discovery happens through the\r\nentry function's globals, not through a class.\r\n\"\"\"\r\n\r\nimport pypto.language as pl\r\n\r\n\r\n@pl.jit.inline\r\ndef add_helper(a: pl.Tensor, c: pl.Out[pl.Tensor]):\r\n    \"\"\"Tile-wise add: c = a + 1.0.\"\"\"\r\n    with pl.at(level=pl.Level.CORE_GROUP):\r\n        tile_a = pl.load(a, [0, 0], [128, 128])\r\n        tile_c = pl.add(tile_a, 1.0)\r\n        pl.store(tile_c, [0, 0], c)\r\n    return c\r\n\r\n\r\n@pl.jit.inline\r\ndef mul_helper(a: pl.Tensor, c: pl.Out[pl.Tensor]):\r\n    \"\"\"Tile-wise multiply: c = a * 2.0.\"\"\"\r\n    with pl.at(level=pl.Level.CORE_GROUP):\r\n        tile_a = pl.load(a, [0, 0], [128, 128])\r\n        tile_c = pl.mul(tile_a, 2.0)\r\n        pl.store(tile_c, [0, 0], c)\r\n    return c\r\n\r\n\r\n@pl.jit\r\ndef main_kernel(a: pl.Tensor, c: pl.Out[pl.Tensor]):\r\n    \"\"\"Entry: c = (a + 1.0) * 2.0, composed via two @pl.jit.inline helpers.\"\"\"\r\n    intermediate = pl.create_tensor([128, 128], dtype=pl.FP32)\r\n    intermediate = add_helper(a, intermediate)\r\n    c = mul_helper(intermediate, c)\r\n    return c\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    import torch\r\n\r\n    a = torch.randn(128, 128, dtype=torch.float32)\r\n    c = torch.zeros(128, 128, dtype=torch.float32)\r\n    prog = main_kernel.compile_for_test(a, c)\r\n    print(f\"main_kernel: {len(prog.functions)} fn(s)\")\r\n    for fn in prog.functions.values():\r\n        print(f\"  {fn.name}: {fn.func_type}\")\r\n","examples/utils/error_handling.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"Demonstrates that the @pl.jit pipeline rejects an invalid kernel at compile time.\r\n\r\nThe body rebinds ``result`` to ``pl.add(x, 1.0)``, discarding the prior write\r\nof ``pl.mul(x, 2.0)``. The JIT specializer alpha-renames the rebinding to keep\r\nthe parser happy, but downstream codegen still surfaces a structural error\r\nbecause the renamed local never reaches the ``pl.store`` (out parameter).\r\n\"\"\"\r\n\r\nimport pypto.language as pl\r\n\r\n\r\n@pl.jit\r\ndef test_ssa_violation(x: pl.Tensor, result: pl.Out[pl.Tensor]):\r\n    with pl.at(level=pl.Level.CORE_GROUP):\r\n        result = pl.mul(x, 2.0)\r\n        result = pl.add(x, 1.0)  # rebinding -- discards the prior write to result\r\n    return result\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    import sys\r\n\r\n    import torch\r\n    from pypto.backend.pto_backend import PartialCodegenError\r\n    from pypto.runtime import RunConfig\r\n\r\n    x = torch.randn(64, dtype=torch.float32)\r\n    result = torch.zeros_like(x)\r\n    try:\r\n        test_ssa_violation(x, result, config=RunConfig())\r\n        print(\"ERROR: expected the invalid kernel to be rejected\")\r\n        sys.exit(1)\r\n    except PartialCodegenError as e:\r\n        print(f\"OK -- caught expected error: {type(e).__name__}\")\r\n","examples/utils/parse_from_text.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"\r\nExample demonstrating pl.parse() and pl.loads() for parsing DSL functions from text/files.\r\n\r\nThis example shows how to:\r\n1. Parse DSL functions from inline code strings using pl.parse()\r\n2. Load DSL functions from external files using pl.loads()\r\n3. Handle errors during parsing\r\n4. Use cases for dynamic code generation and loading kernels\r\n\"\"\"\r\n\r\nimport os\r\nimport tempfile\r\nfrom typing import cast\r\n\r\nimport pypto\r\nimport pypto.language as pl\r\n\r\n\r\ndef example_parse_from_string():\r\n    \"\"\"Example 1: Parse a DSL function from an inline string.\"\"\"\r\n    print(\"=\" * 70)\r\n    print(\"Example 1: Parse from inline string\")\r\n    print(\"=\" * 70)\r\n\r\n    # Define DSL code as a string\r\n    code = \"\"\"\r\n@pl.function\r\ndef vector_add(\r\n    x: pl.Tensor[[128], pl.FP32],\r\n    y: pl.Tensor[[128], pl.FP32],\r\n) -> pl.Tensor[[128], pl.FP32]:\r\n    result: pl.Tensor[[128], pl.FP32] = pl.add(x, y)\r\n    return result\r\n\"\"\"\r\n\r\n    # Parse the function\r\n    func = cast(pypto.ir.Function, pl.parse(code))\r\n\r\n    print(f\"Parsed function: {func.name}\")\r\n    print(f\"Number of parameters: {len(func.params)}\")\r\n    print(f\"Number of return types: {len(func.return_types)}\")\r\n    print(\"\\nFunction IR:\")\r\n    print(func.as_python())\r\n    print()\r\n\r\n\r\ndef example_parse_without_import():\r\n    \"\"\"Example 2: Parse DSL code without import statement (auto-injected).\"\"\"\r\n    print(\"=\" * 70)\r\n    print(\"Example 2: Parse without import (auto-injected)\")\r\n    print(\"=\" * 70)\r\n\r\n    # Notice: no \"import pypto.language as pl\" in the code\r\n    code = \"\"\"\r\n@pl.function\r\ndef vector_mul(x: pl.Tensor[[64], pl.FP32]) -> pl.Tensor[[64], pl.FP32]:\r\n    result: pl.Tensor[[64], pl.FP32] = pl.mul(x, 2.0)\r\n    return result\r\n\"\"\"\r\n\r\n    func = pl.parse(code)\r\n    print(f\"Parsed function: {func.name}\")\r\n    print(\"✓ Import statement was automatically injected\")\r\n    print()\r\n\r\n\r\ndef example_load_from_file():\r\n    \"\"\"Example 3: Load a DSL function from a file.\"\"\"\r\n    print(\"=\" * 70)\r\n    print(\"Example 3: Load from file\")\r\n    print(\"=\" * 70)\r\n\r\n    # Create a temporary file with DSL code\r\n    code = \"\"\"\r\nimport pypto.language as pl\r\n\r\n@pl.function\r\ndef matrix_transpose(x: pl.Tensor[[64, 128], pl.FP16]) -> pl.Tensor[[128, 64], pl.FP16]:\r\n    # Example: simplified transpose operation\r\n    result: pl.Tensor[[128, 64], pl.FP16] = pl.slice(x, [128, 64], [1, 0])\r\n    return result\r\n\"\"\"\r\n\r\n    with tempfile.NamedTemporaryFile(mode=\"w\", suffix=\".py\", delete=False) as f:\r\n        f.write(code)\r\n        temp_path = f.name\r\n\r\n    try:\r\n        # Load the function from file\r\n        func = cast(pypto.ir.Function, pl.loads(temp_path))\r\n        print(f\"Loaded function from: {temp_path}\")\r\n        print(f\"Function name: {func.name}\")\r\n        print(f\"Parameters: {len(func.params)}\")\r\n        print()\r\n    finally:\r\n        # Clean up\r\n\r\n        os.unlink(temp_path)\r\n\r\n\r\ndef example_complex_function():\r\n    \"\"\"Example 4: Parse a complex function with control flow.\"\"\"\r\n    print(\"=\" * 70)\r\n    print(\"Example 4: Parse complex function with control flow\")\r\n    print(\"=\" * 70)\r\n\r\n    code = \"\"\"\r\n@pl.function\r\ndef accumulate(\r\n    x: pl.Tensor[[10], pl.FP32],\r\n    iterations: pl.Tensor[[1], pl.INT32],\r\n) -> pl.Tensor[[10], pl.FP32]:\r\n    # Initialize accumulator\r\n    init_sum: pl.Tensor[[10], pl.FP32] = pl.create_tensor([10], dtype=pl.FP32)\r\n\r\n    # Accumulate over iterations\r\n    for i, (running_sum,) in pl.range(5, init_values=(init_sum,)):\r\n        new_sum: pl.Tensor[[10], pl.FP32] = pl.add(running_sum, x)\r\n        result = pl.yield_(new_sum)\r\n\r\n    return result\r\n\"\"\"\r\n\r\n    func = pl.parse(code)\r\n    print(f\"Parsed function: {func.name}\")\r\n    print(\"✓ Function includes for loop control flow\")\r\n    print(\"\\nFunction IR:\")\r\n    print(func.as_python())\r\n    print()\r\n\r\n\r\ndef example_error_handling():\r\n    \"\"\"Example 5: Handle parsing errors.\"\"\"\r\n    print(\"=\" * 70)\r\n    print(\"Example 5: Error handling\")\r\n    print(\"=\" * 70)\r\n\r\n    # Example 5a: No function defined\r\n    print(\"5a. Code with no @pl.function:\")\r\n    code_no_func = \"\"\"\r\nx = 42\r\ny = x + 1\r\n\"\"\"\r\n    try:\r\n        pl.parse(code_no_func)\r\n    except ValueError as e:\r\n        print(f\"✓ Caught expected error: {e}\")\r\n        print()\r\n\r\n    # Example 5b: Multiple functions\r\n    print(\"5b. Code with multiple functions:\")\r\n    code_multi_func = \"\"\"\r\n@pl.function\r\ndef func1(x: pl.Tensor[[64], pl.FP32]) -> pl.Tensor[[64], pl.FP32]:\r\n    return x\r\n\r\n@pl.function\r\ndef func2(x: pl.Tensor[[64], pl.FP32]) -> pl.Tensor[[64], pl.FP32]:\r\n    return x\r\n\"\"\"\r\n    try:\r\n        pl.parse(code_multi_func)\r\n    except ValueError as e:\r\n        print(f\"✓ Caught expected error: {e}\")\r\n        print()\r\n\r\n    # Example 5c: Syntax error\r\n    print(\"5c. Code with syntax error:\")\r\n    code_syntax_error = \"\"\"\r\n@pl.function\r\ndef bad_syntax(x: pl.Tensor[[64], pl.FP32]) -> pl.Tensor[[64], pl.FP32]:\r\n    return x +\r\n\"\"\"\r\n    try:\r\n        pl.parse(code_syntax_error)\r\n    except SyntaxError as e:\r\n        print(f\"✓ Caught expected error: {type(e).__name__}\")\r\n        print()\r\n\r\n\r\ndef example_use_case_dynamic_generation():\r\n    \"\"\"Example 6: Use case - Dynamic code generation.\"\"\"\r\n    print(\"=\" * 70)\r\n    print(\"Example 6: Use case - Dynamic kernel generation\")\r\n    print(\"=\" * 70)\r\n\r\n    # Simulate generating kernels from a template\r\n    def generate_elementwise_kernel(operation: str, op_func: str) -> str:\r\n        \"\"\"Generate an elementwise operation kernel from a template.\"\"\"\r\n        return f\"\"\"\r\n@pl.function\r\ndef elementwise_{operation}(\r\n    x: pl.Tensor[[1024], pl.FP32],\r\n    y: pl.Tensor[[1024], pl.FP32],\r\n) -> pl.Tensor[[1024], pl.FP32]:\r\n    result: pl.Tensor[[1024], pl.FP32] = pl.{op_func}(x, y)\r\n    return result\r\n\"\"\"\r\n\r\n    # Generate and parse different kernels\r\n    operations = [\r\n        (\"add\", \"add\"),\r\n        (\"subtract\", \"sub\"),\r\n        (\"multiply\", \"mul\"),\r\n    ]\r\n\r\n    for op_name, op_func in operations:\r\n        code = generate_elementwise_kernel(op_name, op_func)\r\n        func = pl.parse(code)\r\n        print(f\"✓ Generated and parsed: {func.name}\")\r\n\r\n    print(\"\\n💡 This pattern is useful for:\")\r\n    print(\"   - Generating specialized kernels from configuration\")\r\n    print(\"   - Loading kernel implementations from a database\")\r\n    print(\"   - Building domain-specific code generators\")\r\n    print()\r\n\r\n\r\ndef example_serialization():\r\n    \"\"\"Example 7: Serialize parsed functions.\"\"\"\r\n    print(\"=\" * 70)\r\n    print(\"Example 7: Serialize parsed functions\")\r\n    print(\"=\" * 70)\r\n\r\n    code = \"\"\"\r\n@pl.function\r\ndef simple_add(x: pl.Tensor[[32], pl.FP32]) -> pl.Tensor[[32], pl.FP32]:\r\n    result: pl.Tensor[[32], pl.FP32] = pl.add(x, 1.0)\r\n    return result\r\n\"\"\"\r\n\r\n    # Parse function\r\n    func = pl.parse(code)\r\n    print(f\"Parsed function: {func.name}\")\r\n\r\n    # Serialize to msgpack\r\n    data = pypto.ir.serialize(func)\r\n    print(f\"✓ Serialized to {len(data)} bytes\")\r\n\r\n    # Deserialize\r\n    restored = cast(pypto.ir.Function, pypto.ir.deserialize(data))\r\n    print(f\"✓ Deserialized function: {restored.name}\")\r\n    print(\"\\n💡 Parsed functions can be serialized just like decorated functions\")\r\n    print()\r\n\r\n\r\ndef main():\r\n    \"\"\"Run all examples.\"\"\"\r\n    print(\"\\n\")\r\n    print(\"╔\" + \"═\" * 68 + \"╗\")\r\n    print(\"║\" + \" \" * 15 + \"pl.parse() and pl.loads() Examples\" + \" \" * 20 + \"║\")\r\n    print(\"╚\" + \"═\" * 68 + \"╝\")\r\n    print()\r\n\r\n    example_parse_from_string()\r\n    example_parse_without_import()\r\n    example_load_from_file()\r\n    example_complex_function()\r\n    example_error_handling()\r\n    example_use_case_dynamic_generation()\r\n    example_serialization()\r\n\r\n    print(\"=\" * 70)\r\n    print(\"All examples completed successfully! ✓\")\r\n    print(\"=\" * 70)\r\n    print()\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    main()\r\n","examples/utils/phase_fence_dep_compression.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"Manual phase-fence dependency compression example.\r\n\r\nThe chained snapshot program submits four flattened stages. Each stage fans out\r\nover ``branches`` tasks, records their ``TaskId`` values in an array, and uses\r\nthat array as the full-array manual dependency for the next stage.\r\n\r\nThis example intentionally uses ``@pl.program`` because ``pl.submit`` takes\r\n``self.<kernel>`` method references.\r\n\"\"\"\r\n\r\nimport pypto.language as pl\r\n\r\nDEFAULT_BRANCHES = 4\r\nTILE_M = 32\r\nBIG_N = 32\r\n\r\n\r\ndef chained_snapshot_shape(*, branches: int = DEFAULT_BRANCHES) -> tuple[int, int]:\r\n    \"\"\"Return the input/output tensor shape for the chained snapshot example.\r\n\r\n    Args:\r\n        branches: Number of parallel branches in each flattened stage.\r\n\r\n    Returns:\r\n        Tensor shape as ``(rows, cols)``.\r\n\r\n    Raises:\r\n        ValueError: If ``branches`` is not positive.\r\n    \"\"\"\r\n    if branches <= 0:\r\n        raise ValueError(f\"branches must be positive, got {branches}\")\r\n    return 4 * branches * TILE_M, BIG_N\r\n\r\n\r\ndef build_chained_snapshot_phase_fence(*, branches: int = DEFAULT_BRANCHES):\r\n    \"\"\"Build a chained manual-scope phase-fence program.\r\n\r\n    Args:\r\n        branches: Number of parallel branches in each flattened stage.\r\n\r\n    Returns:\r\n        A ``@pl.program`` class that can be compiled or run by PyPTO tooling.\r\n    \"\"\"\r\n    big_m, big_n = chained_snapshot_shape(branches=branches)\r\n    tile_m = TILE_M\r\n\r\n    @pl.program\r\n    class ChainedSnapshotPhaseFence:\r\n        @pl.function(type=pl.FunctionType.InCore)\r\n        def kernel_stripe(\r\n            self,\r\n            data: pl.Tensor[[big_m, big_n], pl.FP32],\r\n            row_offset: pl.Scalar[pl.INDEX],\r\n            bias: pl.Scalar[pl.FP32],\r\n            out: pl.Out[pl.Tensor[[big_m, big_n], pl.FP32]],\r\n        ) -> pl.Tensor[[big_m, big_n], pl.FP32]:\r\n            tile: pl.Tile[[tile_m, big_n], pl.FP32] = pl.load(data, [row_offset, 0], [tile_m, big_n])\r\n            result: pl.Tile[[tile_m, big_n], pl.FP32] = pl.add(tile, bias)\r\n            ret: pl.Tensor[[big_m, big_n], pl.FP32] = pl.store(result, [row_offset, 0], out)\r\n            return ret\r\n\r\n        @pl.function(type=pl.FunctionType.Orchestration)\r\n        def main(\r\n            self,\r\n            data: pl.Tensor[[big_m, big_n], pl.FP32],\r\n            out: pl.Out[pl.Tensor[[big_m, big_n], pl.FP32]],\r\n        ) -> pl.Tensor[[big_m, big_n], pl.FP32]:\r\n            with pl.manual_scope():\r\n                tids = pl.array.create(branches, pl.TASK_ID)\r\n                for a_phase, (tids_a,) in pl.range(2, init_values=(tids,)):\r\n                    tids_next = pl.array.create(branches, pl.TASK_ID)\r\n                    for branch in pl.parallel(branches):\r\n                        row: pl.Scalar[pl.INDEX] = (a_phase * branches + branch) * tile_m\r\n                        out, tid = pl.submit(self.kernel_stripe, data, row, 1.0, out, deps=[tids_a])\r\n                        tids_next[branch] = tid\r\n                    tids = pl.yield_(tids_next)\r\n                for b_phase, (tids_b,) in pl.range(2, init_values=(tids,)):\r\n                    tids_next = pl.array.create(branches, pl.TASK_ID)\r\n                    for branch in pl.parallel(branches):\r\n                        row: pl.Scalar[pl.INDEX] = ((2 + b_phase) * branches + branch) * tile_m\r\n                        out, tid = pl.submit(self.kernel_stripe, data, row, 1.0, out, deps=[tids_b])\r\n                        tids_next[branch] = tid\r\n                    tids = pl.yield_(tids_next)\r\n            return out\r\n\r\n    return ChainedSnapshotPhaseFence\r\n\r\n\r\ndef build_chained_snapshot_manual_dummy_phase_fence(*, branches: int = DEFAULT_BRANCHES):\r\n    \"\"\"Build a chained phase-fence program with explicit dummy-task barriers.\r\n\r\n    Args:\r\n        branches: Number of parallel branches in each flattened stage.\r\n\r\n    Returns:\r\n        A ``@pl.program`` class that can be compiled or run by PyPTO tooling.\r\n    \"\"\"\r\n    big_m, big_n = chained_snapshot_shape(branches=branches)\r\n    tile_m = TILE_M\r\n\r\n    @pl.program\r\n    class ChainedSnapshotManualDummyPhaseFence:\r\n        @pl.function(type=pl.FunctionType.InCore)\r\n        def kernel_stripe(\r\n            self,\r\n            data: pl.Tensor[[big_m, big_n], pl.FP32],\r\n            row_offset: pl.Scalar[pl.INDEX],\r\n            bias: pl.Scalar[pl.FP32],\r\n            out: pl.Out[pl.Tensor[[big_m, big_n], pl.FP32]],\r\n        ) -> pl.Tensor[[big_m, big_n], pl.FP32]:\r\n            tile: pl.Tile[[tile_m, big_n], pl.FP32] = pl.load(data, [row_offset, 0], [tile_m, big_n])\r\n            result: pl.Tile[[tile_m, big_n], pl.FP32] = pl.add(tile, bias)\r\n            ret: pl.Tensor[[big_m, big_n], pl.FP32] = pl.store(result, [row_offset, 0], out)\r\n            return ret\r\n\r\n        @pl.function(type=pl.FunctionType.Orchestration)\r\n        def main(\r\n            self,\r\n            data: pl.Tensor[[big_m, big_n], pl.FP32],\r\n            out: pl.Out[pl.Tensor[[big_m, big_n], pl.FP32]],\r\n        ) -> pl.Tensor[[big_m, big_n], pl.FP32]:\r\n            with pl.manual_scope():\r\n                tids = pl.array.create(branches, pl.TASK_ID)\r\n                for a_phase, (tids_a,) in pl.range(2, init_values=(tids,)):\r\n                    tids_next = pl.array.create(branches, pl.TASK_ID)\r\n                    deps = pl.system.task_dummy(deps=[tids_a])\r\n                    for branch in pl.parallel(branches):\r\n                        row: pl.Scalar[pl.INDEX] = (a_phase * branches + branch) * tile_m\r\n                        out, tid = pl.submit(self.kernel_stripe, data, row, 1.0, out, deps=[deps])\r\n                        tids_next[branch] = tid\r\n                    tids = pl.yield_(tids_next)\r\n                for b_phase, (tids_b,) in pl.range(2, init_values=(tids,)):\r\n                    tids_next = pl.array.create(branches, pl.TASK_ID)\r\n                    deps = pl.system.task_dummy(deps=[tids_b])\r\n                    for branch in pl.parallel(branches):\r\n                        row: pl.Scalar[pl.INDEX] = ((2 + b_phase) * branches + branch) * tile_m\r\n                        out, tid = pl.submit(self.kernel_stripe, data, row, 1.0, out, deps=[deps])\r\n                        tids_next[branch] = tid\r\n                    tids = pl.yield_(tids_next)\r\n            return out\r\n\r\n    return ChainedSnapshotManualDummyPhaseFence\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    rows, cols = chained_snapshot_shape()\r\n    for builder in (build_chained_snapshot_phase_fence, build_chained_snapshot_manual_dummy_phase_fence):\r\n        program = builder()\r\n        print(f\"{program.name}: shape=({rows}, {cols}), branches={DEFAULT_BRANCHES}\")\r\n        for fn in program.functions.values():\r\n            print(f\"  {fn.name}: {fn.func_type}\")\r\n","examples/utils/__init__.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"\r\nUtility examples — parsing, cross-function calls, error handling.\r\n\r\n  - parse_from_text.py      — pl.parse() and pl.loads() guide\r\n  - cross_function_calls.py — @pl.jit cross-function calls\r\n  - phase_fence_dep_compression.py — manual_scope phase-fence dependency compression example\r\n  - error_handling.py       — SSA violation detection\r\n\"\"\"\r\n","examples/__init__.py":"# Copyright (c) PyPTO Contributors.\r\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\r\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\r\n# Please refer to the License for details. You may not use this file except in compliance with the License.\r\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\r\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\r\n# See LICENSE in the root of the software repository for the full text of the License.\r\n# -----------------------------------------------------------------------------------------------------------\r\n\r\n\"\"\"\r\nPyPTO Examples — organized from easy to hard.\r\n\r\n  0. hello_world.py — simplest program: 128x128 add (start here)\r\n  1. kernels/       — single-kernel programs (elementwise, matmul, softmax, ...)\r\n  2. models/        — multi-kernel programs with orchestration (FFN, attention, ...)\r\n  3. utils/         — parsing, cross-function calls, error handling\r\n\r\nSee each folder's __init__.py for detailed reading order within.\r\n\"\"\"\r\n"};
